window.ETSDATA=window.ETSDATA||{};window.ETSDATA[12]={"lc":{"p1":[{"n":1,"opts":["She's inserting a cord into an outlet.","She's pressing a button on a machine.","She's gripping the handle of a drawer.","She's tacking a notice onto the wall."],"vi":["Cô ấy đang cắm dây điện vào ổ cắm.","Cô ấy đang nhấn nút trên một cái máy.","Cô ấy đang nắm tay cầm của ngăn kéo.","Cô ấy đang ghim một tờ thông báo lên tường."],"ans":"A","xp":"Người trong ảnh đang đưa tay cắm dây điện vào ổ cắm trên tường → (A) đúng. (B) không nhấn nút máy, (C) không nắm tay cầm ngăn kéo, (D) không ghim thông báo lên tường.","a":"E24-T02-01.mp3","img":"q1.jpg"},{"n":2,"opts":["Some window shutters are being replaced.","A pillow is being arranged on a seat.","An outdoor table is being cleared off.","Some wooden boards are being painted."],"vi":["Mấy cánh cửa chớp đang được thay.","Một chiếc gối đang được sắp xếp trên ghế.","Một chiếc bàn ngoài trời đang được dọn sạch.","Mấy tấm ván gỗ đang được sơn."],"ans":"B","xp":"Người phụ nữ đang đặt chiếc gối (pillow) lên ghế → (B) đúng. Không ai thay cửa chớp (A), dọn bàn (C) hay sơn ván gỗ (D).","a":"E24-T02-02.mp3","img":"q2.jpg"},{"n":3,"opts":["Some utensils have been discarded in a bin.","Some bottles are being emptied into a sink.","A rolling chair has been placed next to a counter.","Some drawers have been left open."],"vi":["Một số dụng cụ đã bị vứt vào thùng rác.","Mấy cái chai đang được đổ vào bồn rửa.","Một chiếc ghế có bánh xe đã được đặt cạnh quầy.","Mấy ngăn kéo đang bị để mở."],"ans":"C","xp":"Trong ảnh có chiếc ghế có bánh xe (rolling chair) đặt cạnh quầy (counter) → (C) đúng. (A), (B) nhắc đến thùng rác, bồn rửa không có trong ảnh; (D) sai vì các ngăn kéo đều đóng.","a":"E24-T02-03.mp3","img":"q3.jpg"},{"n":4,"opts":["A man is chopping some wood into pieces.","Leaves are scattered across the grass.","A man is closing a window.","Wood is piled near a fence."],"vi":["Một người đàn ông đang chặt gỗ thành từng khúc.","Lá cây rơi vương vãi khắp bãi cỏ.","Một người đàn ông đang đóng cửa sổ.","Gỗ được chất đống gần hàng rào."],"ans":"D","xp":"Bên phải ảnh có một đống gỗ chất gần hàng rào (piled near a fence) → (D) đúng. Người đàn ông không chặt gỗ (A) hay đóng cửa sổ (C); không thấy lá rơi khắp bãi cỏ (B).","a":"E24-T02-04.mp3","img":"q4.jpg"},{"n":5,"opts":["People are standing in line in a lobby.","Items are being loaded into shopping bags.","Tents have been set up in a parking area.","A worker is putting up a canopy."],"vi":["Mọi người đang xếp hàng trong sảnh.","Hàng hóa đang được cho vào túi mua sắm.","Những chiếc lều đã được dựng ở bãi đậu xe.","Một công nhân đang dựng mái che."],"ans":"C","xp":"Các lều (tents) đã được dựng sẵn ở bãi đậu xe → (C) đúng (have been set up = trạng thái đã dựng xong). (A) sai vì không phải ở sảnh; (B) không ai đang cho đồ vào túi; (D) không ai đang dựng mái che.","a":"E24-T02-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some luggage is stacked next to an escalator.","A suitcase is being lifted onto a shuttle bus.","Some suitcases are displayed in a shop window.","A luggage rack has two levels."],"vi":["Một số hành lý được chồng lên nhau cạnh thang cuốn.","Một chiếc vali đang được nhấc lên xe buýt đưa đón.","Mấy chiếc vali được trưng bày trong tủ kính cửa hàng.","Giá để hành lý có hai tầng."],"ans":"D","xp":"Giá để hành lý (luggage rack) trong ảnh có hai tầng, vali đặt ở cả tầng trên và tầng dưới → (D) đúng. Ảnh không có thang cuốn (A), xe buýt (B) hay tủ kính cửa hàng (C).","a":"E24-T02-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Have the machines on the factory floor been cleaned?","qvi":"Máy móc ở khu xưởng sản xuất đã được lau dọn chưa?","opts":["No, not yet.","It's in the shipping container.","I just put it in the trash bin."],"vi":["Chưa, vẫn chưa.","Nó ở trong công-te-nơ vận chuyển.","Tôi vừa bỏ nó vào thùng rác."],"ans":"A","xp":"Câu hỏi Yes/No (Have ... been cleaned?) → (A) trả lời 'Chưa' là hợp lý. (B) bẫy liên tưởng factory → shipping container; (C) bẫy liên tưởng cleaned → trash bin.","a":"E24-T02-07.mp3"},{"n":8,"q":"How much will the budget increase next year?","qvi":"Năm sau ngân sách sẽ tăng bao nhiêu?","opts":["About 10 percent.","Three hours, I think.","At the bank's main branch."],"vi":["Khoảng 10 phần trăm.","Tôi nghĩ là ba tiếng.","Ở chi nhánh chính của ngân hàng."],"ans":"A","xp":"Hỏi 'How much' tăng bao nhiêu → (A) đưa ra con số cụ thể 10% là đúng. (B) trả lời cho How long; (C) trả lời cho Where.","a":"E24-T02-08.mp3"},{"n":9,"q":"You're going to water the plants before you leave, aren't you?","qvi":"Bạn sẽ tưới cây trước khi về, phải không?","opts":["I walked the whole way.","Yes, right after lunch.","In the breakroom."],"vi":["Tôi đã đi bộ suốt cả quãng đường.","Vâng, ngay sau bữa trưa.","Trong phòng nghỉ."],"ans":"B","xp":"Câu hỏi đuôi xác nhận việc tưới cây → (B) 'Vâng, ngay sau bữa trưa' là đúng. (A) bẫy liên tưởng going → walked; (C) trả lời cho Where.","a":"E24-T02-09.mp3"},{"n":10,"q":"Aren't you going to schedule an eye doctor appointment?","qvi":"Bạn không định đặt lịch khám mắt à?","opts":["Those glasses look nice on you.","I already scheduled one.","The seminar is three days long."],"vi":["Cặp kính đó trông hợp với bạn đấy.","Tôi đặt lịch rồi.","Hội thảo kéo dài ba ngày."],"ans":"B","xp":"Câu hỏi phủ định hỏi có đặt lịch khám mắt không → (B) 'Tôi đặt rồi' là đúng. (A) bẫy liên tưởng eye → glasses; (C) không liên quan.","a":"E24-T02-10.mp3"},{"n":11,"q":"I'm going to try to fix this printer.","qvi":"Tôi sẽ thử sửa cái máy in này.","opts":["You're right, it doesn't fit.","Double-sided copies.","Are you sure it can be repaired?"],"vi":["Bạn nói đúng, nó không vừa.","Bản sao in hai mặt.","Bạn có chắc là nó sửa được không?"],"ans":"C","xp":"Câu trần thuật: người nói định sửa máy in → (C) hỏi lại 'Có chắc sửa được không?' là phản hồi tự nhiên. (A) bẫy phát âm fix – fit; (B) bẫy liên tưởng printer → copies.","a":"E24-T02-11.mp3"},{"n":12,"q":"What should we do with these brochures?","qvi":"Chúng ta nên làm gì với mấy cuốn sách giới thiệu này?","opts":["A trip to the seashore.","Yes, I found it already.","I'll leave them at the front desk."],"vi":["Một chuyến đi biển.","Vâng, tôi tìm thấy nó rồi.","Tôi sẽ để chúng ở quầy lễ tân."],"ans":"C","xp":"Hỏi 'What should we do' (xử lý thế nào) → (C) nói cụ thể sẽ để ở quầy lễ tân là đúng. (A) bẫy liên tưởng brochures → trip; (B) câu hỏi What không trả lời Yes/No.","a":"E24-T02-12.mp3"},{"n":13,"q":"Has the policy meeting been rescheduled?","qvi":"Cuộc họp về chính sách đã được dời lịch chưa?","opts":["We have lots of desk calendar designs.","Yes, it's happening tomorrow instead.","This soup I ordered is delicious."],"vi":["Chúng tôi có rất nhiều mẫu lịch để bàn.","Rồi, thay vào đó nó sẽ diễn ra vào ngày mai.","Món súp tôi gọi ngon quá."],"ans":"B","xp":"Hỏi cuộc họp đã đổi lịch chưa → (B) 'Rồi, chuyển sang ngày mai' là đúng. (A) bẫy liên tưởng rescheduled → calendar; (C) không liên quan.","a":"E24-T02-13.mp3"},{"n":14,"q":"Why don't we stop by the office cafeteria on our way to the workshop?","qvi":"Sao chúng ta không ghé căng-tin công ty trên đường đến buổi hội thảo nhỉ?","opts":["Sure, we have time for that.","A full-service buffet.","The topic is professional networking."],"vi":["Được thôi, chúng ta có thời gian mà.","Tiệc buffet phục vụ đầy đủ.","Chủ đề là xây dựng mạng lưới quan hệ nghề nghiệp."],"ans":"A","xp":"'Why don't we...?' là lời đề nghị → (A) đồng ý 'Được thôi, mình có thời gian' là đúng. (B) bẫy liên tưởng cafeteria → buffet; (C) bẫy liên tưởng workshop → topic.","a":"E24-T02-14.mp3"},{"n":15,"q":"Have you tried our famous pasta dish?","qvi":"Bạn đã thử món mì Ý nổi tiếng của chúng tôi chưa?","opts":["We need a table for five.","Yes, it was delicious.","I'll try to make it on time."],"vi":["Chúng tôi cần một bàn cho năm người.","Rồi, món đó rất ngon.","Tôi sẽ cố đến đúng giờ."],"ans":"B","xp":"Hỏi đã ăn thử món mì chưa → (B) 'Rồi, ngon lắm' là đúng. (A) bẫy liên tưởng dish → table; (C) lặp từ try nhưng nghĩa khác (try to make it on time = cố đến kịp giờ).","a":"E24-T02-15.mp3"},{"n":16,"q":"Who's the opening act at tonight's concert?","qvi":"Ai biểu diễn mở màn trong buổi hòa nhạc tối nay?","opts":["Could you turn up the volume?","A jazz singer from France.","The position has been filled."],"vi":["Bạn vặn to âm lượng lên được không?","Một ca sĩ nhạc jazz đến từ Pháp.","Vị trí đó đã có người rồi."],"ans":"B","xp":"Hỏi 'Who' (ai mở màn) → (B) 'Một ca sĩ jazz người Pháp' là đúng. (A) bẫy liên tưởng concert → volume; (C) bẫy hiểu nhầm opening là 'vị trí trống' → position.","a":"E24-T02-16.mp3"},{"n":17,"q":"When do the product demonstrations start?","qvi":"Khi nào các buổi giới thiệu sản phẩm bắt đầu?","opts":["The schedule was e-mailed last Friday.","Some innovative features.","In room 202, I think."],"vi":["Lịch trình đã được gửi qua e-mail hôm thứ Sáu tuần trước.","Một số tính năng đột phá.","Tôi nghĩ là ở phòng 202."],"ans":"A","xp":"Hỏi 'When' → (A) trả lời gián tiếp: lịch đã gửi qua e-mail, xem trong đó sẽ biết giờ. (B) bẫy liên tưởng product → features; (C) trả lời cho Where.","a":"E24-T02-17.mp3"},{"n":18,"q":"I tried updating the Web site, but it didn't work.","qvi":"Tôi đã thử cập nhật trang web nhưng không được.","opts":["That date works for me.","Usually our online reviews.","Just send me the changes you want."],"vi":["Ngày đó tôi rảnh.","Thường là các đánh giá trực tuyến của chúng tôi.","Cứ gửi cho tôi những thay đổi bạn muốn."],"ans":"C","xp":"Người nói gặp vấn đề khi cập nhật web → (C) đưa ra giải pháp: gửi phần muốn sửa để mình làm giúp. (A) bẫy từ work – works; (B) bẫy liên tưởng Web site → online.","a":"E24-T02-18.mp3"},{"n":19,"q":"Did you hire a new welding specialist?","qvi":"Bạn đã tuyển chuyên viên hàn mới chưa?","opts":["The part's back-ordered.","Yes, he starts tomorrow.","No, it should be higher."],"vi":["Linh kiện đó đang bị nợ hàng (chưa có hàng).","Rồi, anh ấy bắt đầu làm từ ngày mai.","Không, nó nên cao hơn."],"ans":"B","xp":"Hỏi đã tuyển người chưa → (B) 'Rồi, mai anh ấy bắt đầu làm' là đúng. (A) không liên quan; (C) bẫy phát âm hire – higher.","a":"E24-T02-19.mp3"},{"n":20,"q":"How was the color palette for the lobby chosen?","qvi":"Bảng màu cho sảnh đã được chọn như thế nào?","opts":["Blue and orange.","It was fine, thanks.","I wasn't involved."],"vi":["Xanh dương và cam.","Ổn cả, cảm ơn.","Tôi không tham gia việc đó."],"ans":"C","xp":"Hỏi 'How' (chọn bằng cách nào) → (C) 'Tôi không tham gia' = cách nói gián tiếp là mình không biết. (A) bẫy liên tưởng color → blue and orange (trả lời What color); (B) hiểu nhầm How là hỏi cảm nhận.","a":"E24-T02-20.mp3"},{"n":21,"q":"When are we ordering more supplies for the office?","qvi":"Khi nào chúng ta đặt thêm đồ dùng văn phòng?","opts":["In the storage closet.","Next week on Monday.","The new desk looks great!"],"vi":["Trong tủ kho.","Thứ Hai tuần sau.","Cái bàn mới trông đẹp quá!"],"ans":"B","xp":"Hỏi 'When' → (B) 'Thứ Hai tuần sau' là đúng. (A) trả lời cho Where, bẫy liên tưởng supplies → storage closet; (C) bẫy liên tưởng office → desk.","a":"E24-T02-21.mp3"},{"n":22,"q":"The battery for the water pump is going to be solar powered, right?","qvi":"Pin cho máy bơm nước sẽ chạy bằng năng lượng mặt trời, đúng không?","opts":["We're still in the planning stages.","A hundred and forty dollars per year.","Yes, I'd love a glass of water."],"vi":["Chúng tôi vẫn đang ở giai đoạn lên kế hoạch.","Một trăm bốn mươi đô-la mỗi năm.","Vâng, tôi muốn một ly nước."],"ans":"A","xp":"Câu hỏi xác nhận → (A) 'Vẫn đang lên kế hoạch' = gián tiếp nói chưa quyết định. (B) trả lời cho How much; (C) lặp từ water.","a":"E24-T02-22.mp3"},{"n":23,"q":"Where can I buy a charger for this laptop?","qvi":"Tôi có thể mua sạc cho chiếc máy tính xách tay này ở đâu?","opts":["Around three o'clock.","I can order one for you.","A limited return policy."],"vi":["Khoảng ba giờ.","Tôi có thể đặt mua một cái cho bạn.","Chính sách đổi trả có giới hạn."],"ans":"B","xp":"Hỏi 'Where' mua sạc → (B) đề nghị giúp đặt mua là phản hồi hợp lý. (A) trả lời cho When; (C) bẫy liên tưởng buy → return policy.","a":"E24-T02-23.mp3"},{"n":24,"q":"Do I need to reserve a meeting room?","qvi":"Tôi có cần đặt phòng họp không?","opts":["Yes, let me show you how.","The service is good.","My slide presentation."],"vi":["Có, để tôi chỉ bạn cách đặt.","Dịch vụ tốt.","Bài thuyết trình bằng slide của tôi."],"ans":"A","xp":"Câu hỏi Yes/No → (A) 'Có, để tôi chỉ cách' là đúng. (B) không liên quan; (C) bẫy liên tưởng meeting → presentation.","a":"E24-T02-24.mp3"},{"n":25,"q":"When's the new department director supposed to start?","qvi":"Khi nào giám đốc bộ phận mới bắt đầu làm việc?","opts":["It's an hour long.","Ms. Pavlova isn't retiring for several weeks.","No, that department's upstairs."],"vi":["Nó dài một tiếng.","Vài tuần nữa cô Pavlova mới nghỉ hưu.","Không, bộ phận đó ở trên lầu."],"ans":"B","xp":"Hỏi 'When' → (B) trả lời gián tiếp: cô Pavlova (giám đốc cũ) vài tuần nữa mới nghỉ hưu, nên người mới sẽ bắt đầu sau đó. (A) trả lời cho How long; (C) câu hỏi When không trả lời Yes/No.","a":"E24-T02-25.mp3"},{"n":26,"q":"Should I deliver these pizzas, or will you?","qvi":"Tôi đi giao mấy cái pizza này hay bạn đi?","opts":["No thanks—I'm not hungry.","Ten dollars for two.","They're being picked up."],"vi":["Không, cảm ơn – tôi không đói.","Mười đô-la cho hai cái.","Khách sẽ đến lấy."],"ans":"C","xp":"Câu hỏi lựa chọn (tôi hay bạn giao) → (C) chọn phương án thứ ba: khách tự đến lấy, không ai cần giao. (A) bẫy liên tưởng pizzas → hungry; (B) trả lời cho How much.","a":"E24-T02-26.mp3"},{"n":27,"q":"This month's shipment schedule has been revised.","qvi":"Lịch giao hàng tháng này đã được điều chỉnh.","opts":["I couldn't find them either.","Which dates have been changed?","Two dollars per pound."],"vi":["Tôi cũng không tìm thấy chúng.","Những ngày nào đã bị thay đổi?","Hai đô-la mỗi pao."],"ans":"B","xp":"Câu thông báo lịch đã thay đổi → (B) hỏi lại 'Những ngày nào thay đổi?' là phản hồi tự nhiên. (A) 'them' không chỉ gì trong câu; (C) trả lời cho How much.","a":"E24-T02-27.mp3"},{"n":28,"q":"How much will the repairs cost?","qvi":"Sửa chữa sẽ tốn bao nhiêu tiền?","opts":["The work is covered under the warranty plan.","Yes, it's also available in red.","In about two weeks."],"vi":["Việc sửa chữa nằm trong phạm vi bảo hành.","Vâng, nó cũng có màu đỏ.","Khoảng hai tuần nữa."],"ans":"A","xp":"Hỏi chi phí sửa → (A) trả lời gián tiếp: được bảo hành nên không mất tiền. (B) câu hỏi How much không trả lời Yes/No; (C) trả lời cho When.","a":"E24-T02-28.mp3"},{"n":29,"q":"Why don't we provide more samples of the wallpaper patterns?","qvi":"Sao chúng ta không cung cấp thêm mẫu hoa văn giấy dán tường nhỉ?","opts":["The newspaper is delivered daily.","An interior design course.","There are plenty in the binders."],"vi":["Báo được giao hằng ngày.","Một khóa học thiết kế nội thất.","Trong các bìa hồ sơ có nhiều rồi mà."],"ans":"C","xp":"Lời đề nghị cung cấp thêm mẫu → (C) 'Trong bìa hồ sơ có nhiều rồi' = từ chối khéo vì đã đủ. (A) bẫy phát âm wallpaper – newspaper; (B) bẫy liên tưởng wallpaper patterns → interior design.","a":"E24-T02-29.mp3"},{"n":30,"q":"Can you give me a tour of the property this afternoon?","qvi":"Chiều nay bạn có thể dẫn tôi đi xem tòa nhà không?","opts":["Sorry, I won't have time until tomorrow.","It has a very modern design.","A house on Maple Street."],"vi":["Xin lỗi, phải đến mai tôi mới có thời gian.","Nó có thiết kế rất hiện đại.","Một ngôi nhà trên đường Maple."],"ans":"A","xp":"Lời nhờ vả → (A) từ chối lịch sự và nói lý do (đến mai mới rảnh) là đúng. (B), (C) bẫy liên tưởng property → design, house.","a":"E24-T02-30.mp3"},{"n":31,"q":"Who's scheduled to test the product today?","qvi":"Hôm nay ai được phân công thử nghiệm sản phẩm?","opts":["We're waiting for confirmation.","It's a great album, right?","About six weeks ago."],"vi":["Chúng tôi đang chờ xác nhận.","Đó là một album tuyệt vời, nhỉ?","Khoảng sáu tuần trước."],"ans":"A","xp":"Hỏi 'Who' → (A) 'Đang chờ xác nhận' = gián tiếp nói chưa biết ai. (B) không liên quan; (C) trả lời cho When.","a":"E24-T02-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Good morning, captain. We'll be docking at the port in Kolkata this evening, right?","Chào buổi sáng, thuyền trưởng. Tối nay chúng ta sẽ cập cảng Kolkata, đúng không ạ?"],["W","Actually, we had to change course overnight to avoid a storm, so we're running behind schedule. But we should arrive early tomorrow.","Thật ra đêm qua chúng ta phải đổi hướng đi để tránh một cơn bão nên đang bị trễ lịch. Nhưng sáng sớm mai chắc sẽ tới nơi."],["M","Well, that's not too bad.","Vậy cũng không tệ lắm."],["W","Oh, Hector has the day off today, so I'll need you to do the morning rounds—starting with checking the machinery in the engine room.","À, hôm nay Hector nghỉ nên tôi cần anh đi kiểm tra buổi sáng – bắt đầu bằng việc kiểm tra máy móc trong phòng máy."],["M","Of course—I'll head there now.","Vâng ạ – tôi xuống đó ngay."]],"qs":[{"n":32,"q":"Where does the conversation most likely take place?","qvi":"Cuộc hội thoại có khả năng diễn ra ở đâu nhất?","opts":["On a train","On a boat","At a factory","At an airport"],"vi":["Trên tàu hỏa","Trên tàu thủy","Ở nhà máy","Ở sân bay"],"ans":"B","xp":"Người đàn ông chào 'Good morning, captain' và nói 'We'll be docking at the port in Kolkata' (sắp cập cảng) → họ đang ở trên tàu thủy. dock = cập bến, port = cảng."},{"n":33,"q":"What caused a delay?","qvi":"Điều gì gây ra sự chậm trễ?","opts":["An electrical failure occurred.","A worker was unavailable.","Some information was incorrect.","The weather was bad."],"vi":["Xảy ra sự cố điện.","Một nhân viên không có mặt.","Một số thông tin không chính xác.","Thời tiết xấu."],"ans":"D","xp":"Người phụ nữ nói: 'we had to change course overnight to avoid a storm, so we're running behind schedule' → phải tránh bão nên bị trễ. a storm (cơn bão) = The weather was bad."},{"n":34,"q":"What will the man do next?","qvi":"Người đàn ông sẽ làm gì tiếp theo?","opts":["Confirm a schedule","Speak to a coworker","Check some machinery","Clean a storage room"],"vi":["Xác nhận lịch trình","Nói chuyện với đồng nghiệp","Kiểm tra máy móc","Dọn phòng kho"],"ans":"C","xp":"Người phụ nữ nhờ: 'starting with checking the machinery in the engine room', người đàn ông đáp 'Of course—I'll head there now' → anh ấy sẽ đi kiểm tra máy móc."}],"a":"E24-T02-32-34.mp3"},{"ns":[35,37],"script":[["M","Hi. I'm here to schedule some personal training sessions.","Chào chị. Tôi đến để đặt lịch vài buổi tập với huấn luyện viên cá nhân."],["W","OK. What are your fitness goals?","Vâng. Mục tiêu tập luyện của anh là gì?"],["M","I'd like to lift weights and build strength.","Tôi muốn tập tạ và tăng sức mạnh."],["W","I can work with you on that. Are you currently a member here?","Tôi có thể giúp anh việc đó. Hiện anh có phải là hội viên ở đây không?"],["M","No, I'll also need to sign up for a membership. I saw online that you're running a special for new members—fifty percent off the first month's membership. Can I sign up for that?","Không, tôi cũng cần đăng ký làm hội viên nữa. Tôi thấy trên mạng là bên chị đang có ưu đãi cho hội viên mới – giảm 50% phí tháng đầu tiên. Tôi đăng ký gói đó được không?"],["W","Absolutely. But before I get you signed up, let me show you around our facility.","Tất nhiên rồi. Nhưng trước khi làm thủ tục đăng ký, để tôi dẫn anh đi tham quan cơ sở của chúng tôi."]],"qs":[{"n":35,"q":"Where does the woman most likely work?","qvi":"Người phụ nữ có khả năng làm việc ở đâu nhất?","opts":["At a sports stadium","At a fitness center","At a doctor's office","At a library"],"vi":["Ở sân vận động","Ở trung tâm thể hình","Ở phòng khám bác sĩ","Ở thư viện"],"ans":"B","xp":"Người đàn ông nói 'I'm here to schedule some personal training sessions' và người phụ nữ hỏi 'What are your fitness goals?' → cô ấy làm ở trung tâm thể hình (phòng gym)."},{"n":36,"q":"What does the man ask about?","qvi":"Người đàn ông hỏi về điều gì?","opts":["A discount","A form","A business location","A parking policy"],"vi":["Một khoản giảm giá","Một mẫu đơn","Địa điểm kinh doanh","Quy định đỗ xe"],"ans":"A","xp":"Anh ấy nói: 'you're running a special for new members—fifty percent off the first month's membership. Can I sign up for that?' → hỏi về ưu đãi giảm giá. fifty percent off = A discount."},{"n":37,"q":"What will the woman do next?","qvi":"Người phụ nữ sẽ làm gì tiếp theo?","opts":["Post a sign","Confirm an account number","Provide a tour","Look at a schedule"],"vi":["Dán biển thông báo","Xác nhận số tài khoản","Dẫn đi tham quan","Xem lịch trình"],"ans":"C","xp":"Cuối hội thoại cô ấy nói: 'let me show you around our facility' → dẫn anh ấy đi tham quan cơ sở. show you around = Provide a tour."}],"a":"E24-T02-35-37.mp3"},{"ns":[38,40],"script":[["W","As you can see, this Renaissance landscape painting we acquired is in bad condition. We can't display it yet.","Như anh thấy đấy, bức tranh phong cảnh thời Phục Hưng mà chúng ta mới mua về đang trong tình trạng tệ. Chúng ta chưa thể trưng bày nó được."],["M","Hmm, yes. This painting will need significant restoration work.","Ừm, đúng vậy. Bức tranh này sẽ cần phục chế khá nhiều."],["W","I'll begin by investigating the artist's color palette and style to see how we should repair the damaged areas.","Tôi sẽ bắt đầu bằng việc nghiên cứu bảng màu và phong cách của họa sĩ để xem nên sửa những chỗ hư hại như thế nào."],["M","You know, this would be a stunning piece to unveil at our anniversary dinner in June. And, since it's a big project to finish by then, we should get started right away.","Chị biết không, đây sẽ là một tác phẩm tuyệt đẹp để ra mắt tại bữa tối kỷ niệm vào tháng Sáu. Và vì đây là dự án lớn cần xong trước thời điểm đó, chúng ta nên bắt tay vào làm ngay."]],"qs":[{"n":38,"q":"Who most likely are the speakers?","qvi":"Những người nói có khả năng là ai nhất?","opts":["Art restorers","Event planners","Photographers","Interior designers"],"vi":["Người phục chế tác phẩm nghệ thuật","Người tổ chức sự kiện","Nhiếp ảnh gia","Nhà thiết kế nội thất"],"ans":"A","xp":"Người đàn ông nói 'This painting will need significant restoration work' và người phụ nữ sẽ tìm hiểu 'how we should repair the damaged areas' → họ là người phục chế tranh. restoration = phục chế."},{"n":39,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Hire an intern","Review a contract","Take some measurements","Investigate a problem"],"vi":["Thuê một thực tập sinh","Xem xét hợp đồng","Đo đạc kích thước","Điều tra một vấn đề"],"ans":"D","xp":"Cô ấy nói: 'I'll begin by investigating the artist's color palette and style to see how we should repair the damaged areas' → nghiên cứu để tìm cách sửa phần hư hại = Investigate a problem."},{"n":40,"q":"Why does the man suggest beginning a project quickly?","qvi":"Tại sao người đàn ông đề nghị bắt đầu dự án sớm?","opts":["Payment has already been made.","Staff will be on vacation.","An important event is approaching.","A client is in town for a limited time."],"vi":["Đã thanh toán rồi.","Nhân viên sẽ đi nghỉ phép.","Một sự kiện quan trọng sắp đến.","Một khách hàng chỉ ở thành phố trong thời gian ngắn."],"ans":"C","xp":"Anh ấy nói bức tranh sẽ được ra mắt 'at our anniversary dinner in June' và 'since it's a big project to finish by then, we should get started right away' → vì bữa tối kỷ niệm sắp tới. anniversary dinner = An important event."}],"a":"E24-T02-38-40.mp3"},{"ns":[41,43],"script":[["W","Hi, Ozan. Do you have time to review some slides I'm presenting at a meeting on Thursday?","Chào Ozan. Anh có thời gian xem giúp mấy slide tôi sẽ trình bày trong cuộc họp hôm thứ Năm không?"],["M1","Oh. Is that the meeting with Smith Incorporated?","Ồ. Có phải cuộc họp với công ty Smith không?"],["W","Yes. I'm presenting them with our updated marketing plan for their chain of bookstores.","Đúng vậy. Tôi sẽ trình bày cho họ kế hoạch tiếp thị đã cập nhật cho chuỗi nhà sách của họ."],["M1","You know, Smith Incorporated prefers informal meetings. I think just a handout highlighting how our marketing plan will positively impact their book sales would be enough.","Chị biết đấy, công ty Smith thích những buổi họp thân mật, không trang trọng. Tôi nghĩ chỉ cần một tờ tài liệu nêu bật việc kế hoạch tiếp thị của mình sẽ tác động tích cực thế nào đến doanh số sách của họ là đủ."],["W","Really? Thilo, you've worked with this client before. What do you think?","Thật sao? Thilo, anh từng làm việc với khách hàng này rồi. Anh nghĩ sao?"],["M2","Ozan is right. I think they'd prefer a meeting that was more of a conversation than a presentation.","Ozan nói đúng đấy. Tôi nghĩ họ sẽ thích một buổi họp giống trò chuyện hơn là một bài thuyết trình."]],"qs":[{"n":41,"q":"What is the woman preparing?","qvi":"Người phụ nữ đang chuẩn bị gì?","opts":["A slide presentation","A travel itinerary","A guest list","A sales contract"],"vi":["Một bài thuyết trình bằng slide","Lịch trình chuyến đi","Danh sách khách mời","Hợp đồng bán hàng"],"ans":"A","xp":"Cô ấy hỏi: 'Do you have time to review some slides I'm presenting at a meeting on Thursday?' → cô ấy đang chuẩn bị bài thuyết trình bằng slide."},{"n":42,"q":"What kind of business is Smith Incorporated?","qvi":"Smith Incorporated là loại hình doanh nghiệp gì?","opts":["A law firm","A construction company","A pharmaceutical manufacturer","A bookstore chain"],"vi":["Công ty luật","Công ty xây dựng","Nhà sản xuất dược phẩm","Chuỗi nhà sách"],"ans":"D","xp":"Khi được hỏi về cuộc họp với Smith Incorporated, cô ấy nói: 'our updated marketing plan for their chain of bookstores' → Smith là chuỗi nhà sách."},{"n":43,"q":"What do the men agree about?","qvi":"Hai người đàn ông đồng ý với nhau về điều gì?","opts":["A subscription should be canceled.","An advertising campaign should be delayed.","A training session should be mandatory.","A meeting should be casual."],"vi":["Nên hủy gói đăng ký.","Nên hoãn chiến dịch quảng cáo.","Buổi đào tạo nên là bắt buộc.","Cuộc họp nên thân mật, không trang trọng."],"ans":"D","xp":"Ozan nói 'Smith Incorporated prefers informal meetings', Thilo đồng ý 'Ozan is right... they'd prefer a meeting that was more of a conversation than a presentation' → cuộc họp nên thân mật. informal = casual."}],"a":"E24-T02-41-43.mp3"},{"ns":[44,46],"script":[["W","I heard that the results of your experiment were better than you expected. Congratulations!","Tôi nghe nói kết quả thí nghiệm của anh tốt hơn anh mong đợi. Chúc mừng nhé!"],["M","Thanks! I thought we'd have to run that reaction ten times before we got a positive result. But we got it on the third try.","Cảm ơn chị! Tôi tưởng phải chạy phản ứng đó mười lần mới có kết quả khả quan. Nhưng đến lần thứ ba là được rồi."],["W","You'll have to write up your results and submit them to the research director. That's Esra, right?","Anh sẽ phải viết báo cáo kết quả và nộp cho giám đốc nghiên cứu. Là chị Esra, đúng không?"],["M","Oh, Esra's leaving the company next week.","À, tuần sau chị Esra nghỉ việc ở công ty rồi."],["W","Oh, I didn't know that. I wonder if you'll be promoted to fill her position.","Ồ, tôi không biết đấy. Không biết anh có được thăng chức vào vị trí của chị ấy không nhỉ."],["M","I don't think so. I've never managed an entire research group. I hope to get some experience doing that next quarter.","Tôi không nghĩ vậy. Tôi chưa bao giờ quản lý cả một nhóm nghiên cứu. Tôi hy vọng quý tới sẽ có chút kinh nghiệm làm việc đó."]],"qs":[{"n":44,"q":"Why does the woman congratulate the man?","qvi":"Tại sao người phụ nữ chúc mừng người đàn ông?","opts":["He finished a road race.","He won a publishing award.","His experiment was successful.","His research funding was extended."],"vi":["Anh ấy đã hoàn thành một cuộc đua đường trường.","Anh ấy đoạt giải thưởng xuất bản.","Thí nghiệm của anh ấy thành công.","Kinh phí nghiên cứu của anh ấy được gia hạn."],"ans":"C","xp":"Cô ấy nói: 'the results of your experiment were better than you expected. Congratulations!' → thí nghiệm thành công. better than you expected = successful."},{"n":45,"q":"What does the man imply when he says, \"Esra's leaving the company next week\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"Esra's leaving the company next week\"?","opts":["He needs assistance planning a party for Esra.","He will not submit a report to Esra.","He will apply for a new position.","A larger office has become available."],"vi":["Anh ấy cần giúp lên kế hoạch tiệc cho Esra.","Anh ấy sẽ không nộp báo cáo cho Esra.","Anh ấy sẽ ứng tuyển vị trí mới.","Đã có một văn phòng rộng hơn còn trống."],"ans":"B","xp":"Người phụ nữ nói anh phải 'write up your results and submit them to the research director. That's Esra, right?' → anh đáp Esra tuần sau nghỉ việc, ngụ ý anh sẽ không nộp báo cáo cho Esra (mà cho người khác)."},{"n":46,"q":"What does the man hope to do next quarter?","qvi":"Người đàn ông hy vọng làm gì vào quý tới?","opts":["Receive a research grant","Publish a book","Replace some furniture","Gain management experience"],"vi":["Nhận tài trợ nghiên cứu","Xuất bản một cuốn sách","Thay một số đồ nội thất","Có thêm kinh nghiệm quản lý"],"ans":"D","xp":"Anh ấy nói: 'I've never managed an entire research group. I hope to get some experience doing that next quarter' → muốn có kinh nghiệm quản lý."}],"a":"E24-T02-44-46.mp3"},{"ns":[47,49],"script":[["W","Now we'll move on to a special segment of our news program where we highlight new local businesses for our viewers. Today I'm talking with Dhruv Bajaj—a personal trainer and gym owner. Thanks for coming into the studio today, Dhruv!","Bây giờ chúng ta chuyển sang chuyên mục đặc biệt của chương trình thời sự, nơi chúng tôi giới thiệu đến khán giả các doanh nghiệp mới tại địa phương. Hôm nay tôi trò chuyện với Dhruv Bajaj – huấn luyện viên cá nhân và chủ phòng tập. Cảm ơn anh đã đến trường quay hôm nay, Dhruv!"],["M","Thanks for having me! I'm excited to tell you about the gym I just opened last month. It has state-of-the-art equipment, and my trainers can work with clients at any stage in their fitness journey.","Cảm ơn chị đã mời tôi! Tôi rất hào hứng được kể về phòng tập tôi vừa mở tháng trước. Phòng tập có trang thiết bị hiện đại nhất, và các huấn luyện viên của tôi có thể hỗ trợ khách hàng ở bất kỳ giai đoạn nào trong hành trình tập luyện."],["W","Sounds great. How did you get started in this line of work?","Nghe tuyệt quá. Anh đã bắt đầu làm nghề này như thế nào?"],["M","Well, I was an athlete in school, and when I stopped competing, I wanted to continue doing something fitness-related. So I started working as a trainer.","À, hồi đi học tôi là vận động viên, và khi thôi thi đấu, tôi muốn tiếp tục làm gì đó liên quan đến thể hình. Vì vậy tôi bắt đầu làm huấn luyện viên."]],"qs":[{"n":47,"q":"Where most likely are the speakers?","qvi":"Những người nói có khả năng đang ở đâu nhất?","opts":["At a sporting goods store","At a television studio","At a sports arena","At a gym"],"vi":["Ở cửa hàng đồ thể thao","Ở trường quay truyền hình","Ở nhà thi đấu thể thao","Ở phòng tập gym"],"ans":"B","xp":"Người phụ nữ nói 'a special segment of our news program' và 'Thanks for coming into the studio today' → họ đang ở trường quay truyền hình. Lưu ý (D) là bẫy: anh ấy nói về phòng gym nhưng không ở đó."},{"n":48,"q":"What does the man say he recently did?","qvi":"Người đàn ông nói gần đây anh ấy đã làm gì?","opts":["He retired from his job.","He designed a Web site.","He opened a new facility.","He competed in a sports event."],"vi":["Anh ấy nghỉ hưu.","Anh ấy thiết kế một trang web.","Anh ấy mở một cơ sở mới.","Anh ấy thi đấu trong một sự kiện thể thao."],"ans":"C","xp":"Anh ấy nói: 'the gym I just opened last month' → vừa mở phòng tập mới. last month = recently; the gym I just opened = a new facility."},{"n":49,"q":"What does the woman ask the man to talk about?","qvi":"Người phụ nữ đề nghị người đàn ông nói về điều gì?","opts":["His career path","His mentors","His future goals","His hobbies"],"vi":["Con đường sự nghiệp của anh ấy","Những người cố vấn của anh ấy","Mục tiêu tương lai của anh ấy","Sở thích của anh ấy"],"ans":"A","xp":"Cô ấy hỏi: 'How did you get started in this line of work?' (anh bắt đầu làm nghề này thế nào?) → hỏi về con đường sự nghiệp."}],"a":"E24-T02-47-49.mp3"},{"ns":[50,52],"script":[["M1","As director, I'm delighted to welcome you to the Redmond Aquatic Institute. We're happy you'll be producing content for our Web site.","Với tư cách giám đốc, tôi rất vui được chào đón cô đến với Viện Thủy sinh Redmond. Chúng tôi rất mừng vì cô sẽ sản xuất nội dung cho trang web của chúng tôi."],["W","I'm looking forward to writing about Redmond's initiatives in marine biology.","Tôi rất mong được viết về các dự án sáng kiến của Redmond trong lĩnh vực sinh học biển."],["M1","Yes, the more articles the public can read about threats to aquatic ecosystems, the better. Public awareness will help us get funding to meet our aim of preserving these ecosystems. This is Roberto. He's working on our mangrove research project, which is the first one you'll cover.","Vâng, công chúng càng đọc được nhiều bài viết về các mối đe dọa đối với hệ sinh thái dưới nước thì càng tốt. Nhận thức của công chúng sẽ giúp chúng tôi có kinh phí để đạt mục tiêu bảo tồn các hệ sinh thái này. Đây là Roberto. Anh ấy đang làm dự án nghiên cứu rừng ngập mặn, đó là dự án đầu tiên cô sẽ viết bài."],["M2","It's an interesting project. And what's exciting is that we've started using drones to photograph the area with the mangroves. So we have some great images you could use.","Đây là một dự án thú vị. Và điều hấp dẫn là chúng tôi đã bắt đầu dùng máy bay không người lái (drone) để chụp ảnh khu vực rừng ngập mặn. Vì thế chúng tôi có vài bức ảnh rất đẹp cô có thể dùng."]],"qs":[{"n":50,"q":"What has the woman been hired to do?","qvi":"Người phụ nữ được thuê để làm gì?","opts":["Write articles","Update some software","Organize a fund-raiser","Manage office staff"],"vi":["Viết bài","Cập nhật phần mềm","Tổ chức sự kiện gây quỹ","Quản lý nhân viên văn phòng"],"ans":"A","xp":"Giám đốc nói cô sẽ 'producing content for our Web site' và cô đáp 'I'm looking forward to writing about Redmond's initiatives in marine biology' → cô được thuê để viết bài."},{"n":51,"q":"According to the director, what is the organization's goal?","qvi":"Theo giám đốc, mục tiêu của tổ chức là gì?","opts":["To hire professionals in the field","To create educational programs","To collect data from other scientific institutes","To protect aquatic environments"],"vi":["Tuyển các chuyên gia trong ngành","Xây dựng các chương trình giáo dục","Thu thập dữ liệu từ các viện khoa học khác","Bảo vệ môi trường dưới nước"],"ans":"D","xp":"Giám đốc nói: 'our aim of preserving these ecosystems' (các hệ sinh thái dưới nước) → mục tiêu là bảo vệ môi trường nước. aim = goal; preserving these (aquatic) ecosystems = protect aquatic environments."},{"n":52,"q":"What does Roberto say is exciting?","qvi":"Roberto nói điều gì là thú vị?","opts":["The use of some equipment","The results of a survey","The public response to a project","A recent donation to the institute"],"vi":["Việc sử dụng một thiết bị","Kết quả một cuộc khảo sát","Phản hồi của công chúng về một dự án","Một khoản quyên góp gần đây cho viện"],"ans":"A","xp":"Roberto nói: 'what's exciting is that we've started using drones to photograph the area' → việc dùng drone (một loại thiết bị). using drones = The use of some equipment."}],"a":"E24-T02-50-52.mp3"},{"ns":[53,55],"script":[["W","Matthew, you're not planning to cancel Wednesday's budget meeting, are you?","Matthew, anh không định hủy cuộc họp ngân sách hôm thứ Tư đấy chứ?"],["M","I haven't sent out the cancellation yet, but our research partners in China are off this week for a national holiday, so there's no point in meeting. Why?","Tôi chưa gửi thông báo hủy, nhưng các đối tác nghiên cứu bên Trung Quốc tuần này nghỉ lễ quốc gia nên họp cũng chẳng để làm gì. Sao vậy?"],["W","Well, I've been looking at the draft budget, and we didn't allocate funds for a project leader.","À, tôi đang xem bản dự thảo ngân sách, và chúng ta đã không phân bổ kinh phí cho vị trí trưởng dự án."],["M","Uh-oh. I wonder how that happened. You're right. We need to discuss how to fix that.","Ôi. Không biết sao lại thế nhỉ. Chị nói đúng. Chúng ta cần bàn cách khắc phục chuyện đó."],["W","You know, we allocated money for a trip to Singapore to present our preliminary findings. We don't really need to do that.","Anh biết không, chúng ta đã phân bổ tiền cho chuyến đi Singapore để trình bày kết quả nghiên cứu sơ bộ. Thật ra chúng ta không cần làm việc đó."]],"qs":[{"n":53,"q":"What does the man say about some contacts in China?","qvi":"Người đàn ông nói gì về các đối tác ở Trung Quốc?","opts":["They submitted some preliminary results.","They requested help with a presentation.","They are celebrating a holiday.","They are coming to visit soon."],"vi":["Họ đã nộp một số kết quả sơ bộ.","Họ nhờ giúp đỡ với một bài thuyết trình.","Họ đang nghỉ lễ.","Họ sắp đến thăm."],"ans":"C","xp":"Anh ấy nói: 'our research partners in China are off this week for a national holiday' → họ đang nghỉ lễ quốc gia. are off for a national holiday = are celebrating a holiday."},{"n":54,"q":"What does the woman imply when she says, \"we didn't allocate funds for a project leader\"?","qvi":"Người phụ nữ ngụ ý gì khi nói \"we didn't allocate funds for a project leader\"?","opts":["She thinks a project deadline should be extended.","She is surprised by a suggestion.","A scheduled meeting should take place.","A project leader will not be hired."],"vi":["Cô ấy nghĩ nên gia hạn thời hạn dự án.","Cô ấy ngạc nhiên trước một đề xuất.","Cuộc họp đã lên lịch nên được tổ chức.","Sẽ không thuê trưởng dự án."],"ans":"C","xp":"Người đàn ông định hủy cuộc họp ngân sách vì 'there's no point in meeting'. Cô ấy đáp ngân sách chưa có tiền cho trưởng dự án → ngụ ý vẫn cần họp để giải quyết; anh ấy cũng đồng ý 'We need to discuss how to fix that'."},{"n":55,"q":"What does the woman say about some travel expenses?","qvi":"Người phụ nữ nói gì về một số chi phí đi lại?","opts":["They are unnecessary.","They have been refunded.","They require receipts.","They were charged to the company credit card."],"vi":["Chúng không cần thiết.","Chúng đã được hoàn tiền.","Chúng cần có hóa đơn.","Chúng đã được tính vào thẻ tín dụng công ty."],"ans":"A","xp":"Cô ấy nói: 'we allocated money for a trip to Singapore... We don't really need to do that' → chi phí chuyến đi là không cần thiết."}],"a":"E24-T02-53-55.mp3"},{"ns":[56,58],"script":[["M","Hello, you've reached tech support.","Xin chào, đây là bộ phận hỗ trợ kỹ thuật."],["W","I'm calling from Rubin Restaurant Equipment. I recently purchased your software to keep track of my warehouse inventory, and I have a question about setting alerts.","Tôi gọi từ công ty Thiết bị Nhà hàng Rubin. Gần đây tôi đã mua phần mềm của bên anh để theo dõi hàng tồn kho trong nhà kho, và tôi có câu hỏi về việc cài đặt cảnh báo."],["M","Sure. How can I help?","Vâng. Tôi có thể giúp gì ạ?"],["W","Well, we've been getting an alert whenever the inventory for our deep fryers drops below ten. But we usually don't stock many of those because restaurants don't often need to replace them. So, can I lower the alert level for just those items?","À, chúng tôi cứ nhận được cảnh báo mỗi khi lượng nồi chiên ngập dầu trong kho xuống dưới mười cái. Nhưng chúng tôi thường không trữ nhiều mặt hàng đó vì các nhà hàng ít khi phải thay. Vậy tôi có thể hạ mức cảnh báo chỉ riêng cho mặt hàng đó không?"],["M","Yes. In the system, if you click on that product, you'll see a link that says, \"Set Custom Alert.\" And you can set it to any number from there.","Được ạ. Trong hệ thống, nếu chị nhấp vào sản phẩm đó, chị sẽ thấy một đường link ghi \"Set Custom Alert\" (Cài cảnh báo tùy chỉnh). Từ đó chị có thể đặt bất kỳ con số nào."],["W","I see it. Thanks for your help.","Tôi thấy rồi. Cảm ơn anh đã giúp."]],"qs":[{"n":56,"q":"Where is the woman calling from?","qvi":"Người phụ nữ gọi điện từ đâu?","opts":["A clothing store","A furniture store","A restaurant supply company","A graphic design firm"],"vi":["Một cửa hàng quần áo","Một cửa hàng nội thất","Một công ty cung cấp thiết bị nhà hàng","Một công ty thiết kế đồ họa"],"ans":"C","xp":"Cô ấy nói: 'I'm calling from Rubin Restaurant Equipment' → công ty cung cấp thiết bị cho nhà hàng. Restaurant Equipment = A restaurant supply company."},{"n":57,"q":"What is some software being used for?","qvi":"Phần mềm đang được dùng để làm gì?","opts":["Inventory management","Employee performance reviews","Sales forecasting","Web site design"],"vi":["Quản lý hàng tồn kho","Đánh giá hiệu quả làm việc của nhân viên","Dự báo doanh số","Thiết kế trang web"],"ans":"A","xp":"Cô ấy nói: 'I recently purchased your software to keep track of my warehouse inventory' → dùng để quản lý hàng tồn kho. keep track of inventory = Inventory management."},{"n":58,"q":"What does the man help the woman do?","qvi":"Người đàn ông giúp người phụ nữ làm gì?","opts":["Return a purchase","Customize a setting","Repair an engine","Inspect a shipment"],"vi":["Trả lại món hàng đã mua","Tùy chỉnh một cài đặt","Sửa động cơ","Kiểm tra lô hàng"],"ans":"B","xp":"Anh ấy hướng dẫn: 'you'll see a link that says, \"Set Custom Alert.\" And you can set it to any number from there' → giúp cô tùy chỉnh mức cảnh báo = Customize a setting."}],"a":"E24-T02-56-58.mp3"},{"ns":[59,61],"script":[["M","I just spoke to the garden director. He wants us to install an irrigation system in the rose garden as well as the magnolia grove. He wants to be sure the flowers get plenty of water during the hot summer months.","Tôi vừa nói chuyện với giám đốc khu vườn. Ông ấy muốn chúng ta lắp hệ thống tưới nước ở vườn hoa hồng và cả khu rừng mộc lan. Ông ấy muốn chắc chắn hoa được tưới đủ nước trong những tháng hè nóng bức."],["W","OK, let's walk over there now and take some measurements. Then we can figure out what materials we'll need.","Được, giờ mình đi bộ qua đó đo đạc đi. Rồi mình sẽ tính xem cần những vật liệu gì."],["M","Sure. We have some extra parts left over from when we worked on the cherry trees. I'll check what we have left after we finish measuring the rose garden.","Ừ. Mình còn thừa một số linh kiện từ hồi làm khu cây anh đào. Đo xong vườn hồng tôi sẽ kiểm tra xem còn lại những gì."]],"qs":[{"n":59,"q":"Where are the speakers most likely working?","qvi":"Những người nói có khả năng đang làm việc ở đâu nhất?","opts":["At a flower shop","At a botanical garden","At a fruit orchard","At a hardware store"],"vi":["Ở cửa hàng hoa","Ở vườn bách thảo","Ở vườn cây ăn quả","Ở cửa hàng đồ kim khí"],"ans":"B","xp":"Người đàn ông nhắc đến 'the garden director', 'the rose garden as well as the magnolia grove' và 'the cherry trees' → nhiều khu vườn, cây khác nhau → vườn bách thảo (botanical garden)."},{"n":60,"q":"What have the speakers been asked to do?","qvi":"Những người nói được yêu cầu làm gì?","opts":["Arrange some flowers","Deliver some tools","Install a watering system","Repair a lawn mower"],"vi":["Cắm hoa","Giao dụng cụ","Lắp đặt hệ thống tưới nước","Sửa máy cắt cỏ"],"ans":"C","xp":"Người đàn ông nói: 'He wants us to install an irrigation system' → được yêu cầu lắp hệ thống tưới. irrigation system = a watering system."},{"n":61,"q":"What does the man offer to do?","qvi":"Người đàn ông đề nghị làm gì?","opts":["Look for some materials","Train an assistant","Transplant some trees","Work extra hours"],"vi":["Tìm một số vật liệu","Đào tạo một trợ lý","Bứng cây đi trồng chỗ khác","Làm thêm giờ"],"ans":"A","xp":"Anh ấy nói: 'We have some extra parts left over... I'll check what we have left' → sẽ kiểm tra xem còn vật liệu gì = Look for some materials."}],"a":"E24-T02-59-61.mp3"},{"ns":[62,64],"script":[["M","Good morning, Ms. Aljohani. Sorry I'm a little late. Traffic was terrible.","Chào buổi sáng, chị Aljohani. Xin lỗi tôi đến hơi trễ. Giao thông tệ quá."],["W","That's OK, but our rental office will be very busy this morning. There's a big education convention in town starting today, and a lot of attendees from out of town have reserved cars to get to the conference center.","Không sao, nhưng sáng nay văn phòng cho thuê xe của chúng ta sẽ rất bận. Từ hôm nay có một hội nghị lớn về giáo dục trong thành phố, và nhiều người tham dự từ nơi khác đến đã đặt xe để đi tới trung tâm hội nghị."],["M","Right. What do you want me to do first?","Vâng. Chị muốn tôi làm gì trước?"],["W","I'd like you to start by checking the batteries in our electric cars. We want to be sure they're all fully charged.","Tôi muốn anh bắt đầu bằng việc kiểm tra pin của các xe điện. Chúng ta cần chắc chắn tất cả đều được sạc đầy."]],"qs":[{"n":62,"q":"Why does the man apologize?","qvi":"Tại sao người đàn ông xin lỗi?","opts":["He lost a key.","He arrived late.","He turned off some equipment.","He forgot an instruction manual."],"vi":["Anh ấy làm mất chìa khóa.","Anh ấy đến trễ.","Anh ấy đã tắt một thiết bị.","Anh ấy quên sách hướng dẫn."],"ans":"B","xp":"Anh ấy nói: 'Sorry I'm a little late. Traffic was terrible.' → xin lỗi vì đến trễ."},{"n":63,"q":"According to the woman, why will the speakers be very busy today?","qvi":"Theo người phụ nữ, tại sao hôm nay họ sẽ rất bận?","opts":["The agency is offering a discount.","A new rental office is opening.","There is a conference in town.","A sporting event will take place."],"vi":["Công ty đang có chương trình giảm giá.","Một văn phòng cho thuê mới sắp khai trương.","Có một hội nghị trong thành phố.","Sẽ có một sự kiện thể thao."],"ans":"C","xp":"Cô ấy nói: 'There's a big education convention in town starting today' → có hội nghị trong thành phố. convention = conference."},{"n":64,"q":"Look at the graphic. Where will the man go first?","qvi":"Nhìn vào hình. Người đàn ông sẽ đến đâu trước?","opts":["Area 1","Area 2","Area 3","Area 4"],"vi":["Khu 1","Khu 2","Khu 3","Khu 4"],"ans":"B","xp":"Cô ấy nói: 'I'd like you to start by checking the batteries in our electric cars' → xe điện (Electric cars) nằm ở Area 2 theo sơ đồ → anh ấy đến Khu 2 trước."}],"a":"E24-T02-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","I've been on vacation, so I missed our department's meeting. Can you give me an update?","Tôi đi nghỉ phép nên lỡ cuộc họp của phòng. Chị cập nhật tình hình cho tôi được không?"],["W","Well, all our public programs and community events are on schedule.","À, tất cả các chương trình công cộng và sự kiện cộng đồng của chúng ta đều đang đúng tiến độ."],["M","Great! How about the Jannis Park project? We're still planning on planting trees best suited for residential areas, right?","Tuyệt! Còn dự án công viên Jannis thì sao? Chúng ta vẫn dự định trồng những loại cây phù hợp nhất với khu dân cư, đúng không?"],["W","That's right. I'm working on the public education part now. There'll be a children's poster competition next month, which the city mayor will judge.","Đúng vậy. Hiện tôi đang lo phần giáo dục cộng đồng. Tháng sau sẽ có một cuộc thi vẽ áp phích dành cho trẻ em, do ông thị trưởng thành phố làm giám khảo."],["M","Interesting. Is there a prize?","Thú vị đấy. Có giải thưởng không?"],["W","The winner will get a ribbon. But all participants will get a seedling to plant at home. We'll be giving away the tallest of these four varieties, since it was the most popular in a survey of our residents.","Người thắng sẽ được nhận một dải ruy băng. Nhưng tất cả người tham gia đều được tặng một cây giống để trồng ở nhà. Chúng ta sẽ tặng loại cao nhất trong bốn loại cây này, vì nó được yêu thích nhất trong cuộc khảo sát cư dân."]],"qs":[{"n":65,"q":"Where do the speakers most likely work?","qvi":"Những người nói có khả năng làm việc ở đâu nhất?","opts":["At a landscaping company","At a local government office","At a garden store","At a lumber yard"],"vi":["Ở công ty cảnh quan","Ở cơ quan chính quyền địa phương","Ở cửa hàng đồ làm vườn","Ở bãi gỗ"],"ans":"B","xp":"Người phụ nữ nói 'all our public programs and community events are on schedule', và họ lo dự án công viên, cuộc thi do thị trưởng chấm, khảo sát cư dân → họ làm ở cơ quan chính quyền địa phương."},{"n":66,"q":"What does the woman say will take place next month?","qvi":"Người phụ nữ nói điều gì sẽ diễn ra vào tháng sau?","opts":["A seasonal promotion","A product demonstration","A poster contest","A lecture series"],"vi":["Một đợt khuyến mãi theo mùa","Một buổi giới thiệu sản phẩm","Một cuộc thi áp phích","Một chuỗi bài giảng"],"ans":"C","xp":"Cô ấy nói: 'There'll be a children's poster competition next month' → cuộc thi áp phích. competition = contest."},{"n":67,"q":"Look at the graphic. What kind of seedlings will be given away?","qvi":"Nhìn vào hình. Loại cây giống nào sẽ được tặng?","opts":["Eastern redbud","Japanese maple","White fringe tree","Panicle hydrangea"],"vi":["Cây hồng ban phương Đông (Eastern redbud)","Cây phong Nhật Bản","Cây tua rua trắng (White fringe tree)","Cây cẩm tú cầu chùm"],"ans":"A","xp":"Cô ấy nói: 'We'll be giving away the tallest of these four varieties' (tặng loại cao nhất). Theo bảng, cây cao nhất là Eastern redbud (9 mét) → (A)."}],"a":"E24-T02-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hi, I'd like a large black coffee and an egg-and-cheese croissant, please.","Chào chị, cho tôi một ly cà phê đen cỡ lớn và một bánh sừng bò trứng phô mai."],["W","Sure. That'll be eight dollars. Are you a Shelby's preferred customer?","Vâng. Của anh hết tám đô-la. Anh có phải là khách hàng ưu tiên của Shelby's không?"],["M","Uh, no I'm not. But I do have an EZ-Cash card.","À, không phải. Nhưng tôi có thẻ EZ-Cash."],["W","Great. Let me ring that up for you.","Tốt quá. Để tôi tính tiền cho anh."],["M","By the way, I'd like to order breakfast for my team tomorrow morning. Can I place that order ahead of time?","À này, tôi muốn đặt bữa sáng cho nhóm của tôi vào sáng mai. Tôi đặt trước được không?"],["W","Sure. Would you like to do that now?","Được ạ. Anh có muốn đặt luôn bây giờ không?"],["M","No, I'll call you later today when I know what everyone wants. Thanks for the information.","Không, chiều nay khi biết mọi người muốn ăn gì tôi sẽ gọi điện cho chị. Cảm ơn chị đã cho biết."]],"qs":[{"n":68,"q":"Where does the conversation most likely take place?","qvi":"Cuộc hội thoại có khả năng diễn ra ở đâu nhất?","opts":["At a café","At an electronics shop","At a stationery store","At a clothing store"],"vi":["Ở quán cà phê","Ở cửa hàng điện tử","Ở cửa hàng văn phòng phẩm","Ở cửa hàng quần áo"],"ans":"A","xp":"Người đàn ông gọi món: 'I'd like a large black coffee and an egg-and-cheese croissant' → họ đang ở quán cà phê."},{"n":69,"q":"Look at the graphic. How much will the man save on his purchase?","qvi":"Nhìn vào hình. Người đàn ông sẽ tiết kiệm được bao nhiêu cho lần mua này?","opts":["5%","3%","7%","2%"],"vi":["5%","3%","7%","2%"],"ans":"D","xp":"Anh ấy không phải khách ưu tiên nhưng nói 'I do have an EZ-Cash card', người phụ nữ đáp 'Great. Let me ring that up' → trả bằng thẻ EZ-Cash. Theo bảng, 'Pay with EZ-Cash card' được giảm 2% → (D). (Hóa đơn 8 đô nên không đạt mức 'Spend $10 or more'.)"},{"n":70,"q":"What does the man say he will do later today?","qvi":"Người đàn ông nói chiều nay anh ấy sẽ làm gì?","opts":["Call a business","Return some merchandise","Fill out an online survey","Hang up some posters"],"vi":["Gọi điện cho cửa hàng","Trả lại hàng","Điền khảo sát trực tuyến","Treo áp phích"],"ans":"A","xp":"Anh ấy nói: 'I'll call you later today when I know what everyone wants' → sẽ gọi điện cho quán (một cơ sở kinh doanh) = Call a business."}],"a":"E24-T02-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Hi, Amina. This is Sabine calling from Blue Drop Creations. I just put the earrings and necklaces that you ordered from me in the mail. Because you've been a customer for over ten years, I've also included a special gift in the package for you. It's a case for your jewelry. This is a new product that I'm starting to offer, so please call me back after you receive it. I'd really like to hear your thoughts on it.","Chào Amina. Mình là Sabine gọi từ Blue Drop Creations. Mình vừa gửi bưu điện những đôi bông tai và dây chuyền bạn đặt mua. Vì bạn đã là khách hàng hơn mười năm nay, mình có tặng kèm một món quà đặc biệt trong gói hàng. Đó là một hộp đựng trang sức. Đây là sản phẩm mới mình bắt đầu bán, nên khi nhận được hàng, bạn gọi lại cho mình nhé. Mình rất muốn nghe bạn nhận xét về nó."]],"qs":[{"n":71,"q":"Who most likely is the speaker?","qvi":"Người nói có khả năng là ai nhất?","opts":["An art gallery owner","A hairstylist","A clothing designer","A jewelry maker"],"vi":["Chủ phòng tranh","Thợ làm tóc","Nhà thiết kế quần áo","Người làm trang sức"],"ans":"D","xp":"Người nói cho biết: 'I just put the earrings and necklaces that you ordered from me in the mail' → khách đặt bông tai, dây chuyền từ cô ấy → cô ấy là người làm trang sức. earrings, necklaces = jewelry."},{"n":72,"q":"Why did the speaker include a special gift?","qvi":"Tại sao người nói tặng kèm một món quà đặc biệt?","opts":["Because the listener is a new customer","Because the listener is celebrating a special occasion","Because the listener is a loyal customer","Because the listener placed a large order"],"vi":["Vì người nghe là khách hàng mới","Vì người nghe đang kỷ niệm một dịp đặc biệt","Vì người nghe là khách hàng thân thiết","Vì người nghe đặt một đơn hàng lớn"],"ans":"C","xp":"Cô ấy nói: 'Because you've been a customer for over ten years, I've also included a special gift' → vì là khách hàng lâu năm. a customer for over ten years = a loyal customer."},{"n":73,"q":"Why is the listener asked to return a phone call?","qvi":"Tại sao người nghe được đề nghị gọi lại?","opts":["To give feedback","To confirm receipt of an order","To update a payment method","To provide an address"],"vi":["Để đưa ra ý kiến phản hồi","Để xác nhận đã nhận hàng","Để cập nhật phương thức thanh toán","Để cung cấp địa chỉ"],"ans":"A","xp":"Cô ấy nói: 'please call me back after you receive it. I'd really like to hear your thoughts on it' → muốn nghe nhận xét về sản phẩm mới. your thoughts = feedback."}],"a":"E24-T02-71-73.mp3"},{"ns":[74,76],"script":[["","Good morning, this is Brandon from Dakota Framing Company, returning your call. We received your voicemail about wanting to frame a wedding picture. There is no need to print the photo yourself. We prefer that you e-mail us a digital copy. So, to answer your question, you can complete the whole order online. Just visit our Web site, where you'll fill in your choices for photo size and the frame and upload your photo. And for a small extra cost, we'll guarantee to replace your frame in case of damage. Please be sure to check that box when you order.","Chào buổi sáng, tôi là Brandon từ Công ty Khung ảnh Dakota, gọi lại cho anh/chị. Chúng tôi đã nhận được tin nhắn thoại về việc anh/chị muốn đóng khung một bức ảnh cưới. Anh/chị không cần tự in ảnh. Chúng tôi muốn anh/chị gửi e-mail bản kỹ thuật số hơn. Vậy, để trả lời câu hỏi của anh/chị: anh/chị có thể hoàn tất toàn bộ đơn hàng trực tuyến. Chỉ cần truy cập trang web của chúng tôi, chọn kích thước ảnh và loại khung rồi tải ảnh lên. Và với một khoản phí nhỏ thêm, chúng tôi bảo đảm thay khung mới nếu khung bị hư hỏng. Hãy nhớ đánh dấu vào ô đó khi đặt hàng nhé."]],"qs":[{"n":74,"q":"What does the listener want to do?","qvi":"Người nghe muốn làm gì?","opts":["Hire a caterer","Purchase a painting","Have a printer repaired","Have a photograph framed"],"vi":["Thuê dịch vụ ăn uống","Mua một bức tranh","Nhờ sửa máy in","Đóng khung một bức ảnh"],"ans":"D","xp":"Người nói: 'We received your voicemail about wanting to frame a wedding picture' → người nghe muốn đóng khung ảnh cưới. frame a wedding picture = Have a photograph framed."},{"n":75,"q":"What does the speaker expect the listener to do on a Web site?","qvi":"Người nói mong người nghe làm gì trên trang web?","opts":["View a list of prices","Place an order","Schedule a time to meet","Read customer reviews"],"vi":["Xem bảng giá","Đặt hàng","Hẹn giờ gặp mặt","Đọc đánh giá của khách hàng"],"ans":"B","xp":"Người nói: 'you can complete the whole order online. Just visit our Web site, where you'll fill in your choices... and upload your photo' → đặt hàng trên trang web = Place an order."},{"n":76,"q":"What is included for an extra fee?","qvi":"Điều gì được cung cấp nếu trả thêm phí?","opts":["Shipping","An artist's signature","A newsletter","A warranty"],"vi":["Vận chuyển","Chữ ký của nghệ sĩ","Bản tin","Bảo hành"],"ans":"D","xp":"Người nói: 'for a small extra cost, we'll guarantee to replace your frame in case of damage' → trả thêm phí sẽ được bảo đảm thay khung khi hư hỏng = A warranty (bảo hành)."}],"a":"E24-T02-74-76.mp3"},{"ns":[77,79],"script":[["","Welcome all to this week's training in our series of patient care programs. Our physical therapy center is known for the excellent care we provide to our patients, and that's because of you, our staff. The training today will be about ways to engage the patients who reside in our facility through playing games. I've prepared different types of activities for us to try out, including some games that involve mental stimulation as well as physical exercises. But, I have to let you know that today I must leave at noon. Next week we'll try out more of the games.","Chào mừng tất cả mọi người đến với buổi đào tạo tuần này trong chuỗi chương trình chăm sóc bệnh nhân. Trung tâm vật lý trị liệu của chúng ta nổi tiếng nhờ sự chăm sóc tuyệt vời dành cho bệnh nhân, và đó là nhờ các bạn, đội ngũ nhân viên. Buổi đào tạo hôm nay sẽ nói về các cách thu hút, gắn kết những bệnh nhân đang lưu trú tại cơ sở thông qua việc chơi trò chơi. Tôi đã chuẩn bị nhiều loại hoạt động khác nhau để chúng ta thử, bao gồm một số trò chơi kích thích trí não cũng như các bài tập thể chất. Nhưng tôi phải báo trước là hôm nay tôi phải về lúc 12 giờ trưa. Tuần sau chúng ta sẽ thử thêm các trò chơi khác."]],"qs":[{"n":77,"q":"Who are the listeners?","qvi":"Người nghe là ai?","opts":["Hotel receptionists","Health-care staff","Customer-service representatives","Fitness trainers"],"vi":["Lễ tân khách sạn","Nhân viên y tế","Nhân viên chăm sóc khách hàng","Huấn luyện viên thể hình"],"ans":"B","xp":"Người nói: 'Welcome all to this week's training in our series of patient care programs. Our physical therapy center...' và gọi người nghe là 'our staff' → họ là nhân viên y tế (trung tâm vật lý trị liệu)."},{"n":78,"q":"What has the speaker prepared?","qvi":"Người nói đã chuẩn bị gì?","opts":["Activities","Food","Certificates","A video"],"vi":["Các hoạt động","Đồ ăn","Giấy chứng nhận","Một đoạn video"],"ans":"A","xp":"Người nói: 'I've prepared different types of activities for us to try out' → đã chuẩn bị các hoạt động."},{"n":79,"q":"What does the speaker imply when he says, \"I must leave at noon\"?","qvi":"Người nói ngụ ý gì khi nói \"I must leave at noon\"?","opts":["He would like permission to leave.","He cannot join a luncheon.","A colleague will fill in for him.","Some material will not be covered today."],"vi":["Anh ấy muốn xin phép về.","Anh ấy không thể dự bữa trưa.","Một đồng nghiệp sẽ làm thay anh ấy.","Một số nội dung sẽ không được học trong hôm nay."],"ans":"D","xp":"Anh ấy vừa nói đã chuẩn bị nhiều hoạt động, rồi nói phải về lúc trưa và 'Next week we'll try out more of the games' → ngụ ý hôm nay không kịp làm hết, một phần nội dung để tuần sau."}],"a":"E24-T02-77-79.mp3"},{"ns":[80,82],"script":[["","Are you a certified commercial truck driver? Hoffman Oversized Haulers is currently looking for experienced truck drivers to join our team. As our name suggests, we transport oversized cargo throughout the region. With Hoffman, drivers enjoy flexible scheduling. In fact, we're the only company in the region that allows employees to determine their own work hours. If you don't have experience working with oversized loads, training is available. Please check out our Web site to learn more about our open positions. We can't wait to work with you.","Bạn có phải là tài xế xe tải thương mại có bằng lái không? Công ty Vận tải Hàng quá khổ Hoffman hiện đang tìm các tài xế xe tải có kinh nghiệm gia nhập đội ngũ. Đúng như tên gọi, chúng tôi vận chuyển hàng hóa quá khổ khắp khu vực. Làm việc với Hoffman, tài xế được hưởng lịch làm việc linh hoạt. Thực tế, chúng tôi là công ty duy nhất trong khu vực cho phép nhân viên tự quyết định giờ làm của mình. Nếu bạn chưa có kinh nghiệm chở hàng quá khổ, chúng tôi có đào tạo. Hãy truy cập trang web của chúng tôi để tìm hiểu thêm về các vị trí đang tuyển. Chúng tôi rất mong được làm việc cùng bạn."]],"qs":[{"n":80,"q":"What is the purpose of the advertisement?","qvi":"Mục đích của quảng cáo là gì?","opts":["To announce a contest","To promote an upcoming sale","To introduce new services","To recruit employees"],"vi":["Thông báo một cuộc thi","Quảng bá đợt giảm giá sắp tới","Giới thiệu dịch vụ mới","Tuyển nhân viên"],"ans":"D","xp":"Người nói: 'Hoffman Oversized Haulers is currently looking for experienced truck drivers to join our team' → quảng cáo tuyển dụng tài xế."},{"n":81,"q":"How is the speaker's company different from its competitors?","qvi":"Công ty của người nói khác các đối thủ cạnh tranh ở điểm nào?","opts":["It is dependable.","It produces innovative products.","It offers flexible schedules.","It pays employees well."],"vi":["Công ty đáng tin cậy.","Công ty sản xuất sản phẩm đột phá.","Công ty có lịch làm việc linh hoạt.","Công ty trả lương cao."],"ans":"C","xp":"Người nói: 'drivers enjoy flexible scheduling. In fact, we're the only company in the region that allows employees to determine their own work hours' → điểm khác biệt là lịch làm việc linh hoạt."},{"n":82,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Complete a survey","Fill out an application","Place an order","Get more information"],"vi":["Hoàn thành khảo sát","Điền đơn ứng tuyển","Đặt hàng","Tìm hiểu thêm thông tin"],"ans":"D","xp":"Người nói: 'Please check out our Web site to learn more about our open positions' → tìm hiểu thêm thông tin. learn more = Get more information. (B) là bẫy vì không nhắc đến việc điền đơn."}],"a":"E24-T02-80-82.mp3"},{"ns":[83,85],"script":[["","Hi, Jinyu. I have some exciting news! The Farmer's Table television program wants to feature our restaurant in an upcoming episode. They'll be coming on Wednesday to film everyone in the kitchen during our dinner service. Since you're the executive chef, I'll need you to come in earlier than usual to get everything prepped and set up. And just as a reminder, I'm still planning to be out of town next week for the Springdale Pastry and Dessert Festival. Thanks!","Chào Jinyu. Tôi có tin vui đây! Chương trình truyền hình The Farmer's Table muốn giới thiệu nhà hàng mình trong một tập sắp tới. Thứ Tư họ sẽ đến quay mọi người trong bếp trong giờ phục vụ bữa tối. Vì anh là bếp trưởng, tôi cần anh đến sớm hơn thường lệ để sơ chế và chuẩn bị mọi thứ. Và nhắc lại là tuần sau tôi vẫn định đi vắng để dự Lễ hội Bánh ngọt và Tráng miệng Springdale. Cảm ơn anh!"]],"qs":[{"n":83,"q":"What is the message mainly about?","qvi":"Tin nhắn chủ yếu nói về điều gì?","opts":["Revising a restaurant menu","Filming for a television show","Launching an advertising campaign","Renovating a kitchen"],"vi":["Sửa đổi thực đơn nhà hàng","Quay phim cho một chương trình truyền hình","Khởi động chiến dịch quảng cáo","Cải tạo nhà bếp"],"ans":"B","xp":"Người nói: 'The Farmer's Table television program wants to feature our restaurant in an upcoming episode. They'll be coming on Wednesday to film everyone' → chủ đề là việc quay chương trình truyền hình."},{"n":84,"q":"What does the speaker ask the listener to do on Wednesday?","qvi":"Người nói yêu cầu người nghe làm gì vào thứ Tư?","opts":["Come to work early","Experiment with new ingredients","Train an employee","Prepare for a safety inspection"],"vi":["Đi làm sớm","Thử nghiệm nguyên liệu mới","Đào tạo một nhân viên","Chuẩn bị cho đợt kiểm tra an toàn"],"ans":"A","xp":"Người nói: 'They'll be coming on Wednesday... I'll need you to come in earlier than usual' → đi làm sớm. come in earlier than usual = Come to work early."},{"n":85,"q":"Where will the speaker go next week?","qvi":"Tuần sau người nói sẽ đi đâu?","opts":["To a food festival","To a cooking class","To a farmers market","To a bakery opening"],"vi":["Đến một lễ hội ẩm thực","Đến một lớp nấu ăn","Đến một chợ nông sản","Đến lễ khai trương tiệm bánh"],"ans":"A","xp":"Người nói: 'I'm still planning to be out of town next week for the Springdale Pastry and Dessert Festival' → đi lễ hội bánh ngọt và tráng miệng = a food festival."}],"a":"E24-T02-83-85.mp3"},{"ns":[86,88],"script":[["","Good evening and thank you for watching Channel Four News. I'm here in Rockville, a suburb in the metropolitan area. Rockville was recently chosen as the site of a multimillion-dollar electric vehicle battery factory. This project promises to bring thousands of jobs, both directly and indirectly, to the surrounding community. At a recent well-attended public comment meeting, residents had a chance to voice any opposition to the project. No one made any comments. To learn more about this exciting development, artist-rendered images of the project are on display at the city hall building.","Chào buổi tối và cảm ơn quý vị đã theo dõi Bản tin Kênh Bốn. Tôi đang ở Rockville, một vùng ngoại ô thuộc khu vực đô thị. Rockville vừa được chọn làm địa điểm xây dựng một nhà máy sản xuất pin xe điện trị giá hàng triệu đô-la. Dự án hứa hẹn mang lại hàng nghìn việc làm, cả trực tiếp lẫn gián tiếp, cho cộng đồng xung quanh. Tại một buổi họp lấy ý kiến công chúng gần đây với đông người tham dự, cư dân đã có cơ hội bày tỏ sự phản đối dự án. Không ai đưa ra ý kiến gì. Để tìm hiểu thêm về dự án phát triển thú vị này, quý vị có thể xem các hình ảnh phối cảnh do họa sĩ thực hiện được trưng bày tại tòa thị chính."]],"qs":[{"n":86,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu bàn về điều gì?","opts":["A job fair","A factory","Some traffic patterns","A prototype electric vehicle"],"vi":["Một hội chợ việc làm","Một nhà máy","Tình hình giao thông","Một mẫu xe điện thử nghiệm"],"ans":"B","xp":"Người nói: 'Rockville was recently chosen as the site of a multimillion-dollar electric vehicle battery factory' và cả bản tin nói về dự án này → chủ đề là một nhà máy. (D) là bẫy: nhà máy làm pin xe điện, không phải mẫu xe điện."},{"n":87,"q":"What does the speaker imply when he says, \"No one made any comments\"?","qvi":"Người nói ngụ ý gì khi nói \"No one made any comments\"?","opts":["Few people were in attendance.","Another meeting will be scheduled.","A project has community support.","A public comment period has ended."],"vi":["Rất ít người tham dự.","Sẽ lên lịch một cuộc họp khác.","Dự án được cộng đồng ủng hộ.","Thời gian lấy ý kiến công chúng đã kết thúc."],"ans":"C","xp":"Trước đó: 'At a recent well-attended public comment meeting, residents had a chance to voice any opposition to the project.' → buổi họp đông người, ai phản đối cũng có thể nói, nhưng không ai lên tiếng → ngụ ý dự án được cộng đồng ủng hộ. (A) sai vì buổi họp 'well-attended' (đông người)."},{"n":88,"q":"What can the public view at the city hall building?","qvi":"Công chúng có thể xem gì tại tòa thị chính?","opts":["An official contract","Some images","A list of companies","Some facts about local politicians"],"vi":["Một hợp đồng chính thức","Một số hình ảnh","Danh sách các công ty","Một số thông tin về chính trị gia địa phương"],"ans":"B","xp":"Người nói: 'artist-rendered images of the project are on display at the city hall building' → có thể xem hình ảnh dự án."}],"a":"E24-T02-86-88.mp3"},{"ns":[89,91],"script":[["","Tired of losing things on your desk because it's too cluttered? If so, the Optimum Space Organizer is the perfect product for you. Designed with office employees like you in mind, this product can make even the messiest of desks look neat again. Best of all, the organizer adjusts to any sized space you may have on your desk. It can be as narrow or as wide as you need it to be—within seconds! If you call in the next ten minutes, you'll receive a 30 percent discount!","Bạn mệt mỏi vì cứ thất lạc đồ trên bàn làm việc do bàn quá bừa bộn? Nếu vậy, Optimum Space Organizer là sản phẩm hoàn hảo dành cho bạn. Được thiết kế dành riêng cho nhân viên văn phòng như bạn, sản phẩm này có thể khiến ngay cả chiếc bàn bừa bộn nhất cũng trở nên gọn gàng trở lại. Tuyệt vời nhất là kệ sắp xếp này có thể điều chỉnh vừa với mọi khoảng trống trên bàn của bạn. Nó có thể hẹp hoặc rộng tùy theo nhu cầu – chỉ trong vài giây! Nếu gọi điện trong mười phút tới, bạn sẽ được giảm giá 30%!"]],"qs":[{"n":89,"q":"What type of product is being advertised?","qvi":"Loại sản phẩm nào đang được quảng cáo?","opts":["A floor lamp","A bookshelf","An office chair","A desk organizer"],"vi":["Đèn cây đứng","Kệ sách","Ghế văn phòng","Kệ sắp xếp đồ trên bàn"],"ans":"D","xp":"Người nói: 'the Optimum Space Organizer is the perfect product for you... this product can make even the messiest of desks look neat again' → kệ sắp xếp đồ trên bàn làm việc."},{"n":90,"q":"What special feature does the speaker emphasize?","qvi":"Người nói nhấn mạnh tính năng đặc biệt nào?","opts":["It is durable.","It is adjustable.","It is easy to assemble.","It is available in many colors."],"vi":["Nó bền.","Nó điều chỉnh được.","Nó dễ lắp ráp.","Nó có nhiều màu."],"ans":"B","xp":"Người nói: 'Best of all, the organizer adjusts to any sized space... It can be as narrow or as wide as you need' → điều chỉnh được. adjusts = adjustable."},{"n":91,"q":"How can the listeners receive a discount?","qvi":"Người nghe có thể được giảm giá bằng cách nào?","opts":["By calling within a time limit","By entering an e-mail address","By referring a product to a friend","By using a mobile phone application"],"vi":["Gọi điện trong thời hạn quy định","Nhập địa chỉ e-mail","Giới thiệu sản phẩm cho bạn bè","Dùng ứng dụng điện thoại"],"ans":"A","xp":"Người nói: 'If you call in the next ten minutes, you'll receive a 30 percent discount!' → gọi trong vòng 10 phút. in the next ten minutes = within a time limit."}],"a":"E24-T02-89-91.mp3"},{"ns":[92,94],"script":[["","Thanks for listening to this episode of Fabulous Foods. Every week, we discuss a different vegetable and ways to cook with it to maximize flavor. Now, before we get started, I'm excited to announce that I've been collaborating with Cartwell Kitchen Supplies to develop a new line of cookware. It'll be released in November, but it's available for preorder right now. Keep in mind, this product line will not be available for long. OK, let's move on to our program. With us today is renowned chef Rebecca Murray to talk about this week's vegetable: eggplant! Rebecca recently launched a vegetarian restaurant in New York that is getting rave reviews so far.","Cảm ơn quý vị đã nghe tập này của Fabulous Foods. Mỗi tuần, chúng tôi bàn về một loại rau củ khác nhau và các cách nấu để tối đa hóa hương vị. Trước khi bắt đầu, tôi rất vui được thông báo rằng tôi đã hợp tác với Cartwell Kitchen Supplies để phát triển một dòng dụng cụ nấu ăn mới. Sản phẩm sẽ ra mắt vào tháng Mười Một, nhưng hiện đã có thể đặt trước. Xin lưu ý, dòng sản phẩm này sẽ không được bán lâu đâu. Được rồi, chúng ta vào chương trình nhé. Hôm nay cùng chúng tôi là đầu bếp nổi tiếng Rebecca Murray để nói về loại rau của tuần này: cà tím! Rebecca vừa mở một nhà hàng chay ở New York và đến nay đang nhận được những lời khen ngợi nồng nhiệt."]],"qs":[{"n":92,"q":"According to the speaker, what is the purpose of the podcast?","qvi":"Theo người nói, mục đích của podcast là gì?","opts":["To discuss the restaurant industry","To review new cooking equipment","To share information about nutrition","To showcase individual ingredients"],"vi":["Bàn về ngành nhà hàng","Đánh giá dụng cụ nấu ăn mới","Chia sẻ thông tin về dinh dưỡng","Giới thiệu từng loại nguyên liệu"],"ans":"D","xp":"Người nói: 'Every week, we discuss a different vegetable and ways to cook with it' → mỗi tuần giới thiệu một loại rau củ (nguyên liệu) = showcase individual ingredients."},{"n":93,"q":"Why does the speaker say, \"this product line will not be available for long\"?","qvi":"Tại sao người nói nói \"this product line will not be available for long\"?","opts":["To encourage the listeners to place an order","To apologize to the listeners for a product shortage","To justify a high price","To criticize a business decision"],"vi":["Để khuyến khích người nghe đặt hàng","Để xin lỗi người nghe vì thiếu hàng","Để biện minh cho giá cao","Để chỉ trích một quyết định kinh doanh"],"ans":"A","xp":"Ngay trước đó người nói giới thiệu dòng dụng cụ nấu ăn mới 'available for preorder right now' → nói 'sẽ không bán lâu đâu' nhằm thúc người nghe đặt hàng sớm."},{"n":94,"q":"According to the speaker, what did Rebecca Murray recently do?","qvi":"Theo người nói, gần đây Rebecca Murray đã làm gì?","opts":["She published a cookbook.","She launched a culinary training course.","She opened a restaurant.","She traveled abroad."],"vi":["Cô ấy xuất bản sách dạy nấu ăn.","Cô ấy mở một khóa đào tạo nấu ăn.","Cô ấy mở một nhà hàng.","Cô ấy đi du lịch nước ngoài."],"ans":"C","xp":"Người nói: 'Rebecca recently launched a vegetarian restaurant in New York' → vừa mở nhà hàng. launched = opened. (B) là bẫy vì cũng dùng từ launched."}],"a":"E24-T02-92-94.mp3"},{"ns":[95,97],"script":[["","Attention passengers. Renovation work to upgrade and modernize our train station is underway. We apologize for the inconvenience the construction noise may cause. Please note that regional train schedules are not affected. Train 133 with service to Washington, D.C., will be arriving shortly. All passengers to Washington, please proceed to Track 26B. If you need assistance handling your baggage, please speak to a ticket agent immediately. Train 133's next stop will be Wilmington, followed by Baltimore and then Washington, D.C.","Xin quý khách chú ý. Công trình cải tạo nhằm nâng cấp và hiện đại hóa nhà ga đang được tiến hành. Chúng tôi xin lỗi vì sự bất tiện mà tiếng ồn thi công có thể gây ra. Xin lưu ý rằng lịch tàu khu vực không bị ảnh hưởng. Tàu số 133 đi Washington, D.C. sắp đến ga. Tất cả hành khách đi Washington vui lòng di chuyển đến đường ray 26B. Nếu cần hỗ trợ mang hành lý, quý khách vui lòng liên hệ ngay nhân viên bán vé. Ga tiếp theo của tàu 133 là Wilmington, sau đó là Baltimore rồi đến Washington, D.C."]],"qs":[{"n":95,"q":"Why does the speaker apologize?","qvi":"Tại sao người nói xin lỗi?","opts":["There is construction noise at the station.","There are no more seats available on a train.","A printed schedule has incorrect information.","A train service has been delayed."],"vi":["Có tiếng ồn thi công ở nhà ga.","Trên tàu không còn chỗ ngồi.","Lịch trình in ra có thông tin sai.","Một chuyến tàu bị trễ."],"ans":"A","xp":"Người nói: 'Renovation work... is underway. We apologize for the inconvenience the construction noise may cause' → xin lỗi vì tiếng ồn thi công. (D) sai vì 'regional train schedules are not affected'."},{"n":96,"q":"According to the speaker, why may some listeners need to see an agent?","qvi":"Theo người nói, tại sao một số người nghe có thể cần gặp nhân viên?","opts":["To ask for a refund","To request baggage service","To purchase a monthly pass","To arrange a transfer"],"vi":["Để yêu cầu hoàn tiền","Để yêu cầu dịch vụ hành lý","Để mua vé tháng","Để sắp xếp chuyển tàu"],"ans":"B","xp":"Người nói: 'If you need assistance handling your baggage, please speak to a ticket agent immediately' → cần hỗ trợ hành lý. assistance handling your baggage = baggage service."},{"n":97,"q":"Look at the graphic. When is Train 133 scheduled to arrive at its next stop?","qvi":"Nhìn vào hình. Tàu 133 dự kiến đến ga tiếp theo lúc mấy giờ?","opts":["At 10:45 A.M.","At 12:05 P.M.","At 1:00 P.M.","At 1:30 P.M."],"vi":["Lúc 10:45 sáng","Lúc 12:05 trưa","Lúc 1:00 chiều","Lúc 1:30 chiều"],"ans":"B","xp":"Người nói: 'Train 133's next stop will be Wilmington' → theo bảng giờ, tàu đến Wilmington lúc 12:05 P.M. → (B)."}],"a":"E24-T02-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Hello, everyone. I'm Carmen Salazar, the airport operations director, and I wanted to thank you for attending this press conference. As of this week, construction on the new regional airport is proceeding on schedule for two of the three terminals. Minor design adjustments to terminal A have put the project slightly behind schedule, and we anticipate about two months will be added to the construction time frame as a result. I'd also like to mention that we now have a 3-D printed model of this project! Please feel free to visit our Web site so you can view it.","Xin chào mọi người. Tôi là Carmen Salazar, giám đốc điều hành sân bay, và tôi muốn cảm ơn quý vị đã đến dự buổi họp báo này. Tính đến tuần này, việc xây dựng sân bay khu vực mới đang đúng tiến độ ở hai trong ba nhà ga. Một vài điều chỉnh nhỏ về thiết kế ở nhà ga A đã khiến dự án chậm tiến độ một chút, và chúng tôi dự kiến thời gian thi công sẽ kéo dài thêm khoảng hai tháng. Tôi cũng muốn nói thêm là hiện chúng tôi đã có mô hình in 3D của dự án này! Mời quý vị truy cập trang web của chúng tôi để xem."]],"qs":[{"n":98,"q":"Who most likely are the listeners?","qvi":"Người nghe có khả năng là ai nhất?","opts":["Civil engineers","Urban planners","News reporters","Safety inspectors"],"vi":["Kỹ sư xây dựng","Nhà quy hoạch đô thị","Phóng viên báo chí","Thanh tra an toàn"],"ans":"C","xp":"Người nói: 'I wanted to thank you for attending this press conference' → người nghe dự họp báo → họ là phóng viên."},{"n":99,"q":"Look at the graphic. Which of the following companies will be affected by a delay?","qvi":"Nhìn vào hình. Công ty nào sau đây sẽ bị ảnh hưởng bởi sự chậm trễ?","opts":["Selca Air","Trilco Airlines","Heathson Airways","Bluxtin Airlines"],"vi":["Selca Air","Trilco Airlines","Heathson Airways","Bluxtin Airlines"],"ans":"A","xp":"Người nói: 'Minor design adjustments to terminal A have put the project slightly behind schedule' → nhà ga A bị chậm. Theo sơ đồ, Terminal A gồm Gristar Airlines và Selca Air → trong các lựa chọn chỉ có Selca Air → (A)."},{"n":100,"q":"What does the speaker invite the listeners to do?","qvi":"Người nói mời người nghe làm gì?","opts":["Download some designs","Look at a model","Take a site tour","View a Webcam"],"vi":["Tải xuống một số bản thiết kế","Xem một mô hình","Tham quan công trường","Xem webcam"],"ans":"B","xp":"Người nói: 'we now have a 3-D printed model of this project! Please feel free to visit our Web site so you can view it' → mời xem mô hình. view = look at."}],"a":"E24-T02-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Before operating your handheld device, please ------- the enclosed cable to charge it.","opts":["plan","remain","use","finish"],"ans":"C","xp":"Từ vựng (động từ). Cần động từ đi với tân ngữ 'the enclosed cable' (dây cáp kèm theo) và mục đích 'to charge it' (để sạc). (C) use = sử dụng → hợp nghĩa. (A) plan = lên kế hoạch, (B) remain = vẫn còn (nội động từ, không có tân ngữ), (D) finish = hoàn thành → không hợp.\nDịch: Trước khi vận hành thiết bị cầm tay, vui lòng sử dụng dây cáp kèm theo để sạc nó."},{"n":102,"q":"Safile's new external hard drive can ------- store up to one terabyte of data.","opts":["secure","security","securely","secured"],"ans":"C","xp":"Từ loại. Chỗ trống nằm giữa động từ khiếm khuyết 'can' và động từ chính 'store' → cần trạng từ bổ nghĩa cho động từ. (C) securely (một cách an toàn) là trạng từ → chọn (C). (A) secure là tính từ/động từ, (B) security là danh từ, (D) secured là quá khứ phân từ.\nDịch: Ổ cứng gắn ngoài mới của Safile có thể lưu trữ an toàn tới một terabyte dữ liệu."},{"n":103,"q":"Mr. Peterson will travel ------- the Tokyo office for the annual meeting.","opts":["to","through","in","over"],"ans":"A","xp":"Giới từ. 'travel to + nơi đến' = đi đến đâu. Ông Peterson đi đến văn phòng Tokyo → (A) to. (B) through = xuyên qua, (C) in = ở trong, (D) over = phía trên/khắp → không hợp.\nDịch: Ông Peterson sẽ đi đến văn phòng Tokyo để dự cuộc họp thường niên."},{"n":104,"q":"Yong-Soo Cosmetics will not charge for items on back order until ------- have left our warehouse.","opts":["them","they","themselves","their"],"ans":"B","xp":"Đại từ. 'until' là liên từ, sau nó là một mệnh đề; chỗ trống đứng trước động từ 'have left' → cần đại từ làm chủ ngữ. (B) they (chúng) thay cho 'items' → chọn (B). (A) them là tân ngữ, (C) themselves là đại từ phản thân, (D) their là tính từ sở hữu (phải có danh từ theo sau).\nDịch: Mỹ phẩm Yong-Soo sẽ không tính tiền cho các mặt hàng đang chờ bổ sung hàng cho đến khi chúng đã rời khỏi kho của chúng tôi."},{"n":105,"q":"Our premium day tour takes visitors to historic sites ------- the Aprico River.","opts":["onto","since","inside","along"],"ans":"D","xp":"Giới từ. Các di tích lịch sử nằm dọc theo con sông → 'along the river' = dọc theo sông. (D) along → chọn. (A) onto = lên trên, (B) since = kể từ (thời gian), (C) inside = bên trong → không hợp với 'con sông'.\nDịch: Tour cao cấp trong ngày của chúng tôi đưa du khách đến các di tích lịch sử dọc theo sông Aprico."},{"n":106,"q":"Eighty percent of drivers surveyed said they would consider buying a vehicle that runs on -------.","opts":["electricity","electrically","electricians","electrify"],"ans":"A","xp":"Từ loại. Sau giới từ 'on' cần danh từ. 'run on electricity' = chạy bằng điện → (A) electricity (điện). (C) electricians (thợ điện) cũng là danh từ nhưng sai nghĩa; (B) electrically là trạng từ, (D) electrify là động từ.\nDịch: Tám mươi phần trăm số tài xế được khảo sát cho biết họ sẽ cân nhắc mua một chiếc xe chạy bằng điện."},{"n":107,"q":"Xinzhe Zu has ------- Petrin Engineering as the vice president of operations.","opts":["attached","resigned","joined","combined"],"ans":"C","xp":"Từ vựng (động từ). Cần động từ có tân ngữ là một công ty và đi với 'as + chức vụ': 'join + công ty + as ...' = gia nhập công ty với vai trò ... → (C) joined. (A) attached = gắn vào, (B) resigned = từ chức (phải là 'resigned from'), (D) combined = kết hợp.\nDịch: Xinzhe Zu đã gia nhập Petrin Engineering với vai trò phó chủ tịch phụ trách vận hành."},{"n":108,"q":"Next month, Barder House Books will be holding ------- third author's hour in Cleveland.","opts":["it","itself","its own","its"],"ans":"D","xp":"Đại từ. Chỗ trống đứng trước cụm danh từ 'third author's hour' → cần tính từ sở hữu. (D) its (của nó, tức của Barder House Books) → chọn. (A) it là đại từ chủ ngữ/tân ngữ, (B) itself là đại từ phản thân, (C) its own (của riêng nó) mang nghĩa nhấn mạnh, không phù hợp đứng trước 'third author's hour' trong câu này.\nDịch: Tháng tới, nhà sách Barder House sẽ tổ chức buổi 'giờ gặp gỡ tác giả' lần thứ ba của mình tại Cleveland."},{"n":109,"q":"Chester's Tiles ------- expanded to a second location in Turnington.","opts":["severely","usually","recently","exactly"],"ans":"C","xp":"Từ vựng (trạng từ). Động từ ở quá khứ 'expanded' (đã mở rộng) → hợp với (C) recently = gần đây. (A) severely = nghiêm trọng, (B) usually = thường xuyên (dùng với thì hiện tại đơn), (D) exactly = chính xác → không hợp nghĩa.\nDịch: Chester's Tiles gần đây đã mở rộng sang địa điểm thứ hai ở Turnington."},{"n":110,"q":"Tabrino's has ------- increased the number of almonds in the Nut Medley snack pack.","opts":["significant","significance","signifies","significantly"],"ans":"D","xp":"Từ loại. Chỗ trống nằm giữa trợ động từ 'has' và quá khứ phân từ 'increased' → cần trạng từ. (D) significantly (đáng kể) → chọn. (A) significant là tính từ, (B) significance là danh từ, (C) signifies là động từ.\nDịch: Tabrino's đã tăng đáng kể số lượng hạnh nhân trong gói snack Nut Medley."},{"n":111,"q":"------- she travels, Jacintha Flores collects samples of local fabrics and patterns.","opts":["Wherever","In addition to","Either","In contrast to"],"ans":"A","xp":"Liên từ. Sau chỗ trống là mệnh đề 'she travels' → cần liên từ nối hai mệnh đề. (A) Wherever = bất cứ nơi nào → chọn. (B) In addition to và (D) In contrast to là giới từ (theo sau phải là danh từ), (C) Either đi với 'or'.\nDịch: Bất cứ nơi nào cô đến, Jacintha Flores đều thu thập mẫu vải và hoa văn của địa phương."},{"n":112,"q":"Most picture ------- at Glowing Photo Lab go on sale at 3:00 P.M. today.","opts":["framer","framing","framed","frames"],"ans":"D","xp":"Từ loại / danh từ ghép. 'Most + danh từ số nhiều' và động từ 'go' (số nhiều) → cần danh từ số nhiều. 'picture frames' = khung ảnh → (D) frames. (A) framer (người đóng khung) số ít và sai nghĩa, (B) framing, (C) framed không hợp.\nDịch: Hầu hết khung ảnh tại Glowing Photo Lab sẽ được giảm giá vào lúc 3 giờ chiều hôm nay."},{"n":113,"q":"All students in the business management class hold ------- college degrees.","opts":["late","developed","advanced","elated"],"ans":"C","xp":"Từ vựng (tính từ). Cụm cố định 'advanced degree' = bằng cấp cao (thạc sĩ, tiến sĩ) → (C) advanced. (A) late = muộn, (B) developed = phát triển (dùng cho quốc gia, sản phẩm), (D) elated = phấn khởi → không hợp.\nDịch: Tất cả sinh viên trong lớp quản trị kinh doanh đều có bằng cấp cao (sau đại học)."},{"n":114,"q":"We hired Noah Wan of Shengyao Accounting Ltd. ------- our company's financial assets.","opts":["to evaluate","to be evaluated","will be evaluated","evaluate"],"ans":"A","xp":"Dạng động từ. Câu đã có động từ chính 'hired' → chỗ trống cần 'to V' chỉ mục đích (thuê ai để làm gì). Có tân ngữ 'our company's financial assets' → cần dạng chủ động → (A) to evaluate (để đánh giá). (B) to be evaluated là bị động, (C) will be evaluated và (D) evaluate là động từ chia, không đứng sau động từ chính được.\nDịch: Chúng tôi đã thuê ông Noah Wan của công ty Kế toán Shengyao để đánh giá tài sản tài chính của công ty."},{"n":115,"q":"Ms. Charisse is taking on a new account ------- she finishes the Morrison project.","opts":["with","going","after","between"],"ans":"C","xp":"Liên từ. Sau chỗ trống là mệnh đề 'she finishes the Morrison project' → cần liên từ. (C) after (sau khi) vừa là giới từ vừa là liên từ → chọn. (A) with và (D) between là giới từ, (B) going là V-ing.\nDịch: Cô Charisse sẽ nhận một khách hàng mới sau khi cô hoàn thành dự án Morrison."},{"n":116,"q":"Cormet Motors' profits are ------- this year than last year.","opts":["higher","high","highly","highest"],"ans":"A","xp":"So sánh. Có 'than' → cần so sánh hơn. (A) higher (cao hơn) → chọn. (B) high là dạng nguyên, (C) highly là trạng từ, (D) highest là so sánh nhất.\nDịch: Lợi nhuận của Cormet Motors năm nay cao hơn năm ngoái."},{"n":117,"q":"In its ------- advertising campaign, Jaymor Tools demonstrates how reliable its products are.","opts":["current","relative","spacious","collected"],"ans":"A","xp":"Từ vựng (tính từ). Cần tính từ bổ nghĩa cho 'advertising campaign' (chiến dịch quảng cáo). (A) current = hiện tại → hợp nghĩa. (B) relative = tương đối, (C) spacious = rộng rãi (dùng cho không gian), (D) collected = được thu thập → không hợp.\nDịch: Trong chiến dịch quảng cáo hiện tại, Jaymor Tools cho thấy sản phẩm của họ đáng tin cậy như thế nào."},{"n":118,"q":"Remember to submit receipts for reimbursement ------- returning from a business trip.","opts":["such as","when","then","within"],"ans":"B","xp":"Liên từ. 'when + V-ing' là dạng rút gọn của mệnh đề thời gian (when you return → when returning). (B) when (khi) → chọn. (A) such as = chẳng hạn như, (C) then = sau đó (trạng từ), (D) within = trong vòng (theo sau là khoảng thời gian/phạm vi).\nDịch: Hãy nhớ nộp hóa đơn để được hoàn tiền khi trở về từ chuyến công tác."},{"n":119,"q":"Patrons will be able to access Westside Library's ------- acquired collection of books on Tuesday.","opts":["instantly","newly","early","naturally"],"ans":"B","xp":"Từ vựng (trạng từ). Cụm 'newly acquired' = mới được mua về/mới nhập → (B) newly. (A) instantly = ngay lập tức, (C) early = sớm, (D) naturally = tự nhiên → không hợp với 'acquired collection'.\nDịch: Bạn đọc sẽ có thể tiếp cận bộ sưu tập sách mới được bổ sung của Thư viện Westside vào thứ Ba."},{"n":120,"q":"Please ------- any questions about time sheets to Tabitha Jones in the payroll department.","opts":["direction","directive","directed","direct"],"ans":"D","xp":"Từ loại. Câu mệnh lệnh 'Please + động từ nguyên mẫu'. 'direct + câu hỏi + to + người' = chuyển/gửi câu hỏi đến ai → (D) direct. (A) direction và (B) directive là danh từ, (C) directed là quá khứ.\nDịch: Vui lòng gửi mọi thắc mắc về bảng chấm công đến cô Tabitha Jones ở phòng tính lương."},{"n":121,"q":"Before signing a delivery -------, be sure to double-check that all the items ordered are in the shipment.","opts":["decision","announcement","receipt","limit"],"ans":"C","xp":"Từ vựng (danh từ). Thứ được ký khi nhận hàng là 'delivery receipt' = phiếu/biên nhận giao hàng → (C) receipt. (A) decision = quyết định, (B) announcement = thông báo, (D) limit = giới hạn → không hợp.\nDịch: Trước khi ký biên nhận giao hàng, hãy nhớ kiểm tra lại xem tất cả các món đã đặt có trong lô hàng không."},{"n":122,"q":"Funds have been added to the budget for expenses ------- with the new building.","opts":["associated","association","associate","associates"],"ans":"A","xp":"Rút gọn mệnh đề quan hệ. Câu đã có động từ chính 'have been added' → chỗ trống bổ nghĩa cho 'expenses'. 'expenses (which are) associated with ...' = chi phí liên quan đến ... → dùng quá khứ phân từ (A) associated. (B) association là danh từ, (C)(D) là động từ chia.\nDịch: Ngân sách đã được bổ sung tiền cho các chi phí liên quan đến tòa nhà mới."},{"n":123,"q":"Ms. Bernard ------- that a deadline was approaching, so she requested some assistance.","opts":["noticed","obscured","withdrew","appeared"],"ans":"A","xp":"Từ vựng (động từ). Cần động từ + mệnh đề 'that': 'notice that ...' = nhận thấy rằng ... → (A) noticed. Hợp logic: nhận thấy hạn chót sắp đến nên nhờ giúp đỡ. (B) obscured = che khuất, (C) withdrew = rút lui/rút tiền, (D) appeared = xuất hiện (không đi với chủ ngữ người + that theo nghĩa này).\nDịch: Cô Bernard nhận thấy hạn chót đang đến gần, nên cô đã đề nghị được hỗ trợ."},{"n":124,"q":"Mr. Moscowitz is ------- that Dr. Tanaka will agree to present the keynote speech at this year's conference.","opts":["hopes","hoped","hopeful","hopefully"],"ans":"C","xp":"Từ loại. Sau động từ 'to be' (is) cần tính từ; cấu trúc 'be hopeful that ...' = hy vọng rằng ... → (C) hopeful. (A) hopes là động từ, (B) hoped (is hoped là bị động, không hợp với chủ ngữ người), (D) hopefully là trạng từ.\nDịch: Ông Moscowitz hy vọng rằng Tiến sĩ Tanaka sẽ đồng ý trình bày bài phát biểu chính tại hội nghị năm nay."},{"n":125,"q":"Two Australian companies are developing new smartphones, but it is unclear ------- phone will become available first.","opts":["if","which","before","because"],"ans":"B","xp":"Từ để hỏi / mệnh đề danh từ. Sau chỗ trống là danh từ 'phone' rồi đến động từ → cần từ hạn định đứng trước danh từ: 'which phone' = điện thoại nào. Có hai công ty → hỏi chiếc nào ra mắt trước → (B) which. (A) if = liệu/nếu, (C) before = trước khi, (D) because = vì → không đứng trước danh từ theo cách này.\nDịch: Hai công ty Úc đang phát triển điện thoại thông minh mới, nhưng chưa rõ điện thoại nào sẽ ra mắt trước."},{"n":126,"q":"Corners Gym offers its members a free lesson in how to use ------- properly.","opts":["weighs","weights","weighty","weighed"],"ans":"B","xp":"Từ loại. Sau động từ 'use' cần danh từ làm tân ngữ. (B) weights (tạ) là danh từ → chọn; hợp với ngữ cảnh phòng gym. (A) weighs là động từ, (C) weighty là tính từ, (D) weighed là quá khứ.\nDịch: Phòng tập Corners Gym cung cấp cho hội viên một buổi học miễn phí về cách sử dụng tạ đúng cách."},{"n":127,"q":"------- the rules, overnight parking is not permitted at the clubhouse facility.","opts":["Prior to","Except for","Instead of","According to"],"ans":"D","xp":"Giới từ. 'According to the rules' = theo quy định → (D). (A) Prior to = trước khi, (B) Except for = ngoại trừ, (C) Instead of = thay vì → không hợp nghĩa.\nDịch: Theo quy định, không được phép đỗ xe qua đêm tại khu nhà câu lạc bộ."},{"n":128,"q":"Once everyone -------, we can begin the conference call.","opts":["arrived","is arriving","to arrive","has arrived"],"ans":"D","xp":"Thì của động từ. 'Once' (một khi) là liên từ thời gian; mệnh đề chính nói về tương lai ('we can begin') → mệnh đề thời gian dùng hiện tại hoàn thành để chỉ hành động hoàn tất trước → (D) has arrived. (A) arrived là quá khứ, (B) is arriving (đang đến) không hợp nghĩa, (C) to arrive không phải động từ chia.\nDịch: Một khi mọi người đã đến đủ, chúng ta có thể bắt đầu cuộc họp qua điện thoại."},{"n":129,"q":"Each summer a motivational video that highlights the past year's ------- is shown to all company employees.","opts":["preferences","accomplishments","communications","uncertainties"],"ans":"B","xp":"Từ vựng (danh từ). Video truyền động lực (motivational) nêu bật những thành tựu của năm qua → (B) accomplishments = thành tựu. (A) preferences = sở thích, (C) communications = sự giao tiếp, (D) uncertainties = điều không chắc chắn → không hợp.\nDịch: Mỗi mùa hè, một video truyền động lực nêu bật những thành tựu của năm qua được chiếu cho toàn bộ nhân viên công ty."},{"n":130,"q":"Employees who wish to attend the retirement dinner ------- Ms. Howell's 30 years of service should contact Mr. Lee.","opts":["honor","to honor","will honor","will be honored"],"ans":"B","xp":"Dạng động từ. Câu đã có động từ chính 'should contact' (chủ ngữ 'Employees who wish...') → chỗ trống cần 'to V' chỉ mục đích của bữa tiệc: bữa tối để vinh danh → (B) to honor. (A)(C)(D) là động từ chia, không thể thêm vào.\nDịch: Những nhân viên muốn tham dự bữa tiệc chia tay nghỉ hưu để vinh danh 30 năm cống hiến của bà Howell nên liên hệ với ông Lee."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Myung-Hee Hahn</p><p><b>From:</b> Dellwyn Home Store</p><p><b>Date:</b> January 15</p><p><b>Subject:</b> Order update</p></div><p>Dear Ms. Hahn,</p><p>Your <span class=\"blank\" data-n=\"131\">-------</span> order of a red oak dining table and six matching chairs arrived at our store this morning. We would now like to arrange for the delivery of the <span class=\"blank\" data-n=\"132\">-------</span>. Please call us at 517-555-0188 and ask <span class=\"blank\" data-n=\"133\">-------</span> to Coleman Cobb, our delivery manager. <span class=\"blank\" data-n=\"134\">-------</span>.</p><p>Customer Service, Dellwyn Home Store</p>","vi":"Người nhận: Myung-Hee Hahn\nNgười gửi: Cửa hàng Đồ gia dụng Dellwyn\nNgày: 15 tháng 1\nTiêu đề: Cập nhật đơn hàng\n\nKính gửi cô Hahn,\n\nĐơn hàng đặt riêng gồm một bàn ăn gỗ sồi đỏ và sáu chiếc ghế đồng bộ của cô đã về đến cửa hàng chúng tôi sáng nay. Bây giờ chúng tôi muốn sắp xếp việc giao số đồ nội thất này. Vui lòng gọi cho chúng tôi theo số 517-555-0188 và xin được nói chuyện với ông Coleman Cobb, quản lý giao hàng của chúng tôi. Ông ấy có thể sắp xếp một thời gian thuận tiện.\n\nBộ phận Chăm sóc Khách hàng, Cửa hàng Đồ gia dụng Dellwyn","qs":[{"n":131,"opts":["specially","specialize","special","specializing"],"ans":"C","xp":"Từ loại. Chỗ trống nằm giữa tính từ sở hữu 'Your' và danh từ 'order' → cần tính từ. (C) special (đặc biệt) → 'special order' = đơn đặt hàng riêng/đặt theo yêu cầu. (A) specially là trạng từ, (B) specialize là động từ, (D) specializing là V-ing (chuyên về) sai nghĩa.\nDịch: Đơn hàng đặt riêng gồm một bàn ăn gỗ sồi đỏ và sáu chiếc ghế đồng bộ của cô đã về đến cửa hàng sáng nay."},{"n":132,"opts":["furniture","appliances","refund","tools"],"ans":"A","xp":"Từ vựng (danh từ). Câu trước nhắc đến 'a red oak dining table and six matching chairs' (bàn ăn và ghế) → đây là đồ nội thất → (A) furniture. (B) appliances = thiết bị điện gia dụng, (C) refund = tiền hoàn lại, (D) tools = dụng cụ → không đúng.\nDịch: Bây giờ chúng tôi muốn sắp xếp việc giao số đồ nội thất này."},{"n":133,"opts":["speak","spoken","is speaking","to speak"],"ans":"D","xp":"Dạng động từ. Cấu trúc 'ask to V' = xin/đề nghị được làm gì → 'ask to speak to Coleman Cobb' = xin được nói chuyện với Coleman Cobb → (D) to speak. Các dạng còn lại không theo sau 'ask' được.\nDịch: Vui lòng gọi cho chúng tôi theo số 517-555-0188 và xin được nói chuyện với ông Coleman Cobb, quản lý giao hàng."},{"n":134,"opts":["He can schedule a convenient time.","He began working here yesterday.","He can meet you at 11:00 A.M.","He recently moved to Dellwyn."],"ans":"A","xp":"Điền câu. Câu trước giới thiệu Coleman Cobb là quản lý giao hàng và mục đích cuộc gọi là sắp xếp việc giao hàng ('arrange for the delivery'). Câu (A) 'Ông ấy có thể sắp xếp một thời gian thuận tiện' nối tiếp hợp lý: gọi cho ông ấy để hẹn giờ giao. (B) mới bắt đầu làm việc hôm qua, (D) mới chuyển đến Dellwyn → không liên quan; (C) gặp lúc 11 giờ sáng → đã cố định giờ, mâu thuẫn với việc phải gọi để sắp xếp.\n(A) Ông ấy có thể sắp xếp một thời gian thuận tiện.\n(B) Ông ấy bắt đầu làm việc ở đây hôm qua.\n(C) Ông ấy có thể gặp cô lúc 11 giờ sáng.\n(D) Ông ấy mới chuyển đến Dellwyn."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following advertisement.","passage":"<h3>Keep Cool Service Contractors:<br>67 Main Road, Edinburgh Village<br>Chaguanas, Trinidad and Tobago</h3><p>Keep Cool Service Contractors can bring you peace of mind. As part of an annual contract, we will service your air-conditioning system, ensuring your <span class=\"blank\" data-n=\"135\">-------</span> and comfort. This includes inspecting the system, making repairs as needed, and professionally cleaning your air ducts. <span class=\"blank\" data-n=\"136\">-------</span>, if necessary, we can replace your old air-conditioning system with a new, cost-efficient one.</p><p>Our workers are highly qualified licensed technicians who stay up-to-date with ongoing training. <span class=\"blank\" data-n=\"137\">-------</span>. We promise you fair prices and professional work, <span class=\"blank\" data-n=\"138\">-------</span> by our Keep Cool guarantee. Call 1-868-555-0129 for a free quote today.</p>","vi":"Keep Cool Service Contractors (Nhà thầu Dịch vụ Keep Cool):\n67 Main Road, Edinburgh Village\nChaguanas, Trinidad và Tobago\n\nKeep Cool Service Contractors có thể mang lại cho bạn sự an tâm. Trong khuôn khổ hợp đồng hằng năm, chúng tôi sẽ bảo dưỡng hệ thống điều hòa không khí của bạn, đảm bảo sự an toàn và thoải mái cho bạn. Dịch vụ này bao gồm kiểm tra hệ thống, sửa chữa khi cần và vệ sinh chuyên nghiệp các ống dẫn khí. Hơn nữa, nếu cần, chúng tôi có thể thay hệ thống điều hòa cũ của bạn bằng một hệ thống mới, tiết kiệm chi phí.\n\nNhân viên của chúng tôi là những kỹ thuật viên có giấy phép, trình độ cao, luôn cập nhật kiến thức qua các khóa đào tạo liên tục. Thêm vào đó, họ thân thiện, sạch sẽ và am hiểu. Chúng tôi cam kết mang đến cho bạn giá cả hợp lý và dịch vụ chuyên nghiệp, được bảo đảm bằng chính sách bảo hành Keep Cool. Hãy gọi 1-868-555-0129 để nhận báo giá miễn phí ngay hôm nay.","qs":[{"n":135,"opts":["safe","safely","safest","safety"],"ans":"D","xp":"Từ loại. Sau tính từ sở hữu 'your' và song song với danh từ 'comfort' qua 'and' → cần danh từ. (D) safety (sự an toàn) → chọn. (A) safe là tính từ, (B) safely là trạng từ, (C) safest là so sánh nhất.\nDịch: Chúng tôi sẽ bảo dưỡng hệ thống điều hòa của bạn, đảm bảo sự an toàn và thoải mái cho bạn."},{"n":136,"opts":["On one hand","Nonetheless","Furthermore","And yet"],"ans":"C","xp":"Trạng từ liên kết. Câu trước liệt kê các dịch vụ (kiểm tra, sửa chữa, vệ sinh); câu này thêm một dịch vụ nữa (thay hệ thống mới) → quan hệ bổ sung → (C) Furthermore (hơn nữa). (A) On one hand = một mặt (phải đi với 'on the other hand'), (B) Nonetheless và (D) And yet = tuy nhiên (tương phản) → không hợp.\nDịch: Hơn nữa, nếu cần, chúng tôi có thể thay hệ thống điều hòa cũ của bạn bằng một hệ thống mới, tiết kiệm chi phí."},{"n":137,"opts":["Take advantage of dozens of useful online tools.","Moreover, the air conditioner you chose is very popular.","Plus, they are friendly, clean, and knowledgeable.","Thank you for visiting our contractor showroom."],"ans":"C","xp":"Điền câu. Câu trước nói về nhân viên: 'Our workers are highly qualified licensed technicians...'. Câu (C) tiếp tục khen nhân viên, với 'Plus' (thêm vào đó) và 'they' = 'Our workers' → liên kết chặt chẽ. (A) công cụ trực tuyến, (B) máy điều hòa bạn đã chọn (người đọc quảng cáo chưa chọn gì), (D) cảm ơn đã ghé phòng trưng bày → không liên quan.\n(A) Hãy tận dụng hàng chục công cụ trực tuyến hữu ích.\n(B) Hơn nữa, chiếc máy điều hòa bạn chọn rất được ưa chuộng.\n(C) Thêm vào đó, họ thân thiện, sạch sẽ và am hiểu.\n(D) Cảm ơn bạn đã ghé thăm phòng trưng bày của chúng tôi."},{"n":138,"opts":["backed","backs","backing","back"],"ans":"A","xp":"Dạng động từ (phân từ). Câu đã có động từ chính 'promise'; cụm sau dấu phẩy bổ nghĩa cho 'fair prices and professional work' và có 'by' (bởi) → nghĩa bị động: 'được bảo đảm bởi' → quá khứ phân từ (A) backed (back = hậu thuẫn, bảo đảm). (C) backing là chủ động, (B)(D) là động từ chia.\nDịch: Chúng tôi cam kết mang đến cho bạn giá cả hợp lý và dịch vụ chuyên nghiệp, được bảo đảm bằng chính sách bảo hành Keep Cool."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> All Customers</p><p><b>From:</b> asquires@lightidea.com</p><p><b>Date:</b> March 6</p><p><b>Subject:</b> Information</p></div><p>Dear Light Idea Customers,</p><p>Light Idea is enacting a price increase on select energy-efficient products, effective April 17. Specific product pricing will <span class=\"blank\" data-n=\"139\">-------</span>. Please contact your sales representative for details and questions.</p><p>The last date for ordering at current prices is April 16. All orders <span class=\"blank\" data-n=\"140\">-------</span> after this date will follow the new price list. <span class=\"blank\" data-n=\"141\">-------</span>. Customers will be able to find this on our Web site.</p><p>We will continue to provide quality products and <span class=\"blank\" data-n=\"142\">-------</span> service to our valued customers. Thank you for your business.</p><p>Sincerely,</p><p>Arvin Squires<br>Head of Sales, Light Idea</p>","vi":"Người nhận: Tất cả khách hàng\nNgười gửi: asquires@lightidea.com\nNgày: 6 tháng 3\nTiêu đề: Thông tin\n\nKính gửi Quý khách hàng của Light Idea,\n\nLight Idea sẽ tăng giá một số sản phẩm tiết kiệm năng lượng được chọn, có hiệu lực từ ngày 17 tháng 4. Giá của từng sản phẩm cụ thể sẽ khác nhau. Vui lòng liên hệ đại diện bán hàng của quý khách để biết chi tiết và giải đáp thắc mắc.\n\nNgày cuối cùng đặt hàng theo giá hiện tại là 16 tháng 4. Tất cả đơn hàng nhận được sau ngày này sẽ áp dụng bảng giá mới. Bảng giá cập nhật sẽ có vào ngày 20 tháng 3. Quý khách có thể tìm thấy bảng giá này trên trang web của chúng tôi.\n\nChúng tôi sẽ tiếp tục cung cấp sản phẩm chất lượng và dịch vụ xuất sắc cho những khách hàng quý giá của mình. Cảm ơn quý khách đã ủng hộ.\n\nTrân trọng,\n\nArvin Squires\nTrưởng phòng Kinh doanh, Light Idea","qs":[{"n":139,"opts":["agree","vary","wait","decline"],"ans":"B","xp":"Từ vựng (động từ). Chỉ 'một số sản phẩm' tăng giá, và câu sau bảo liên hệ đại diện bán hàng để biết chi tiết → giá từng sản phẩm sẽ khác nhau → (B) vary = thay đổi, khác nhau. (A) agree = đồng ý, (C) wait = chờ, (D) decline = giảm (mâu thuẫn với việc tăng giá).\nDịch: Giá của từng sản phẩm cụ thể sẽ khác nhau."},{"n":140,"opts":["receiving","having received","received","will be received"],"ans":"C","xp":"Rút gọn mệnh đề quan hệ. Câu đã có động từ chính 'will follow' → chỗ trống bổ nghĩa cho 'All orders'. Đơn hàng 'được nhận' → nghĩa bị động → quá khứ phân từ (C) received (= orders which are received). (A) receiving, (B) having received mang nghĩa chủ động, (D) will be received là động từ chia, không thể thêm.\nDịch: Tất cả đơn hàng nhận được sau ngày này sẽ áp dụng bảng giá mới."},{"n":141,"opts":["The updated price list will be available on March 20.","We apologize for this inconvenience.","Your orders will be shipped after April 17.","We are increasing prices because of rising costs."],"ans":"A","xp":"Điền câu. Câu trước nhắc 'the new price list', câu sau nói 'Customers will be able to find this on our Web site' — 'this' phải chỉ một thứ có thể tìm trên web → bảng giá. Câu (A) 'Bảng giá cập nhật sẽ có vào ngày 20/3' tạo cầu nối cho 'this'. (B)(C)(D) không có danh từ nào để 'this ... on our Web site' thay thế hợp lý.\n(A) Bảng giá cập nhật sẽ có vào ngày 20 tháng 3.\n(B) Chúng tôi xin lỗi vì sự bất tiện này.\n(C) Đơn hàng của quý khách sẽ được giao sau ngày 17 tháng 4.\n(D) Chúng tôi tăng giá vì chi phí tăng."},{"n":142,"opts":["exceptionally","exception","exceptional","exceptionalism"],"ans":"C","xp":"Từ loại. Chỗ trống đứng trước danh từ 'service' và song song với 'quality products' → cần tính từ. (C) exceptional (xuất sắc, vượt trội) → chọn. (A) exceptionally là trạng từ, (B) exception (ngoại lệ) và (D) exceptionalism là danh từ.\nDịch: Chúng tôi sẽ tiếp tục cung cấp sản phẩm chất lượng và dịch vụ xuất sắc cho những khách hàng quý giá."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Jang-Ho Kwon &lt;jkwon@newart.nz&gt;</p><p><b>From:</b> Kenneth Okim &lt;k.okim@okimjewelry.nz&gt;</p><p><b>Subject:</b> Good news</p><p><b>Date:</b> 30 August</p></div><p>Dear Jang-Ho,</p><p>Thank you for the shipment last month of 80 units of your jewelry pieces. I am happy to report that they have been selling very well in my shop. My <span class=\"blank\" data-n=\"143\">-------</span> love the colourful designs as well as the quality of your workmanship. <span class=\"blank\" data-n=\"144\">-------</span>.</p><p>I would like to increase the number of units I order from you. Would you be able to <span class=\"blank\" data-n=\"145\">-------</span> my order for the September shipment?</p><p>Finally, I would like to discuss the possibility of featuring your work exclusively in my store. I believe that I could reach your target audience best and that the agreement would serve <span class=\"blank\" data-n=\"146\">-------</span> both very well. I look forward to hearing from you.</p><p>Best regards,</p><p>Kenneth Okim<br>Okim Jewelry</p>","vi":"Người nhận: Jang-Ho Kwon <jkwon@newart.nz>\nNgười gửi: Kenneth Okim <k.okim@okimjewelry.nz>\nTiêu đề: Tin vui\nNgày: 30 tháng 8\n\nAnh Jang-Ho thân mến,\n\nCảm ơn anh về lô hàng 80 món trang sức tháng trước. Tôi rất vui được báo rằng chúng đang bán rất chạy ở cửa hàng của tôi. Khách hàng của tôi rất thích những thiết kế đầy màu sắc cũng như chất lượng tay nghề của anh. Giá cả hợp lý cũng khiến các sản phẩm của anh trở nên rất đáng tiền.\n\nTôi muốn tăng số lượng sản phẩm đặt từ anh. Anh có thể tăng gấp đôi đơn hàng của tôi cho lô hàng tháng 9 được không?\n\nCuối cùng, tôi muốn bàn về khả năng trưng bày độc quyền các sản phẩm của anh tại cửa hàng của tôi. Tôi tin rằng tôi có thể tiếp cận tốt nhất nhóm khách hàng mục tiêu của anh và thỏa thuận này sẽ rất có lợi cho cả hai chúng ta. Tôi mong sớm nhận được hồi âm của anh.\n\nTrân trọng,\n\nKenneth Okim\nOkim Jewelry","qs":[{"n":143,"opts":["patients","students","customers","teammates"],"ans":"C","xp":"Từ vựng (danh từ). Câu trước: trang sức 'selling very well in my shop' (bán rất chạy ở cửa hàng của tôi) → những người yêu thích thiết kế là khách hàng của cửa hàng → (C) customers. (A) patients = bệnh nhân, (B) students = học sinh, (D) teammates = đồng đội → không hợp.\nDịch: Khách hàng của tôi rất thích những thiết kế đầy màu sắc cũng như chất lượng tay nghề của anh."},{"n":144,"opts":["If you need more time, please let me know.","Unfortunately, I do not have adequate shelf space at this time.","I would like to show you some of my own designs.","The reasonable prices also make your pieces a great value."],"ans":"D","xp":"Điền câu. Câu trước liệt kê lý do khách thích sản phẩm (thiết kế, tay nghề). Câu (D) thêm một lý do nữa với từ 'also' (cũng): giá hợp lý → rất đáng tiền. (B) không đủ chỗ trưng bày → mâu thuẫn với việc muốn đặt thêm hàng; (A) cần thêm thời gian, (C) muốn cho xem thiết kế của mình → không liên quan.\n(A) Nếu anh cần thêm thời gian, hãy cho tôi biết.\n(B) Đáng tiếc là hiện tôi không có đủ chỗ trên kệ.\n(C) Tôi muốn cho anh xem một số thiết kế của riêng tôi.\n(D) Giá cả hợp lý cũng khiến sản phẩm của anh rất đáng tiền."},{"n":145,"opts":["include","double","repeat","insure"],"ans":"B","xp":"Từ vựng (động từ). Câu trước: 'I would like to increase the number of units' (muốn tăng số lượng) → hỏi có thể tăng gấp đôi đơn hàng không → (B) double = tăng gấp đôi. (A) include = bao gồm, (C) repeat = lặp lại (giữ nguyên số lượng, không phải tăng), (D) insure = bảo hiểm.\nDịch: Anh có thể tăng gấp đôi đơn hàng của tôi cho lô hàng tháng 9 được không?"},{"n":146,"opts":["us","you","we","these"],"ans":"A","xp":"Đại từ. Sau động từ 'serve' cần đại từ tân ngữ; 'us both' = cả hai chúng ta (người viết và người nhận). Thỏa thuận có lợi cho cả hai bên → (A) us. (C) we là chủ ngữ; (B) you both chỉ phía người nhận, không gồm người viết; (D) these không hợp.\nDịch: Tôi tin rằng thỏa thuận này sẽ rất có lợi cho cả hai chúng ta."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following invitation.","passages":["<h3>Focus Your Social Media Presence</h3><p>For small-business owners, it can be a challenge to stand out in a competitive social media environment. Successfully reaching your target market involves knowing how and where to promote your products in a way that is effective and memorable. The Savan Business Center offers support for business owners who need a boost in doing just that. For over 50 years, we've been helping entrepreneurs grow their sales through insight of current industry trends and understanding of our clients' unique needs.</p><p>Let us help you get more organized in creating effective and far-reaching social media content. Our latest webinar, Focus Your Social Media Presence, will cover topics related to making your business stand out. You can sign up on our event Web page.</p><p><b>Date:</b> February 5<br><b>Time:</b> 10:00 A.M. to 11:00 A.M.<br><b>Event Web page:</b> https://www.savanbusinesscenter.com/socialmedia</p>"],"vi":"Tập trung vào sự hiện diện trên mạng xã hội\n\nĐối với các chủ doanh nghiệp nhỏ, việc nổi bật trong một môi trường mạng xã hội đầy cạnh tranh có thể là một thách thức. Tiếp cận thành công thị trường mục tiêu đòi hỏi bạn phải biết quảng bá sản phẩm như thế nào và ở đâu sao cho hiệu quả và dễ nhớ. Trung tâm Doanh nghiệp Savan hỗ trợ những chủ doanh nghiệp cần được tiếp sức để làm được điều đó. Hơn 50 năm qua, chúng tôi đã giúp các doanh nhân tăng doanh số nhờ hiểu biết về xu hướng hiện tại của ngành và sự thấu hiểu nhu cầu riêng của từng khách hàng.\n\nHãy để chúng tôi giúp bạn tổ chức tốt hơn trong việc tạo ra nội dung mạng xã hội hiệu quả và có sức lan tỏa rộng. Hội thảo trực tuyến mới nhất của chúng tôi, Focus Your Social Media Presence, sẽ đề cập đến các chủ đề liên quan đến việc làm cho doanh nghiệp của bạn nổi bật. Bạn có thể đăng ký trên trang web sự kiện của chúng tôi.\n\nNgày: 5 tháng 2\nThời gian: 10:00 sáng đến 11:00 sáng\nTrang web sự kiện: https://www.savanbusinesscenter.com/socialmedia","qs":[{"n":147,"q":"What is true about the Savan Business Center?","qvi":"Điều gì đúng về Trung tâm Doanh nghiệp Savan?","opts":["It works with small businesses.","It publishes a weekly newsletter.","It recently launched a new Web site.","It is seeking suggestions for webinar topics."],"ans":"A","xp":"Câu hỏi chi tiết (thông tin đúng). Đoạn đầu viết: \"For small-business owners...\" và \"The Savan Business Center offers support for business owners who need a boost\" → trung tâm hỗ trợ các chủ doanh nghiệp nhỏ = làm việc với doanh nghiệp nhỏ → chọn (A). Bản tin hằng tuần, trang web mới hay xin gợi ý chủ đề đều không được nhắc đến.\n(A) Trung tâm làm việc với các doanh nghiệp nhỏ.\n(B) Trung tâm xuất bản bản tin hằng tuần.\n(C) Trung tâm vừa ra mắt trang web mới.\n(D) Trung tâm đang tìm gợi ý cho chủ đề hội thảo trực tuyến."},{"n":148,"q":"What is indicated about the webinar?","qvi":"Điều gì được nêu về hội thảo trực tuyến?","opts":["It begins at 11:00 A.M.","It features advice on creating promotional content.","It is being offered every month.","It requires a small fee to attend."],"ans":"B","xp":"Câu hỏi chi tiết. \"Let us help you get more organized in creating effective and far-reaching social media content. Our latest webinar... will cover topics related to making your business stand out.\" → hội thảo hướng dẫn tạo nội dung mạng xã hội để quảng bá doanh nghiệp = lời khuyên về tạo nội dung quảng bá → (B). (A) sai vì hội thảo bắt đầu lúc 10:00 (11:00 là giờ kết thúc). (C), (D) không được nhắc đến.\n(A) Hội thảo bắt đầu lúc 11 giờ sáng.\n(B) Hội thảo có lời khuyên về việc tạo nội dung quảng bá.\n(C) Hội thảo được tổ chức hằng tháng.\n(D) Phải trả một khoản phí nhỏ để tham dự."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following announcement.","passages":["<h3>Dine Out Darville Is Back!</h3><p>Dine Out Darville, which runs this year from June 22 to 28, is the perfect chance to try a restaurant in Darville for the first time or revisit one of your favorite restaurants in town. You might even visit multiple restaurants during the weeklong event! Twelve popular restaurants will offer special four-course dinners—including a cup of soup, a salad, a main course, and a dessert—all for a reduced price of $30. Reservations are highly recommended. Dine Out Darville welcomes hundreds of locals and tourists each year, and you do not want to miss your opportunity to get a great meal at a great price.</p><p>Visit www.darvillebusinesscouncil.org/dineout for a list of participating restaurants.</p>"],"vi":"Dine Out Darville đã trở lại!\n\nDine Out Darville, năm nay diễn ra từ ngày 22 đến 28 tháng 6, là cơ hội hoàn hảo để thử một nhà hàng ở Darville lần đầu tiên hoặc quay lại một trong những nhà hàng yêu thích của bạn trong thị trấn. Bạn thậm chí có thể ghé nhiều nhà hàng trong suốt sự kiện kéo dài một tuần này! Mười hai nhà hàng nổi tiếng sẽ phục vụ bữa tối đặc biệt bốn món — gồm một chén súp, một đĩa salad, một món chính và một món tráng miệng — tất cả với giá ưu đãi 30 đô la. Rất nên đặt chỗ trước. Mỗi năm Dine Out Darville chào đón hàng trăm người dân địa phương và khách du lịch, và bạn sẽ không muốn bỏ lỡ cơ hội thưởng thức một bữa ăn tuyệt vời với giá tuyệt vời.\n\nHãy truy cập www.darvillebusinesscouncil.org/dineout để xem danh sách các nhà hàng tham gia.","qs":[{"n":149,"q":"What is mentioned about Dine Out Darville?","qvi":"Điều gì được đề cập về Dine Out Darville?","opts":["It lasts for one week.","It is held in a different location each year.","It is being held for the first time.","It includes both lunch and dinner."],"ans":"A","xp":"Câu hỏi chi tiết. \"runs this year from June 22 to 28\" và \"during the weeklong event\" → sự kiện kéo dài một tuần → (A). (B) không nhắc đến; (C) sai vì tiêu đề \"Is Back!\" và \"welcomes hundreds of locals and tourists each year\" cho thấy đã tổ chức nhiều năm; (D) sai vì chỉ có \"four-course dinners\" (bữa tối).\n(A) Sự kiện kéo dài một tuần.\n(B) Sự kiện được tổ chức ở địa điểm khác nhau mỗi năm.\n(C) Sự kiện được tổ chức lần đầu tiên.\n(D) Sự kiện gồm cả bữa trưa và bữa tối."},{"n":150,"q":"What is NOT included in the reduced-price meals?","qvi":"Điều gì KHÔNG có trong các bữa ăn giá ưu đãi?","opts":["A cup of soup","A salad","A dessert","A beverage"],"ans":"D","xp":"Câu hỏi NOT. \"four-course dinners—including a cup of soup, a salad, a main course, and a dessert\" → có súp (A), salad (B), tráng miệng (C). Đồ uống (beverage) không được nhắc đến → chọn (D).\n(A) Một chén súp\n(B) Một đĩa salad\n(C) Một món tráng miệng\n(D) Một đồ uống"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following article.","passages":["<h3>Rainsy To Move Headquarters</h3><p>DADE (July 11)—Rainsy LLC announced yesterday that it is moving its headquarters to Dade.</p><p>A data storage and analytics firm currently based in Salt Creek, Rainsy has clients that include some of the country's largest credit card companies, online retailers, and software providers. Rainsy helps these businesses manage and understand their customer data.</p><p>Rainsy is not planning to close its current offices in Salt Creek. However, the Dade location will become its new base of operations, as several members of its executive team will work there. The company's chief executive officer and chief financial officer will relocate to Dade along with approximately 50 percent of the company's workforce.</p><p>The office of Rainsy's chief technology officer will remain in Salt Creek, as will the account management team. The company's new Dade offices are located at 12 Glacier Parkway.</p>"],"vi":"Rainsy sẽ chuyển trụ sở chính\n\nDADE (11 tháng 7) — Hôm qua, Công ty Rainsy LLC thông báo sẽ chuyển trụ sở chính đến Dade.\n\nLà một công ty lưu trữ và phân tích dữ liệu hiện có trụ sở tại Salt Creek, Rainsy có khách hàng gồm một số công ty thẻ tín dụng, nhà bán lẻ trực tuyến và nhà cung cấp phần mềm lớn nhất cả nước. Rainsy giúp các doanh nghiệp này quản lý và hiểu dữ liệu khách hàng của họ.\n\nRainsy không có kế hoạch đóng cửa văn phòng hiện tại ở Salt Creek. Tuy nhiên, chi nhánh Dade sẽ trở thành cơ sở hoạt động mới của công ty, vì một số thành viên ban điều hành sẽ làm việc ở đó. Giám đốc điều hành và giám đốc tài chính của công ty sẽ chuyển đến Dade cùng với khoảng 50% lực lượng lao động của công ty.\n\nVăn phòng của giám đốc công nghệ Rainsy sẽ vẫn ở Salt Creek, nhóm quản lý tài khoản cũng vậy. Văn phòng mới của công ty ở Dade nằm tại số 12 Glacier Parkway.","qs":[{"n":151,"q":"What does Rainsy LLC do?","qvi":"Công ty Rainsy LLC làm gì?","opts":["It stores and analyzes consumer information.","It sells technology products online.","It processes credit card payments for retailers.","It develops computer software programs."],"ans":"A","xp":"Câu hỏi chi tiết. \"A data storage and analytics firm... Rainsy helps these businesses manage and understand their customer data.\" → lưu trữ và phân tích dữ liệu khách hàng = stores and analyzes consumer information → (A). Thẻ tín dụng, bán lẻ trực tuyến, phần mềm là lĩnh vực của khách hàng Rainsy, không phải việc Rainsy làm → loại (B), (C), (D).\n(A) Công ty lưu trữ và phân tích thông tin người tiêu dùng.\n(B) Công ty bán sản phẩm công nghệ trực tuyến.\n(C) Công ty xử lý thanh toán thẻ tín dụng cho nhà bán lẻ.\n(D) Công ty phát triển các chương trình phần mềm máy tính."},{"n":152,"q":"Who will be based in Dade?","qvi":"Ai sẽ làm việc tại Dade?","opts":["Rainsy's chief technology officer","The entire Rainsy executive team","About half of Rainsy's employees","The Rainsy account management team"],"ans":"C","xp":"Câu hỏi chi tiết. \"The company's chief executive officer and chief financial officer will relocate to Dade along with approximately 50 percent of the company's workforce.\" → khoảng 50% nhân viên = about half of Rainsy's employees → (C). (A) và (D) sai vì giám đốc công nghệ và nhóm quản lý tài khoản \"will remain in Salt Creek\". (B) sai vì chỉ \"several members of its executive team\" (một số thành viên), không phải toàn bộ.\n(A) Giám đốc công nghệ của Rainsy\n(B) Toàn bộ ban điều hành của Rainsy\n(C) Khoảng một nửa nhân viên của Rainsy\n(D) Nhóm quản lý tài khoản của Rainsy"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Michael Liu (9:43 A.M.)</b></p><p>Hi, Jana. I'm at Biz Plus. The paper you need is out of stock until next week. Will another color work?</p></div><div class=\"msg\"><p><b>Jana Bhat (9:45 A.M.)</b></p><p>What are the options?</p></div><div class=\"msg\"><p><b>Michael Liu (9:46 A.M.)</b></p><p>They have yellow, green, and pink in the brand that you prefer.</p></div><div class=\"msg\"><p><b>Jana Bhat (9:47 A.M.)</b></p><p>I really need blue. Are there other brands of blue printer paper?</p></div><div class=\"msg\"><p><b>Michael Liu (9:48 A.M.)</b></p><p>Yes, but they're all a darker blue. They also cost more.</p></div><div class=\"msg\"><p><b>Jana Bhat (9:49 A.M.)</b></p><p>OK, forget it. I'll place an order online.</p></div>"],"vi":"Michael Liu (9:43 sáng): Chào Jana. Mình đang ở Biz Plus. Loại giấy bạn cần hết hàng đến tuần sau. Màu khác có được không?\n\nJana Bhat (9:45 sáng): Có những lựa chọn nào?\n\nMichael Liu (9:46 sáng): Họ có màu vàng, xanh lá và hồng của nhãn hiệu bạn thích.\n\nJana Bhat (9:47 sáng): Mình thật sự cần màu xanh dương. Có nhãn hiệu giấy in xanh dương nào khác không?\n\nMichael Liu (9:48 sáng): Có, nhưng tất cả đều là màu xanh đậm hơn. Chúng cũng đắt hơn.\n\nJana Bhat (9:49 sáng): Thôi, bỏ đi. Mình sẽ đặt hàng trên mạng.","qs":[{"n":153,"q":"What is suggested about the paper Mr. Liu is shopping for?","qvi":"Có thể suy ra điều gì về loại giấy mà anh Liu đang tìm mua?","opts":["It is light blue.","It is expensive.","It is sold exclusively at Biz Plus.","It has been discontinued."],"ans":"A","xp":"Câu hỏi suy luận. Jana cần giấy màu xanh dương (\"I really need blue\"), và các nhãn hiệu khác \"are all a darker blue\" (đều xanh đậm hơn) → loại giấy cô ấy cần là màu xanh nhạt hơn = light blue → (A). (B) sai: chính các nhãn hiệu khác mới \"cost more\". (C) sai vì Jana có thể đặt mua online. (D) sai: giấy chỉ tạm hết hàng \"until next week\", không phải ngừng sản xuất.\n(A) Giấy màu xanh nhạt.\n(B) Giấy đắt tiền.\n(C) Giấy chỉ được bán độc quyền tại Biz Plus.\n(D) Giấy đã ngừng sản xuất."},{"n":154,"q":"At 9:49 A.M., what does Ms. Bhat most likely mean when she writes, \"OK, forget it\"?","qvi":"Lúc 9:49 sáng, khi viết \"OK, forget it\" (Thôi, bỏ đi), nhiều khả năng cô Bhat có ý gì?","opts":["She wants to check her budget.","She thinks Mr. Liu should not purchase paper at Biz Plus.","She believes Mr. Liu should not place an order this week.","She plans to cancel her order."],"ans":"B","xp":"Câu hỏi hàm ý. Sau khi biết Biz Plus chỉ có màu khác hoặc giấy xanh đậm hơn và đắt hơn, Jana nói \"OK, forget it. I'll place an order online.\" → cô ấy bảo anh Liu đừng mua giấy ở Biz Plus nữa, cô sẽ tự đặt online → (B). (C) sai vì không nói về việc đặt hàng tuần này; (D) sai vì cô ấy sắp đặt hàng chứ không hủy.\n(A) Cô ấy muốn kiểm tra ngân sách.\n(B) Cô ấy nghĩ anh Liu không nên mua giấy ở Biz Plus.\n(C) Cô ấy cho rằng anh Liu không nên đặt hàng trong tuần này.\n(D) Cô ấy định hủy đơn hàng của mình."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following letter.","passages":["<p>20 May</p><p>Neil Croft, Director<br>Queensland Libraries<br>13 Hummocky Road<br>Brisbane QLD 4003</p><p>Dear Mr. Croft,</p><p><span class=\"pos\">[1]</span> I have read your inquiry about offering financial management courses at libraries across Queensland. The Society for Financial Management Advisors (SFMA) welcomes the opportunity to partner with the libraries to make basic financial management information more widely available.</p><p>You proposed that SFMA members could lead introductory courses at several library branches. <span class=\"pos\">[2]</span> SFMA members have offered similar courses to recent graduates, people changing careers, and first-time investors in the past.</p><p><span class=\"pos\">[3]</span> If you have a list of library branches that would host the first series of events, I can suggest facilitators who work near those libraries or would be willing to travel to them. Do you have a general profile of the expected attendees? <span class=\"pos\">[4]</span> That information would help us tailor the courses to audience needs and interests.</p><p>I look forward to meeting with you to develop a plan. Please contact me by telephone at 07 5550 1344 to set up a time to discuss the courses.</p><p>Sincerely,</p><p><i>Roberta Otney</i><br>Roberta Otney<br>Chairperson, Society for Financial Management Advisors</p>"],"vi":"Ngày 20 tháng 5\n\nNeil Croft, Giám đốc\nThư viện Queensland\n13 Hummocky Road\nBrisbane QLD 4003\n\nKính gửi ông Croft,\n\n[1] Tôi đã đọc yêu cầu của ông về việc mở các khóa học quản lý tài chính tại các thư viện trên khắp Queensland. Hiệp hội Cố vấn Quản lý Tài chính (SFMA) hoan nghênh cơ hội hợp tác với các thư viện để giúp thông tin quản lý tài chính cơ bản đến được với nhiều người hơn.\n\nÔng đã đề xuất rằng các thành viên SFMA có thể đứng lớp các khóa nhập môn tại một số chi nhánh thư viện. [2] Trước đây, các thành viên SFMA đã từng dạy những khóa tương tự cho sinh viên mới tốt nghiệp, người đang chuyển nghề và nhà đầu tư lần đầu.\n\n[3] Nếu ông có danh sách các chi nhánh thư viện sẽ tổ chức đợt sự kiện đầu tiên, tôi có thể đề xuất những người hướng dẫn làm việc gần các thư viện đó hoặc sẵn sàng đi đến đó. Ông có thông tin khái quát về những người dự kiến tham dự không? [4] Thông tin đó sẽ giúp chúng tôi điều chỉnh khóa học phù hợp với nhu cầu và sở thích của người học.\n\nTôi mong được gặp ông để cùng xây dựng kế hoạch. Vui lòng liên hệ với tôi qua số điện thoại 07 5550 1344 để sắp xếp thời gian trao đổi về các khóa học.\n\nTrân trọng,\nRoberta Otney\nChủ tịch, Hiệp hội Cố vấn Quản lý Tài chính","qs":[{"n":155,"q":"Why did Ms. Otney write the letter?","qvi":"Tại sao cô Otney viết lá thư này?","opts":["To welcome a new library director","To register for an SFMA finance course","To confirm some educational credentials","To reply to a question from Mr. Croft"],"ans":"D","xp":"Câu hỏi mục đích. Mở đầu thư: \"I have read your inquiry about offering financial management courses at libraries\" → cô viết thư để phản hồi yêu cầu/câu hỏi (inquiry) của ông Croft → (D). Các lựa chọn khác không được nhắc đến.\n(A) Để chào đón một giám đốc thư viện mới\n(B) Để đăng ký một khóa học tài chính của SFMA\n(C) Để xác nhận một số bằng cấp học vấn\n(D) Để trả lời câu hỏi của ông Croft"},{"n":156,"q":"What is one thing Ms. Otney requested?","qvi":"Một điều cô Otney yêu cầu là gì?","opts":["A library membership","A list of course instructors","The locations of some libraries","Mr. Croft's telephone number"],"ans":"C","xp":"Câu hỏi chi tiết. \"If you have a list of library branches that would host the first series of events, I can suggest facilitators who work near those libraries\" → cô cần biết những chi nhánh thư viện nào sẽ tổ chức (và ở đâu) để chọn người hướng dẫn ở gần = địa điểm của một số thư viện → (C). (B) sai: chính cô Otney sẽ đề xuất người hướng dẫn. (D) sai: cô đưa số điện thoại của mình, không xin số của ông Croft.\n(A) Thẻ thành viên thư viện\n(B) Danh sách giảng viên khóa học\n(C) Địa điểm của một số thư viện\n(D) Số điện thoại của ông Croft"},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"This is something I would be happy to arrange.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Đây là điều tôi rất sẵn lòng sắp xếp.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu hỏi điền câu. \"This\" phải chỉ một việc vừa được nhắc đến mà cô Otney có thể sắp xếp. Ngay trước [2] là \"You proposed that SFMA members could lead introductory courses at several library branches.\" → \"This is something I would be happy to arrange\" = việc để thành viên SFMA đứng lớp, tôi sẵn lòng sắp xếp. Câu sau [2] tiếp tục củng cố: thành viên SFMA từng dạy các khóa tương tự → (B).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following advertisement.","passages":["<h3>Claro Vision</h3><p>The difference is clear.</p><p>Take advantage of our limited-time offer:<br><b>50% off all eyeglass frames through 30 September</b></p><h4>Other advantages available today and every day:</h4><ul><li>Free eyeglass fittings and adjustments</li><li>Money-back guarantee if you are not completely satisfied</li><li>More than 500 locations in shopping malls throughout Canada</li><li>Low-cost vision checkups by licensed opticians</li></ul><p>To find a store near you, visit www.clarovision.ca/locations, or call 416-555-0122 today!</p>"],"vi":"Claro Vision\nKhác biệt thật rõ ràng.\n\nHãy tận dụng ưu đãi có thời hạn của chúng tôi:\nGiảm 50% tất cả gọng kính đến hết ngày 30 tháng 9\n\nNhững lợi ích khác có ngay hôm nay và mỗi ngày:\n- Miễn phí đo, lắp và chỉnh kính\n- Hoàn tiền nếu bạn không hoàn toàn hài lòng\n- Hơn 500 cửa hàng trong các trung tâm mua sắm trên khắp Canada\n- Khám mắt chi phí thấp do chuyên viên đo kính có giấy phép thực hiện\n\nĐể tìm cửa hàng gần bạn, hãy truy cập www.clarovision.ca/locations hoặc gọi 416-555-0122 ngay hôm nay!","qs":[{"n":158,"q":"Why most likely was the advertisement created?","qvi":"Nhiều khả năng quảng cáo này được tạo ra để làm gì?","opts":["To draw attention to an underused professional service","To publicize the benefits of a warranty policy","To announce the opening of new store locations","To promote a temporary price discount"],"ans":"D","xp":"Câu hỏi mục đích. Nội dung nổi bật nhất: \"Take advantage of our limited-time offer: 50% off all eyeglass frames through 30 September\" → quảng bá đợt giảm giá có thời hạn = temporary price discount → (D). Chính sách hoàn tiền (B) hay các cửa hàng (C) chỉ là \"other advantages\" phụ; không có cửa hàng mới.\n(A) Để thu hút sự chú ý đến một dịch vụ chuyên môn ít được sử dụng\n(B) Để quảng bá lợi ích của chính sách bảo hành\n(C) Để thông báo khai trương cửa hàng mới\n(D) Để quảng bá đợt giảm giá tạm thời"},{"n":159,"q":"What is stated about Claro Vision stores?","qvi":"Điều gì được nêu về các cửa hàng Claro Vision?","opts":["They are larger than competitors' stores.","They accept all major credit cards.","They are located next to shopping malls.","They provide eyeglass fittings at no cost."],"ans":"D","xp":"Câu hỏi chi tiết. \"Free eyeglass fittings and adjustments\" → đo lắp kính miễn phí = at no cost → (D). (C) sai vì cửa hàng nằm \"in shopping malls\" (bên trong trung tâm mua sắm), không phải \"next to\" (bên cạnh). (A), (B) không được nhắc đến.\n(A) Cửa hàng lớn hơn cửa hàng của đối thủ.\n(B) Cửa hàng chấp nhận mọi loại thẻ tín dụng phổ biến.\n(C) Cửa hàng nằm cạnh các trung tâm mua sắm.\n(D) Cửa hàng đo lắp kính miễn phí."},{"n":160,"q":"What is stated about vision checkups?","qvi":"Điều gì được nêu về dịch vụ khám mắt?","opts":["They are completed by a partner company.","They are performed by a certified professional.","They should be done every ten months.","They are offered on a limited number of days."],"ans":"B","xp":"Câu hỏi chi tiết. \"Low-cost vision checkups by licensed opticians\" → khám mắt do chuyên viên có giấy phép (licensed = certified) thực hiện → (B). (D) sai vì đây là lợi ích \"available today and every day\" (có mỗi ngày).\n(A) Việc khám do một công ty đối tác thực hiện.\n(B) Việc khám do một chuyên gia có chứng nhận thực hiện.\n(C) Nên khám mắt mỗi mười tháng.\n(D) Dịch vụ chỉ có vào một số ngày nhất định."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following letter.","passages":["<p>Rossery Building Corporation<br>2710 South Exmouth Drive<br>Singapore 188509</p><p>1 April</p><p>Elizabeth Balakrishnan<br>Bala Home Furnishings<br>416 Holliton Drive C2<br>Singapore 793801</p><p>Dear Ms. Balakrishnan,</p><p>This is a reminder that the one-year lease for your space will end on 30 April. Please contact my office at 1555 0124 to make an appointment to renew your lease. There will be a small increase in rent and fees because of rising operating costs.</p><p>Updated charges upon lease renewal:</p><table><tr><td>Monthly rental</td><td>S$1,800.00</td></tr><tr><td>Parking space fee</td><td>S$50.00</td></tr><tr><td>Cleaning service</td><td>S$10.00</td></tr><tr><td>Security fee</td><td>S$35.00</td></tr><tr><td><b>Total monthly charge</b></td><td><b>S$1,895.00</b></td></tr></table><p>If you are not renewing your lease, please notify our office by 15 April. Plan to vacate the property by 5 P.M. on 30 April. There will be an inspection of the property, and there may be charges for repairs or damages beyond normal usage.</p><p>Kind regards,</p><p><i>Alexis Tan</i><br>Alexis Tan</p>"],"vi":"Tập đoàn Xây dựng Rossery\n2710 South Exmouth Drive\nSingapore 188509\n\nNgày 1 tháng 4\n\nElizabeth Balakrishnan\nBala Home Furnishings\n416 Holliton Drive C2\nSingapore 793801\n\nKính gửi cô Balakrishnan,\n\nĐây là thư nhắc rằng hợp đồng thuê mặt bằng một năm của cô sẽ hết hạn vào ngày 30 tháng 4. Vui lòng liên hệ văn phòng của tôi theo số 1555 0124 để đặt lịch hẹn gia hạn hợp đồng thuê. Tiền thuê và các khoản phí sẽ tăng nhẹ do chi phí vận hành tăng.\n\nCác khoản phí mới khi gia hạn hợp đồng:\nTiền thuê hằng tháng: 1.800,00 đô la Singapore\nPhí chỗ đậu xe: 50,00 đô la Singapore\nDịch vụ vệ sinh: 10,00 đô la Singapore\nPhí an ninh: 35,00 đô la Singapore\nTổng phí hằng tháng: 1.895,00 đô la Singapore\n\nNếu cô không gia hạn hợp đồng, vui lòng báo cho văn phòng chúng tôi trước ngày 15 tháng 4. Hãy dự kiến dọn ra khỏi mặt bằng trước 5 giờ chiều ngày 30 tháng 4. Sẽ có một đợt kiểm tra mặt bằng, và có thể phát sinh phí sửa chữa hoặc hư hỏng vượt quá mức sử dụng thông thường.\n\nTrân trọng,\nAlexis Tan","qs":[{"n":161,"q":"What is the purpose of the letter?","qvi":"Mục đích của lá thư là gì?","opts":["To explain the fees for equipment installation","To offer a discount on a service","To provide information about a lease agreement","To request a change to a property amenity"],"ans":"C","xp":"Câu hỏi mục đích. \"This is a reminder that the one-year lease for your space will end on 30 April. Please contact my office... to renew your lease.\" Sau đó thư liệt kê các khoản phí mới khi gia hạn và hướng dẫn nếu không gia hạn → thư cung cấp thông tin về hợp đồng thuê (lease agreement) → (C). Thư nói phí tăng chứ không giảm giá (B); không có lắp đặt thiết bị (A).\n(A) Để giải thích các khoản phí lắp đặt thiết bị\n(B) Để giảm giá một dịch vụ\n(C) Để cung cấp thông tin về hợp đồng thuê\n(D) Để yêu cầu thay đổi một tiện ích của tòa nhà"},{"n":162,"q":"According to the letter, what must Ms. Balakrishnan pay for each month?","qvi":"Theo lá thư, cô Balakrishnan phải trả tiền cho thứ gì hằng tháng?","opts":["Furniture rental","Office supplies","An inspection fee","A parking space"],"ans":"D","xp":"Câu hỏi chi tiết. Bảng phí hằng tháng có dòng \"Parking space fee S$50.00\" → cô phải trả tiền chỗ đậu xe mỗi tháng → (D). (C) sai: việc kiểm tra (inspection) chỉ diễn ra khi dọn đi, và chỉ có thể tính phí sửa chữa/hư hỏng. (A) dễ nhầm vì công ty cô tên \"Home Furnishings\" (đồ nội thất), nhưng không có phí thuê đồ nội thất.\n(A) Tiền thuê đồ nội thất\n(B) Văn phòng phẩm\n(C) Phí kiểm tra\n(D) Chỗ đậu xe"},{"n":163,"q":"Who most likely is Ms. Tan?","qvi":"Nhiều khả năng cô Tan là ai?","opts":["A repair person","A property manager","A cleaning person","A security company employee"],"ans":"B","xp":"Câu hỏi suy luận. Cô Tan viết thư từ Rossery Building Corporation, nhắc hợp đồng thuê sắp hết hạn, mời liên hệ \"my office\" để gia hạn, thông báo giá thuê mới và việc kiểm tra mặt bằng → đây là công việc của người quản lý bất động sản/tòa nhà → (B). Sửa chữa, vệ sinh, an ninh chỉ là các khoản phí được liệt kê.\n(A) Thợ sửa chữa\n(B) Người quản lý bất động sản\n(C) Nhân viên vệ sinh\n(D) Nhân viên công ty an ninh"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> lkhoury@britelyauto.co.uk</p><p><b>From:</b> khagel@qualiview.co.uk</p><p><b>Date:</b> 14 April</p><p><b>Subject:</b> Your proposed changes</p></div><p>Dear Ms. Khoury,</p><p>Thank you for forwarding your proposed revisions to the contract for Qualiview Ltd. to be your wholesale supplier of automotive window glass.</p><p>First, we will gladly agree to an extension of the contract term from one to three years. Secondly, I am not sure what more we can do to address your concerns about packaging materials. We use custom-built crates and innovative packaging to reduce the risk of breakage during shipping. While we will replace any goods that may be damaged in transit, we do not agree to pay an additional penalty fee in the event of such damage.</p><p>I would like to discuss this further with you next week; however, I will be out of the office through Tuesday afternoon. Would you be available to meet before 11:00 A.M. on either Wednesday or Thursday? Friday is also possible. Please let me know a convenient date and time for you.</p><p>Best regards,</p><p>Karl Hagel<br>Qualiview Ltd.</p>"],"vi":"Người nhận: lkhoury@britelyauto.co.uk\nNgười gửi: khagel@qualiview.co.uk\nNgày: 14 tháng 4\nTiêu đề: Những thay đổi chị đề xuất\n\nKính gửi chị Khoury,\n\nCảm ơn chị đã gửi những điều chỉnh đề xuất cho hợp đồng để Qualiview Ltd. trở thành nhà cung cấp sỉ kính cửa xe ô tô cho công ty chị.\n\nThứ nhất, chúng tôi sẵn lòng đồng ý gia hạn thời hạn hợp đồng từ một năm lên ba năm. Thứ hai, tôi không chắc chúng tôi có thể làm gì thêm để giải quyết những lo ngại của chị về vật liệu đóng gói. Chúng tôi sử dụng thùng gỗ đóng theo yêu cầu và cách đóng gói cải tiến để giảm nguy cơ vỡ trong quá trình vận chuyển. Mặc dù chúng tôi sẽ thay thế bất kỳ hàng hóa nào có thể bị hư hỏng trong lúc vận chuyển, chúng tôi không đồng ý trả thêm phí phạt trong trường hợp xảy ra hư hỏng như vậy.\n\nTôi muốn trao đổi thêm với chị vào tuần tới; tuy nhiên, tôi sẽ vắng mặt ở văn phòng đến hết chiều thứ Ba. Chị có thể gặp trước 11 giờ sáng vào thứ Tư hoặc thứ Năm không? Thứ Sáu cũng được. Vui lòng cho tôi biết ngày giờ thuận tiện cho chị.\n\nTrân trọng,\nKarl Hagel\nQualiview Ltd.","qs":[{"n":164,"q":"Why did Mr. Hagel write the e-mail?","qvi":"Tại sao anh Hagel viết e-mail này?","opts":["To report damage to an item","To finalize a purchase","To request a product sample","To negotiate a contract"],"ans":"D","xp":"Câu hỏi mục đích. Anh Hagel phản hồi \"your proposed revisions to the contract\": đồng ý một điểm (gia hạn hợp đồng lên 3 năm), từ chối một điểm (phí phạt khi hàng hư hỏng) và hẹn gặp để \"discuss this further\" → đang thương lượng hợp đồng → (D). Không có hàng bị hư (A), hợp đồng chưa chốt (B).\n(A) Để báo cáo hư hỏng của một món hàng\n(B) Để hoàn tất một giao dịch mua\n(C) Để yêu cầu hàng mẫu\n(D) Để thương lượng một hợp đồng"},{"n":165,"q":"What is indicated about Qualiview Ltd.?","qvi":"Điều gì được nêu về Qualiview Ltd.?","opts":["It sells its products online.","It makes windows for cars.","It has paid penalty fees in the past.","It recently redesigned its shipping crates."],"ans":"B","xp":"Câu hỏi chi tiết. \"Qualiview Ltd. to be your wholesale supplier of automotive window glass\" → Qualiview cung cấp kính cửa xe ô tô (automotive window glass = windows for cars) → (B). (C) sai: họ từ chối trả phí phạt. (D) sai: họ dùng \"custom-built crates\" nhưng không nói mới thiết kế lại.\n(A) Công ty bán sản phẩm trực tuyến.\n(B) Công ty sản xuất kính cửa cho ô tô.\n(C) Công ty từng trả phí phạt trước đây.\n(D) Công ty vừa thiết kế lại thùng vận chuyển."},{"n":166,"q":"The word \"address\" in paragraph 2, line 2, is closest in meaning to","qvi":"Từ \"address\" ở đoạn 2, dòng 2 gần nghĩa nhất với","opts":["respond to","think about","greet","deliver"],"ans":"A","xp":"Câu hỏi đồng nghĩa. \"I am not sure what more we can do to address your concerns about packaging materials\" → \"address concerns\" = giải quyết, xử lý, đáp lại những lo ngại → gần nghĩa nhất với \"respond to\" (đáp ứng, phản hồi) → (A). \"address\" còn có nghĩa \"phát biểu/xưng hô với ai\" (gần greet) hoặc \"ghi địa chỉ để gửi\" (gần deliver), nhưng không hợp ngữ cảnh.\n(A) đáp lại, giải quyết\n(B) suy nghĩ về\n(C) chào hỏi\n(D) giao, phân phát"},{"n":167,"q":"When is Mr. Hagel available next week?","qvi":"Tuần tới anh Hagel rảnh khi nào?","opts":["On Monday morning","On Tuesday afternoon","On Wednesday morning","On Thursday afternoon"],"ans":"C","xp":"Câu hỏi chi tiết. \"I will be out of the office through Tuesday afternoon. Would you be available to meet before 11:00 A.M. on either Wednesday or Thursday? Friday is also possible.\" → anh vắng mặt đến hết chiều thứ Ba (loại A, B), có thể gặp trước 11 giờ sáng thứ Tư/thứ Năm → sáng thứ Tư → (C). (D) sai vì thứ Năm chỉ rảnh trước 11 giờ sáng, không phải buổi chiều.\n(A) Sáng thứ Hai\n(B) Chiều thứ Ba\n(C) Sáng thứ Tư\n(D) Chiều thứ Năm"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following article.","passages":["<h3>Shipping Disruptions</h3><p>SINGAPORE (6 June)—Recently, the demand for international freight space has been outpacing the availability of shipping containers. This container shortage has led to higher costs for goods being shipped out of Asian ports. A drop in the production of rolls of steel, the raw material that containers are made from, has further complicated the situation. <span class=\"pos\">[1]</span></p><p>Some exporters have considered the more expensive option of air freight, but companies are still faced with a difficult choice. <span class=\"pos\">[2]</span> They must either ask their customers to accept shipment delays, or substantially raise customer prices to cover the costs of expedited shipping. Either way, suppliers risk triggering customer dissatisfaction.</p><p>\"We are working with business partners, investors, and government officials to discuss solutions to this problem,\" said Henry Lam, a spokesperson for the household goods producer QET Group. <span class=\"pos\">[3]</span> \"It's going to take total cooperation of all stakeholders to find a solution.\"</p><p>Not all companies are suffering, though. For example, Fezker, the producer of athletic apparel and footwear, has implemented strategies to better overcome this situation. Fezker has successfully refocused its efforts away from exports to western countries and toward expanding its domestic and regional markets. <span class=\"pos\">[4]</span></p><p>\"We moved quickly, so the shipping container shortage has not caused a significant impact on our profits,\" said Fezker CEO Nuwa Lee.</p>"],"vi":"Gián đoạn vận chuyển\n\nSINGAPORE (6 tháng 6) — Gần đây, nhu cầu về chỗ chở hàng quốc tế đã vượt quá số lượng container vận chuyển hiện có. Tình trạng thiếu container này khiến chi phí hàng hóa xuất đi từ các cảng châu Á tăng cao. Sản lượng thép cuộn — nguyên liệu thô để làm container — giảm sút càng khiến tình hình thêm phức tạp. [1]\n\nMột số nhà xuất khẩu đã cân nhắc phương án vận chuyển hàng không đắt đỏ hơn, nhưng các công ty vẫn phải đối mặt với một lựa chọn khó khăn. [2] Họ phải hoặc đề nghị khách hàng chấp nhận việc giao hàng chậm trễ, hoặc tăng giá bán đáng kể để bù chi phí vận chuyển nhanh. Dù theo cách nào, các nhà cung cấp cũng có nguy cơ khiến khách hàng không hài lòng.\n\n\"Chúng tôi đang làm việc với các đối tác kinh doanh, nhà đầu tư và quan chức chính phủ để bàn giải pháp cho vấn đề này,\" ông Henry Lam, người phát ngôn của nhà sản xuất đồ gia dụng QET Group, cho biết. [3] \"Cần có sự hợp tác hoàn toàn của tất cả các bên liên quan để tìm ra giải pháp.\"\n\nTuy nhiên, không phải công ty nào cũng gặp khó khăn. Ví dụ, Fezker, nhà sản xuất quần áo và giày dép thể thao, đã triển khai các chiến lược để vượt qua tình hình này tốt hơn. Fezker đã chuyển hướng thành công, không còn tập trung xuất khẩu sang các nước phương Tây mà chuyển sang mở rộng thị trường trong nước và trong khu vực. [4]\n\n\"Chúng tôi đã hành động nhanh chóng, nên tình trạng thiếu container không gây ảnh hưởng đáng kể đến lợi nhuận của chúng tôi,\" Giám đốc điều hành Fezker, bà Nuwa Lee, cho biết.","qs":[{"n":168,"q":"What is mentioned about shipping containers?","qvi":"Điều gì được đề cập về container vận chuyển?","opts":["They come in different sizes.","They are in short supply.","They are made from a variety of materials.","They can be used for long-term storage."],"ans":"B","xp":"Câu hỏi chi tiết. \"the demand for international freight space has been outpacing the availability of shipping containers. This container shortage...\" → container đang thiếu (shortage = short supply) → (B). (C) sai: container được làm từ \"rolls of steel\" (một loại nguyên liệu), không phải nhiều loại vật liệu. (A), (D) không được nhắc đến.\n(A) Container có nhiều kích cỡ khác nhau.\n(B) Container đang khan hiếm.\n(C) Container được làm từ nhiều loại vật liệu.\n(D) Container có thể dùng để lưu trữ lâu dài."},{"n":169,"q":"What does Mr. Lam say is needed to resolve the situation?","qvi":"Theo ông Lam, cần gì để giải quyết tình hình?","opts":["A sharp increase in the number of customers","A relaxation of government restrictions","The development of new technologies","Communication between affected groups"],"ans":"D","xp":"Câu hỏi chi tiết. Ông Lam nói: \"We are working with business partners, investors, and government officials to discuss solutions\" và \"It's going to take total cooperation of all stakeholders to find a solution.\" → cần sự trao đổi, hợp tác giữa các bên liên quan (stakeholders = affected groups) → (D). Ông có nhắc \"government officials\" nhưng không nói về nới lỏng quy định (B).\n(A) Số lượng khách hàng tăng mạnh\n(B) Chính phủ nới lỏng các hạn chế\n(C) Phát triển công nghệ mới\n(D) Sự trao đổi giữa các nhóm bị ảnh hưởng"},{"n":170,"q":"What type of clothing does Fezker produce?","qvi":"Fezker sản xuất loại quần áo nào?","opts":["Rain jackets","Sportswear","Business suits","Work uniforms"],"ans":"B","xp":"Câu hỏi chi tiết. \"Fezker, the producer of athletic apparel and footwear\" → athletic apparel (quần áo thể thao) = sportswear → (B).\n(A) Áo khoác đi mưa\n(B) Đồ thể thao\n(C) Com-lê công sở\n(D) Đồng phục lao động"},{"n":171,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"These markets are supplied using more readily available truck and train transportation.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Các thị trường này được cung ứng bằng phương tiện xe tải và tàu hỏa sẵn có hơn.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"Câu hỏi điền câu. \"These markets\" phải chỉ các thị trường vừa được nhắc ngay trước đó. Câu trước [4]: \"Fezker has successfully refocused its efforts... toward expanding its domestic and regional markets.\" → \"These markets\" = thị trường trong nước và khu vực, có thể chở hàng bằng xe tải và tàu hỏa thay vì container đường biển. Câu sau [4] (\"We moved quickly, so the shipping container shortage has not caused a significant impact...\") cũng khớp → (D).\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Gary Wendel (7:40 A.M.)</b></p><p>Good morning, team. Can you share the current status of your projects, please?</p></div><div class=\"msg\"><p><b>Jing Yu (7:42 A.M.)</b></p><p>I met with the client last week to confirm the start date for Phase B of the Palisade project.</p></div><div class=\"msg\"><p><b>Robbie Zuniga (7:43 A.M.)</b></p><p>I am headed to the job site now for the Riverview project. The rain last week delayed pouring the concrete for the sidewalks. I will check the conditions this morning to see if the situation has improved.</p></div><div class=\"msg\"><p><b>Gary Wendel (7:44 A.M.)</b></p><p>When will Phase B of the Palisade project begin?</p></div><div class=\"msg\"><p><b>Jing Yu (7:46 A.M.)</b></p><p>We will break ground in March and plan to have the building completed by November.</p></div><div class=\"msg\"><p><b>Gary Wendel (7:47 A.M.)</b></p><p>That's good news about the March start date. I am sure the client is happy about that.</p></div><div class=\"msg\"><p><b>Gary Wendel (7:50 A.M.)</b></p><p>Robbie, let me know what you find out about the site conditions. Perhaps Nathan Burry can help at the site. He's our most knowledgeable concrete finisher.</p></div><div class=\"msg\"><p><b>Robbie Zuniga (7:55 A.M.)</b></p><p>Actually, I'm meeting Nathan at the site this morning, so I'll get his opinion on when we can pour the concrete. The rest of the project is on hold until we can do this.</p></div><div class=\"msg\"><p><b>Gary Wendel (7:57 A.M.)</b></p><p>Keep me posted. I don't want to rush it if it's still too wet. At the same time, the Riverview project is already behind schedule because of equipment problems and late delivery of building materials.</p></div><div class=\"msg\"><p><b>Robbie Zuniga (7:58 A.M.)</b></p><p>Will do.</p></div>"],"vi":"Gary Wendel (7:40 sáng): Chào buổi sáng cả nhóm. Mọi người có thể cho biết tình trạng hiện tại của các dự án không?\n\nJing Yu (7:42 sáng): Tuần trước tôi đã gặp khách hàng để xác nhận ngày khởi công Giai đoạn B của dự án Palisade.\n\nRobbie Zuniga (7:43 sáng): Tôi đang đến công trường dự án Riverview. Trận mưa tuần trước làm chậm việc đổ bê tông vỉa hè. Sáng nay tôi sẽ kiểm tra điều kiện để xem tình hình đã khá hơn chưa.\n\nGary Wendel (7:44 sáng): Khi nào Giai đoạn B của dự án Palisade bắt đầu?\n\nJing Yu (7:46 sáng): Chúng ta sẽ động thổ vào tháng 3 và dự kiến hoàn thành tòa nhà trước tháng 11.\n\nGary Wendel (7:47 sáng): Tin tốt về ngày khởi công tháng 3. Tôi chắc là khách hàng rất hài lòng về điều đó.\n\nGary Wendel (7:50 sáng): Robbie, cho tôi biết anh tìm hiểu được gì về điều kiện công trường nhé. Có lẽ Nathan Burry có thể giúp ở công trường. Anh ấy là thợ hoàn thiện bê tông giỏi chuyên môn nhất của chúng ta.\n\nRobbie Zuniga (7:55 sáng): Thật ra sáng nay tôi sẽ gặp Nathan ở công trường, nên tôi sẽ hỏi ý kiến anh ấy về thời điểm có thể đổ bê tông. Phần còn lại của dự án đang tạm dừng cho đến khi làm xong việc này.\n\nGary Wendel (7:57 sáng): Cập nhật cho tôi nhé. Tôi không muốn làm vội nếu mặt bằng vẫn còn quá ướt. Mặt khác, dự án Riverview đã bị chậm tiến độ vì sự cố thiết bị và vật liệu xây dựng giao trễ.\n\nRobbie Zuniga (7:58 sáng): Tôi sẽ làm vậy.","qs":[{"n":172,"q":"In what industry do the writers most likely work?","qvi":"Những người viết nhiều khả năng làm việc trong ngành nào?","opts":["Construction","Energy","Manufacturing","Travel"],"ans":"A","xp":"Câu hỏi suy luận. Cuộc trò chuyện nhắc đến \"job site\", \"pouring the concrete for the sidewalks\", \"break ground\", \"have the building completed\", \"concrete finisher\", \"building materials\" → họ làm trong ngành xây dựng → (A).\n(A) Xây dựng\n(B) Năng lượng\n(C) Sản xuất\n(D) Du lịch"},{"n":173,"q":"Why did Mr. Wendel begin the discussion?","qvi":"Tại sao anh Wendel bắt đầu cuộc thảo luận?","opts":["To plan a client meeting","To discuss a weather forecast","To obtain an update on some work","To change the start date of an event"],"ans":"C","xp":"Câu hỏi mục đích. Tin nhắn đầu tiên: \"Can you share the current status of your projects, please?\" → anh muốn nắm tình hình hiện tại (update) của các dự án → (C). (A) sai vì cuộc gặp khách hàng đã diễn ra tuần trước; (B) mưa chỉ được nhắc là nguyên nhân chậm trễ; (D) không ai đổi ngày khởi công.\n(A) Để lên kế hoạch gặp khách hàng\n(B) Để bàn về dự báo thời tiết\n(C) Để nắm thông tin cập nhật về một số công việc\n(D) Để thay đổi ngày bắt đầu của một sự kiện"},{"n":174,"q":"What is indicated about the Riverview project?","qvi":"Điều gì được nêu về dự án Riverview?","opts":["It has had several delays.","It is being managed by Ms. Yu.","It will be completed in November.","Its clients are happy with the progress."],"ans":"A","xp":"Câu hỏi chi tiết. \"The rain last week delayed pouring the concrete\" và \"the Riverview project is already behind schedule because of equipment problems and late delivery of building materials\" → dự án bị chậm nhiều lần (mưa, thiết bị, vật liệu) → (A). (B) sai: Robbie Zuniga phụ trách Riverview, cô Yu phụ trách Palisade. (C), (D) nói về dự án Palisade (hoàn thành tháng 11, khách hàng hài lòng với ngày khởi công).\n(A) Dự án đã bị chậm trễ nhiều lần.\n(B) Dự án do cô Yu quản lý.\n(C) Dự án sẽ hoàn thành vào tháng 11.\n(D) Khách hàng hài lòng với tiến độ."},{"n":175,"q":"At 7:58 A.M., what does Mr. Zuniga most likely mean when he writes, \"Will do\"?","qvi":"Lúc 7:58 sáng, khi viết \"Will do\" (Tôi sẽ làm vậy), nhiều khả năng anh Zuniga có ý gì?","opts":["He will revise a delivery schedule.","He will purchase more equipment.","He will hire workers to help at a site.","He will share the outcome of a meeting."],"ans":"D","xp":"Câu hỏi hàm ý. Robbie nói sẽ gặp Nathan ở công trường sáng nay để hỏi ý kiến khi nào đổ bê tông; anh Wendel đáp \"Keep me posted\" (cập nhật cho tôi nhé). \"Will do\" = anh đồng ý sẽ báo lại kết quả buổi gặp với Nathan → (D). Các lựa chọn khác không được yêu cầu.\n(A) Anh ấy sẽ điều chỉnh lịch giao hàng.\n(B) Anh ấy sẽ mua thêm thiết bị.\n(C) Anh ấy sẽ thuê thêm công nhân hỗ trợ ở công trường.\n(D) Anh ấy sẽ chia sẻ kết quả của một buổi gặp."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and survey form.","passages":["<div class=\"hdr\"><p><b>From:</b> Madalyn Kerluke &lt;mkerluke@karabel.ca&gt;</p><p><b>To:</b> Omar Niklaus &lt;oniklaus@karabel.ca&gt;, Jay Toncic &lt;jtoncic@karabel.ca&gt;</p><p><b>Date:</b> Friday, 3 February 2:16 P.M.</p><p><b>Subject:</b> Taste-test results</p><p><b>Attachment:</b> Fatior Labs survey results</p></div><p>Hi, Team.</p><p>I just received the 24–26 January survey results from Fatior Labs for our new ice-cream taste test. As you can see from the attached document, the results are very disappointing. We sent the four flavours that we considered to be the best, but none of them received high enough ratings to advance to the next stage of development. Most of the reviews were consistent among the 92 taste-test participants in our target market of consumers ages 25 through 40. It's not a big problem if a product gets low scores in colour in the testing phase, since we can easily adjust that in the laboratory. But we should never be sending out samples that are getting scores lower than 3 in the taste category.</p><p>I would like to meet at 9 A.M. on Monday (6 February) to figure out how to proceed. There is one flavour we may be able to work with if we make a few adjustments, as suggested by most of our taste testers. We will also need to get some new flavours to Fatior Labs no later than 1 March if we are going to get a new ice cream on the Preston Grocers freezer shelves by the beginning of June.</p><p>Madalyn Kerluke</p>","<h3>Fatior Labs Consumer Taste-Testing Survey</h3><p><b>Date:</b> 24 January</p><p><b>Company:</b> Karabel Industries</p><p><b>Participant number:</b> 54</p><p>Directions: You will be given a 45 g sample of 4 different ice creams. Please rate the taste, texture, sweetness, and colour of each ice cream on a scale of 1 (very unpleasant) to 5 (very pleasant). Please write any additional comments below.</p><table><tr><th>Flavour</th><th>Taste</th><th>Texture</th><th>Sweetness</th><th>Colour</th></tr><tr><td>Lemon</td><td>2</td><td>3</td><td>2</td><td>4</td></tr><tr><td>Mango</td><td>3</td><td>3</td><td>2</td><td>1</td></tr><tr><td>Salted Caramel</td><td>2</td><td>1</td><td>1</td><td>5</td></tr><tr><td>Peanut Brittle</td><td>3</td><td>4</td><td>2</td><td>2</td></tr></table><p><b>Comments:</b> The fruit-flavoured ice creams were surprisingly sour. I did not care for them at all. I think the Peanut Brittle has the most potential, but it's missing something. I bet that adding chocolate swirls or brownie bits would make it a winner.</p>"],"vi":"Từ: Madalyn Kerluke <mkerluke@karabel.ca>\nĐến: Omar Niklaus <oniklaus@karabel.ca>, Jay Toncic <jtoncic@karabel.ca>\nNgày: Thứ Sáu, 3 tháng 2, 2:16 chiều\nTiêu đề: Kết quả thử vị\nTệp đính kèm: Kết quả khảo sát của Fatior Labs\n\nChào cả nhóm,\n\nTôi vừa nhận được kết quả khảo sát ngày 24–26 tháng 1 từ Fatior Labs cho đợt thử vị kem mới của chúng ta. Như các bạn thấy trong tài liệu đính kèm, kết quả rất đáng thất vọng. Chúng ta đã gửi bốn hương vị mà chúng ta cho là ngon nhất, nhưng không vị nào được đánh giá đủ cao để chuyển sang giai đoạn phát triển tiếp theo. Phần lớn đánh giá khá thống nhất giữa 92 người tham gia thử vị thuộc thị trường mục tiêu của chúng ta là người tiêu dùng từ 25 đến 40 tuổi. Việc một sản phẩm bị điểm thấp về màu sắc trong giai đoạn thử nghiệm không phải là vấn đề lớn, vì chúng ta có thể dễ dàng điều chỉnh điều đó trong phòng thí nghiệm. Nhưng chúng ta tuyệt đối không nên gửi đi những mẫu bị điểm dưới 3 ở hạng mục hương vị.\n\nTôi muốn họp lúc 9 giờ sáng thứ Hai (6 tháng 2) để tìm cách xử lý tiếp. Có một hương vị mà chúng ta có thể tiếp tục phát triển nếu điều chỉnh một chút, như phần lớn người thử vị đã gợi ý. Chúng ta cũng sẽ cần gửi một số hương vị mới đến Fatior Labs chậm nhất là ngày 1 tháng 3 nếu muốn đưa một loại kem mới lên tủ đông của Preston Grocers vào đầu tháng 6.\n\nMadalyn Kerluke\n\n---\n\nPHIẾU KHẢO SÁT THỬ VỊ NGƯỜI TIÊU DÙNG CỦA FATIOR LABS\nNgày: 24 tháng 1\nCông ty: Karabel Industries\nMã số người tham gia: 54\n\nHướng dẫn: Bạn sẽ được nhận một mẫu 45 g của 4 loại kem khác nhau. Vui lòng chấm điểm hương vị, kết cấu, độ ngọt và màu sắc của từng loại kem theo thang điểm từ 1 (rất khó chịu) đến 5 (rất dễ chịu). Vui lòng ghi thêm nhận xét bên dưới.\n\nHương vị — Vị / Kết cấu / Độ ngọt / Màu sắc\nChanh — 2 / 3 / 2 / 4\nXoài — 3 / 3 / 2 / 1\nCaramel muối — 2 / 1 / 1 / 5\nKẹo đậu phộng giòn — 3 / 4 / 2 / 2\n\nNhận xét: Các loại kem vị trái cây chua một cách bất ngờ. Tôi hoàn toàn không thích chúng. Tôi nghĩ vị Kẹo đậu phộng giòn có nhiều tiềm năng nhất, nhưng còn thiếu một chút gì đó. Tôi cá là thêm vân sô-cô-la hoặc miếng bánh brownie sẽ khiến nó trở thành sản phẩm thành công.","qs":[{"n":176,"q":"What does the e-mail indicate about Karabel Industries ice cream?","qvi":"E-mail cho biết điều gì về kem của Karabel Industries?","opts":["It is currently sold in four flavors.","Its coloring can be changed easily.","Its popularity has declined recently.","It is sold in Karabel Industries stores."],"ans":"B","xp":"Câu hỏi chi tiết. E-mail viết: \"It's not a big problem if a product gets low scores in colour in the testing phase, since we can easily adjust that in the laboratory.\" → màu sắc có thể dễ dàng điều chỉnh trong phòng thí nghiệm = \"Its coloring can be changed easily\".\n(A) sai: bốn vị là mẫu gửi đi thử, chưa được bán. (C), (D) không được nhắc đến; kem dự định bán ở Preston Grocers chứ không phải cửa hàng của Karabel.\n(A) Hiện đang được bán với bốn hương vị.\n(B) Màu sắc của nó có thể thay đổi dễ dàng.\n(C) Mức độ được ưa chuộng của nó gần đây giảm sút.\n(D) Nó được bán tại các cửa hàng của Karabel Industries."},{"n":177,"q":"What does Ms. Kerluke state that she wants to do?","qvi":"Cô Kerluke nói rằng cô muốn làm gì?","opts":["Visit a laboratory","Hold a team meeting","Contact a grocery store","Write new survey questions"],"ans":"B","xp":"Câu hỏi chi tiết. E-mail gửi cho cả nhóm (\"Hi, Team\") và viết: \"I would like to meet at 9 A.M. on Monday (6 February) to figure out how to proceed.\" → muốn họp với nhóm = \"Hold a team meeting\".\n(A) Đến thăm một phòng thí nghiệm\n(B) Tổ chức một cuộc họp nhóm\n(C) Liên hệ một cửa hàng tạp hóa\n(D) Viết câu hỏi khảo sát mới"},{"n":178,"q":"What is suggested about Fatior Labs?","qvi":"Điều gì được ngụ ý về Fatior Labs?","opts":["It has 92 employees.","It manufactures food colorings.","It will perform another taste test for Karabel Industries.","It supplies ice cream to Preston Grocers."],"ans":"C","xp":"Câu hỏi suy luận. E-mail viết: \"We will also need to get some new flavours to Fatior Labs no later than 1 March\" → Karabel sẽ gửi hương vị mới cho Fatior Labs để thử vị tiếp → Fatior Labs sẽ thực hiện một đợt thử vị khác cho Karabel.\n(A) sai: 92 là số người tham gia thử vị, không phải nhân viên. (B), (D) không có thông tin; Preston Grocers là nơi Karabel muốn bán kem.\n(A) Công ty có 92 nhân viên.\n(B) Công ty sản xuất phẩm màu thực phẩm.\n(C) Công ty sẽ thực hiện một đợt thử vị khác cho Karabel Industries.\n(D) Công ty cung cấp kem cho Preston Grocers."},{"n":179,"q":"Based on the survey form, what flavor will Karabel Industries most likely make adjustments to?","qvi":"Dựa vào phiếu khảo sát, Karabel Industries nhiều khả năng sẽ điều chỉnh hương vị nào?","opts":["Lemon","Mango","Salted Caramel","Peanut Brittle"],"ans":"D","xp":"Câu hỏi liên kết 2 đoạn. E-mail: \"There is one flavour we may be able to work with if we make a few adjustments, as suggested by most of our taste testers.\" Phiếu khảo sát: \"I think the Peanut Brittle has the most potential, but it's missing something. I bet that adding chocolate swirls or brownie bits would make it a winner.\" → vị được gợi ý điều chỉnh là Peanut Brittle. Ngoài ra Peanut Brittle có điểm vị 3 (không dưới 3) và kết cấu cao nhất (4).\n(A) Chanh\n(B) Xoài\n(C) Caramel muối\n(D) Kẹo đậu phộng giòn"},{"n":180,"q":"What can be concluded about participant number 54?","qvi":"Có thể kết luận gì về người tham gia số 54?","opts":["The participant purchased several containers of ice cream.","The participant is between the ages of 25 and 40.","The participant regularly takes consumer surveys.","The participant prefers fruit-flavored ice cream."],"ans":"B","xp":"Câu hỏi liên kết 2 đoạn. E-mail: \"the 92 taste-test participants in our target market of consumers ages 25 through 40\". Phiếu khảo sát của người số 54 là một phần của đợt thử vị này (ngày 24 tháng 1, công ty Karabel Industries) → người này ở độ tuổi 25–40.\n(D) sai: người này viết \"The fruit-flavoured ice creams were surprisingly sour. I did not care for them at all.\" → không thích vị trái cây. (A), (C) không có thông tin.\n(A) Người tham gia đã mua vài hộp kem.\n(B) Người tham gia ở độ tuổi từ 25 đến 40.\n(C) Người tham gia thường xuyên làm khảo sát người tiêu dùng.\n(D) Người tham gia thích kem vị trái cây hơn."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following Web page and letter.","passages":["<p>https://www.creategreat.ca/openings</p><p>Create Great, an Ontario-based creative agency with a diverse range of global clients in the fashion industry, is seeking a copywriter who is passionate about fashion, understands market trends, and handles digital tools with ease.</p><p>The ideal candidate will be someone who works well in a fast-paced environment with team members from international backgrounds. The copywriter will collaborate with the creative team to develop brand strategies that suit customer needs and with the marketing team to ensure the success of brand-based publicity campaigns for current and prospective clients. As remote work is permitted for copywriters, residence in Canada is not required.</p><p>To apply, send your cover letter and résumé to the director of our creative team, Fran Benjamin, Create Great, 838 Colbert Street, London, ON N6B 3P5. Application deadline: August 5.</p>","<p>Annie Smith<br>4810 South Bryant Street<br>Portland, OR 97206</p><p>August 6</p><p>Fran Benjamin<br>Create Great<br>838 Colbert Street<br>London, ON N6B 3P5</p><p>Dear Ms. Benjamin,</p><p>I am writing to apply for the copywriter position at Create Great. As an expert fashion designer who also has writing experience, I believe I would be a valuable addition to your team. Enclosed please find my résumé.</p><p>I have a decade of experience as the lead designer for women's collections at MODA, a clothing line in Portland. I oversee the design production process from initial market research to finished product. In my role, I work in close partnership with the marketing and production teams.</p><p>In addition, for the last five years, I have been maintaining my own blog. My posts focus on trends in women's fashion and how to make clothing and cosmetics more sustainable. What started as a hobby has now attracted paying advertisers and over 15,000 followers. Visit www.medesheen.com for examples of my writing.</p><p>Thank you for considering my application.</p><p>Sincerely,</p><p><i>Annie Smith</i><br>Annie Smith</p><p>Enclosure</p>"],"vi":"https://www.creategreat.ca/openings\n\nCreate Great, một công ty sáng tạo có trụ sở tại Ontario với nhiều khách hàng toàn cầu đa dạng trong ngành thời trang, đang tìm một người viết nội dung quảng cáo (copywriter) đam mê thời trang, hiểu các xu hướng thị trường và sử dụng thành thạo các công cụ kỹ thuật số.\n\nỨng viên lý tưởng là người làm việc tốt trong môi trường nhịp độ nhanh cùng các thành viên đến từ nhiều quốc gia. Người viết nội dung sẽ hợp tác với nhóm sáng tạo để xây dựng các chiến lược thương hiệu phù hợp với nhu cầu khách hàng, và với nhóm marketing để đảm bảo thành công cho các chiến dịch quảng bá thương hiệu dành cho khách hàng hiện tại và tiềm năng. Vì người viết nội dung được phép làm việc từ xa, nên không bắt buộc phải cư trú tại Canada.\n\nĐể ứng tuyển, hãy gửi thư xin việc và sơ yếu lý lịch cho giám đốc nhóm sáng tạo của chúng tôi, Fran Benjamin, Create Great, 838 Colbert Street, London, ON N6B 3P5. Hạn nộp hồ sơ: ngày 5 tháng 8.\n\n---\n\nAnnie Smith\n4810 South Bryant Street\nPortland, OR 97206\n\nNgày 6 tháng 8\n\nFran Benjamin\nCreate Great\n838 Colbert Street\nLondon, ON N6B 3P5\n\nKính gửi cô Benjamin,\n\nTôi viết thư này để ứng tuyển vị trí người viết nội dung quảng cáo tại Create Great. Là một nhà thiết kế thời trang chuyên nghiệp đồng thời có kinh nghiệm viết lách, tôi tin rằng mình sẽ là một thành viên có giá trị cho đội ngũ của cô. Xin gửi kèm sơ yếu lý lịch của tôi.\n\nTôi có mười năm kinh nghiệm làm nhà thiết kế chính cho các bộ sưu tập nữ tại MODA, một dòng thời trang ở Portland. Tôi giám sát quy trình sản xuất thiết kế từ khâu nghiên cứu thị trường ban đầu đến thành phẩm. Trong vai trò này, tôi hợp tác chặt chẽ với các nhóm marketing và sản xuất.\n\nNgoài ra, trong năm năm qua, tôi đã duy trì blog riêng của mình. Các bài viết của tôi tập trung vào xu hướng thời trang nữ và cách làm cho quần áo, mỹ phẩm bền vững hơn. Khởi đầu chỉ là sở thích, giờ đây blog đã thu hút các nhà quảng cáo trả phí và hơn 15.000 người theo dõi. Hãy truy cập www.medesheen.com để xem các bài viết mẫu của tôi.\n\nCảm ơn cô đã xem xét đơn ứng tuyển của tôi.\n\nTrân trọng,\nAnnie Smith\n\nTài liệu gửi kèm","qs":[{"n":181,"q":"According to the Web page, what will the job recipient be able to do?","qvi":"Theo trang web, người nhận được công việc sẽ có thể làm gì?","opts":["Work remotely","Manage a team","Travel internationally","Relocate to Canada"],"ans":"A","xp":"Câu hỏi chi tiết. Trang web: \"As remote work is permitted for copywriters, residence in Canada is not required.\" → được phép làm việc từ xa = \"Work remotely\".\n(D) sai: không cần cư trú ở Canada. (B), (C) không được nhắc đến.\n(A) Làm việc từ xa\n(B) Quản lý một nhóm\n(C) Đi công tác quốc tế\n(D) Chuyển đến sống ở Canada"},{"n":182,"q":"On the Web page, the word \"suit\" in paragraph 2, line 4, is closest in meaning to","qvi":"Trên trang web, từ \"suit\" ở đoạn 2, dòng 4 gần nghĩa nhất với","opts":["adapt","determine","invest","satisfy"],"ans":"D","xp":"Câu hỏi đồng nghĩa. Câu gốc: \"develop brand strategies that suit customer needs\" = xây dựng chiến lược thương hiệu phù hợp với / đáp ứng nhu cầu khách hàng. \"suit needs\" ≈ \"satisfy needs\" (đáp ứng, thỏa mãn nhu cầu) → chọn (D).\n(A) adapt: thích nghi, điều chỉnh\n(B) determine: xác định, quyết định\n(C) invest: đầu tư\n(D) satisfy: đáp ứng, làm hài lòng"},{"n":183,"q":"What is indicated about Ms. Smith?","qvi":"Điều gì được nêu về cô Smith?","opts":["She has already met Ms. Benjamin.","She has worked as a copywriter.","She missed an application deadline.","She forgot to submit a required document."],"ans":"C","xp":"Câu hỏi liên kết 2 đoạn. Trang web: \"Application deadline: August 5.\" Thư của cô Smith đề ngày \"August 6\" → cô ấy đã nộp sau hạn chót = lỡ hạn nộp hồ sơ.\n(B) sai: cô là nhà thiết kế thời trang có kinh nghiệm viết (blog), không nói từng làm copywriter. (D) sai: cô gửi kèm résumé (\"Enclosed please find my résumé\") cùng thư xin việc. (A) không có thông tin.\n(A) Cô ấy đã gặp cô Benjamin rồi.\n(B) Cô ấy từng làm người viết nội dung quảng cáo.\n(C) Cô ấy đã lỡ hạn nộp hồ sơ.\n(D) Cô ấy quên nộp một tài liệu bắt buộc."},{"n":184,"q":"According to the letter, what is one of Ms. Smith's responsibilities at MODA?","qvi":"Theo bức thư, một trong những trách nhiệm của cô Smith tại MODA là gì?","opts":["Hiring fashion designers","Writing drafts of advertisements","Managing a production process","Researching sustainable clothing options"],"ans":"C","xp":"Câu hỏi chi tiết. Thư: \"I oversee the design production process from initial market research to finished product.\" → \"oversee\" (giám sát) ≈ \"manage\" (quản lý) → \"Managing a production process\".\n(D) sai: thời trang bền vững là chủ đề trên blog cá nhân, không phải công việc ở MODA. (A), (B) không được nhắc đến.\n(A) Tuyển dụng nhà thiết kế thời trang\n(B) Viết bản nháp quảng cáo\n(C) Quản lý một quy trình sản xuất\n(D) Nghiên cứu các lựa chọn quần áo bền vững"},{"n":185,"q":"What most likely is Medesheen?","qvi":"Medesheen nhiều khả năng là gì?","opts":["A brand of cosmetics","A fashion blog","An online magazine","An advertising agency"],"ans":"B","xp":"Câu hỏi suy luận. Thư: \"for the last five years, I have been maintaining my own blog. My posts focus on trends in women's fashion... Visit www.medesheen.com for examples of my writing.\" → www.medesheen.com là blog thời trang của cô Smith.\n(A) Một nhãn hiệu mỹ phẩm\n(B) Một blog thời trang\n(C) Một tạp chí trực tuyến\n(D) Một công ty quảng cáo"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mails and receipt.","passages":["<p><b>E-Mail Message</b></p><div class=\"hdr\"><p><b>From:</b> Akihito Nakashima &lt;a.nakashima@gilchristshipping.com&gt;</p><p><b>To:</b> Fowler Office Supplies &lt;support@fowlerofficesupplies.com&gt;</p><p><b>Subject:</b> Order B19849</p><p><b>Date:</b> August 19</p></div><p>To Whom It May Concern,</p><p>Yesterday, I purchased some office supplies on your Web site. I received an e-mail receipt, but the costs are not itemized on it. To satisfy a new company policy, I must give my supervisor a receipt with the charges for each item listed separately. Could you e-mail me such a receipt? If not, is it possible for me to get this information myself from your Web site? Finally, can confirmations for future orders possibly be sent to more than one e-mail address? It would be ideal for my supervisor to automatically receive one.</p><p>Thank you,</p><p>Akihito Nakashima, Executive Assistant<br>Gilchrist Shipping</p>","<p><b>E-Mail Message</b></p><div class=\"hdr\"><p><b>From:</b> Fowler Office Supplies &lt;support@fowlerofficesupplies.com&gt;</p><p><b>To:</b> Akihito Nakashima &lt;a.nakashima@gilchristshipping.com&gt;</p><p><b>Subject:</b> RE: Order B19849</p><p><b>Date:</b> August 19</p><p><b>Attachment:</b> B19849</p></div><p>Dear Mr. Nakashima,</p><p>Attached is the receipt you requested. In apology for the inconvenience, we will provide you with 10 percent off the total price of your next order. To view a full description of any previous order, first log in to your account on our Web site, go to the \"My Orders\" tab, and then click on any order number.</p><p>I noticed that included in each of your last few orders was an identical order for ten of a particular item. You should know that we will reduce the price for that item by 5 percent if you mark this as a recurring order. To do this, simply check the \"Recurring Order\" box on the online order form.</p><p>As for your final query, this is not possible right now. However, I will share the idea with our technical team.</p><p>All the best,</p><p>Cameron Higgins, Customer Relations<br>Fowler Office Supplies</p>","<h3>Fowler Office Supplies</h3><p>Receipt for Order: B19849<br>Order Date: August 18</p><table><tr><th>Item</th><th>Price</th><th>Quantity</th><th>Total</th></tr><tr><td>Printer paper</td><td>$8.00/500 sheets</td><td>10</td><td>$ 80.00</td></tr><tr><td>Toner (black)</td><td>$50.00/cartridge</td><td>1</td><td>$ 50.00</td></tr><tr><td>Gel pens (blue)</td><td>$5.00/8-pack</td><td>3</td><td>$ 15.00</td></tr><tr><td>Staples</td><td>$3.50/box</td><td>2</td><td>$ 7.00</td></tr><tr><td colspan=\"3\"><b>GRAND TOTAL</b></td><td><b>$152.00</b></td></tr></table><p>Return Policy: Unopened merchandise may be returned by mail or in one of our stores within 60 days of purchase. For returns by mail, log in to your www.fowlerofficesupplies.com account to print a shipping label. For in-store returns, bring the item and the order number to any Fowler Office Supplies location.</p>"],"vi":"Từ: Akihito Nakashima <a.nakashima@gilchristshipping.com>\nĐến: Fowler Office Supplies <support@fowlerofficesupplies.com>\nTiêu đề: Đơn hàng B19849\nNgày: 19 tháng 8\n\nKính gửi quý công ty,\n\nHôm qua, tôi đã mua một số văn phòng phẩm trên trang web của quý công ty. Tôi đã nhận được biên lai qua e-mail, nhưng chi phí không được liệt kê theo từng món. Để tuân thủ một chính sách mới của công ty, tôi phải nộp cho cấp trên một biên lai có liệt kê riêng chi phí của từng món hàng. Quý công ty có thể gửi e-mail cho tôi một biên lai như vậy không? Nếu không, tôi có thể tự lấy thông tin này từ trang web không? Cuối cùng, xác nhận cho các đơn hàng sau này có thể được gửi đến nhiều hơn một địa chỉ e-mail không? Sẽ rất lý tưởng nếu cấp trên của tôi tự động nhận được một bản.\n\nCảm ơn,\nAkihito Nakashima, Trợ lý điều hành\nGilchrist Shipping\n\n---\n\nTừ: Fowler Office Supplies <support@fowlerofficesupplies.com>\nĐến: Akihito Nakashima <a.nakashima@gilchristshipping.com>\nTiêu đề: TL: Đơn hàng B19849\nNgày: 19 tháng 8\nTệp đính kèm: B19849\n\nKính gửi ông Nakashima,\n\nĐính kèm là biên lai ông yêu cầu. Để xin lỗi vì sự bất tiện, chúng tôi sẽ giảm 10% tổng giá trị đơn hàng tiếp theo của ông. Để xem mô tả đầy đủ của bất kỳ đơn hàng nào trước đây, trước tiên hãy đăng nhập vào tài khoản của ông trên trang web của chúng tôi, vào thẻ \"My Orders\" (Đơn hàng của tôi), rồi nhấp vào số đơn hàng bất kỳ.\n\nTôi nhận thấy rằng trong mỗi đơn hàng gần đây của ông đều có một khoản đặt giống hệt nhau gồm mười đơn vị của một mặt hàng nhất định. Ông nên biết rằng chúng tôi sẽ giảm 5% giá mặt hàng đó nếu ông đánh dấu đây là đơn hàng định kỳ. Để làm điều này, ông chỉ cần đánh dấu vào ô \"Recurring Order\" (Đơn hàng định kỳ) trên mẫu đặt hàng trực tuyến.\n\nVề câu hỏi cuối cùng của ông, việc này hiện chưa thể thực hiện được. Tuy nhiên, tôi sẽ chia sẻ ý tưởng này với nhóm kỹ thuật của chúng tôi.\n\nChúc ông mọi điều tốt đẹp,\nCameron Higgins, Bộ phận Quan hệ khách hàng\nFowler Office Supplies\n\n---\n\nFOWLER OFFICE SUPPLIES\nBiên lai cho đơn hàng: B19849\nNgày đặt hàng: 18 tháng 8\n\nMón hàng — Đơn giá — Số lượng — Thành tiền\nGiấy in — 8,00 đô/500 tờ — 10 — 80,00 đô\nMực in (đen) — 50,00 đô/hộp mực — 1 — 50,00 đô\nBút gel (xanh) — 5,00 đô/gói 8 cây — 3 — 15,00 đô\nKim bấm — 3,50 đô/hộp — 2 — 7,00 đô\nTỔNG CỘNG: 152,00 đô\n\nChính sách đổi trả: Hàng chưa mở có thể được trả lại qua đường bưu điện hoặc tại một trong các cửa hàng của chúng tôi trong vòng 60 ngày kể từ ngày mua. Đối với trả hàng qua bưu điện, hãy đăng nhập vào tài khoản www.fowlerofficesupplies.com để in nhãn gửi hàng. Đối với trả hàng tại cửa hàng, hãy mang món hàng và số đơn hàng đến bất kỳ cửa hàng Fowler Office Supplies nào.","qs":[{"n":186,"q":"Why did Mr. Nakashima send the e-mail?","qvi":"Tại sao ông Nakashima gửi e-mail?","opts":["He did not receive an item he ordered.","He was mistakenly charged twice for an item.","He received a receipt that was not detailed enough.","He did not get a confirmation e-mail for a purchase he made."],"ans":"C","xp":"Câu hỏi mục đích. E-mail 1: \"I received an e-mail receipt, but the costs are not itemized on it... I must give my supervisor a receipt with the charges for each item listed separately.\" → biên lai không liệt kê chi tiết từng món = \"not detailed enough\".\n(D) sai: ông có nhận e-mail biên lai. (A), (B) không được nhắc đến.\n(A) Ông không nhận được món hàng đã đặt.\n(B) Ông bị tính tiền nhầm hai lần cho một món hàng.\n(C) Ông nhận được biên lai không đủ chi tiết.\n(D) Ông không nhận được e-mail xác nhận cho một lần mua hàng."},{"n":187,"q":"According to the second e-mail, what will Mr. Nakashima receive with his next order?","qvi":"Theo e-mail thứ hai, ông Nakashima sẽ nhận được gì với đơn hàng tiếp theo?","opts":["A catalog","A free pen","A printed receipt","A price discount"],"ans":"D","xp":"Câu hỏi chi tiết. E-mail 2: \"In apology for the inconvenience, we will provide you with 10 percent off the total price of your next order.\" → giảm 10% cho đơn hàng tiếp theo = \"A price discount\".\n(A) Một cuốn danh mục sản phẩm\n(B) Một cây bút miễn phí\n(C) Một biên lai in sẵn\n(D) Một khoản giảm giá"},{"n":188,"q":"For what item does Mr. Higgins suggest that Mr. Nakashima select \"Recurring Order\"?","qvi":"Ông Higgins gợi ý ông Nakashima chọn \"Recurring Order\" cho mặt hàng nào?","opts":["Printer paper","Toner","Gel pens","Staples"],"ans":"A","xp":"Câu hỏi liên kết 2 đoạn. E-mail 2: \"included in each of your last few orders was an identical order for ten of a particular item... we will reduce the price for that item by 5 percent if you mark this as a recurring order.\" Biên lai: chỉ có \"Printer paper\" có số lượng 10 → mặt hàng đó là giấy in.\n(A) Giấy in\n(B) Mực in\n(C) Bút gel\n(D) Kim bấm"},{"n":189,"q":"What will Mr. Higgins ask the technical team to look into?","qvi":"Ông Higgins sẽ nhờ nhóm kỹ thuật xem xét điều gì?","opts":["Improving the Web site's response rate","Providing an option to send receipts to multiple e-mail addresses","Placing a link to customers' order history on the home page","Making return labels printable from any device"],"ans":"B","xp":"Câu hỏi liên kết 2 đoạn. E-mail 2: \"As for your final query, this is not possible right now. However, I will share the idea with our technical team.\" Câu hỏi cuối của ông Nakashima trong e-mail 1: \"can confirmations for future orders possibly be sent to more than one e-mail address?\" → nhóm kỹ thuật sẽ xem xét việc gửi xác nhận/biên lai đến nhiều địa chỉ e-mail (\"more than one\" = \"multiple\").\n(A) Cải thiện tốc độ phản hồi của trang web\n(B) Cung cấp tùy chọn gửi biên lai đến nhiều địa chỉ e-mail\n(C) Đặt đường dẫn đến lịch sử đơn hàng của khách trên trang chủ\n(D) Cho phép in nhãn trả hàng từ bất kỳ thiết bị nào"},{"n":190,"q":"What is needed to return an item at a Fowler Office Supplies store?","qvi":"Cần gì để trả hàng tại một cửa hàng Fowler Office Supplies?","opts":["The original receipt","A credit card number","A confirmation e-mail","The order number"],"ans":"D","xp":"Câu hỏi chi tiết. Biên lai, phần chính sách đổi trả: \"For in-store returns, bring the item and the order number to any Fowler Office Supplies location.\" → cần mang số đơn hàng.\n(A) Biên lai gốc\n(B) Số thẻ tín dụng\n(C) Một e-mail xác nhận\n(D) Số đơn hàng"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following article, Web site, and receipt.","passages":["<h3>Crawford and Duval Opens Brick-and-Mortar Stores</h3><p>HONG KONG (18 February)—Crawford and Duval, the online retailer known for its handcrafted blankets, decorative pillows, and other household goods, has established four brick-and-mortar stores in Hong Kong. Last Monday, the company celebrated the grand opening of boutique stores in Causeway Bay, Discovery Bay, and Sheung Wan in addition to a large department store in Central District. While the boutique stores carry the most popular of the small household goods for which Crawford and Duval is famous, the Central District location also boasts an indoor plant department and an on-site café that features specialty coffees, teas, and light snacks. Moreover, it has a much more extensive selection of the merchandise than what is available through the company's Web site.</p>","<p>https://www.crawfordandduval.com.hk</p><p><u>Home</u> | Best Sellers | Full Catalogue | Shopping Cart</p><h3>Crawford and Duval comes to our loyal shoppers in Hong Kong!</h3><p>Crawford and Duval is pleased to announce the opening of its first brick-and-mortar stores in the following locations: Causeway Bay, Discovery Bay, Sheung Wan, and Central District.</p><p>Since the launch of our online store five years ago, we have helped you to create the living space of your dreams. Now we make it even easier to decorate your home. Each location has an interior designer on staff, so you can consult with an expert in person while you browse our popular items.</p><p>All locations are convenient to public transportation. Our Central District location offers free parking in its attached car park.</p><p>As part of our grand-opening celebration, shoppers who visit one of our stores before 1 March will receive a gift card for HK$70 to use during their visit.</p><p>Members of our online Frequent Purchase Club will receive the same benefits in our stores, including a 10 percent discount on purchases of HK$500 or more.</p>","<h3>Crawford and Duval</h3><p><b>Customer Receipt</b><br><b>Date:</b> 23 February</p><table><tr><th>Item</th><th>Price</th></tr><tr><td>Bamboo table lamp</td><td>HK$1,450.00</td></tr><tr><td>Decorative cushions, set of two</td><td>HK$750.00</td></tr><tr><td>Aloe plant in a 7.5-litre planter</td><td>HK$300.00</td></tr><tr><td>Machine-washable wool blanket</td><td>HK$2,000.00</td></tr><tr><td><b>Sub Total</b></td><td>HK$4,500.00</td></tr><tr><td><b>Less 10%</b></td><td>HK$450.00</td></tr><tr><td><b>TOTAL</b></td><td>HK$4,050.00</td></tr></table><p>☐ <b>Cash</b><br>☐ <b>Gift card number:</b><br>☑ <b>Credit card number:</b> ************5598</p><p><b>Name on the credit card:</b> Mei-Lin Fong</p><p><b>Stop at our in-store café for a treat!</b></p>"],"vi":"CRAWFORD AND DUVAL KHAI TRƯƠNG CÁC CỬA HÀNG TRUYỀN THỐNG\n\nHỒNG KÔNG (18 tháng 2) — Crawford and Duval, nhà bán lẻ trực tuyến nổi tiếng với chăn thủ công, gối trang trí và các đồ gia dụng khác, đã mở bốn cửa hàng truyền thống (cửa hàng thực) tại Hồng Kông. Thứ Hai tuần trước, công ty đã tổ chức lễ khai trương các cửa hàng nhỏ (boutique) ở Causeway Bay, Discovery Bay và Sheung Wan, cùng với một cửa hàng bách hóa lớn ở Central District. Trong khi các cửa hàng nhỏ bày bán những món đồ gia dụng nhỏ được ưa chuộng nhất đã làm nên tên tuổi của Crawford and Duval, thì cửa hàng ở Central District còn có thêm khu cây cảnh trong nhà và một quán cà phê tại chỗ phục vụ cà phê đặc sản, trà và đồ ăn nhẹ. Hơn nữa, cửa hàng này có nhiều mặt hàng phong phú hơn hẳn so với những gì có trên trang web của công ty.\n\n---\n\nhttps://www.crawfordandduval.com.hk\nTrang chủ | Bán chạy nhất | Toàn bộ danh mục | Giỏ hàng\n\nCrawford and Duval đến với các khách hàng thân thiết tại Hồng Kông!\n\nCrawford and Duval vui mừng thông báo khai trương các cửa hàng truyền thống đầu tiên tại những địa điểm sau: Causeway Bay, Discovery Bay, Sheung Wan và Central District.\n\nKể từ khi ra mắt cửa hàng trực tuyến cách đây năm năm, chúng tôi đã giúp bạn tạo nên không gian sống mơ ước. Giờ đây, chúng tôi giúp việc trang trí nhà cửa còn dễ dàng hơn nữa. Mỗi cửa hàng đều có một nhà thiết kế nội thất làm việc tại chỗ, để bạn có thể trực tiếp tham khảo ý kiến chuyên gia trong khi xem các sản phẩm được ưa chuộng của chúng tôi.\n\nTất cả các cửa hàng đều thuận tiện đi lại bằng phương tiện công cộng. Cửa hàng ở Central District có chỗ đậu xe miễn phí trong bãi đậu xe liền kề.\n\nTrong khuôn khổ lễ khai trương, khách hàng đến một trong các cửa hàng của chúng tôi trước ngày 1 tháng 3 sẽ nhận được thẻ quà tặng trị giá 70 đô la Hồng Kông để sử dụng trong lần ghé thăm đó.\n\nThành viên Câu lạc bộ Mua hàng Thường xuyên trực tuyến của chúng tôi sẽ nhận được các quyền lợi tương tự tại cửa hàng, bao gồm giảm giá 10% cho các đơn hàng từ 500 đô la Hồng Kông trở lên.\n\n---\n\nCRAWFORD AND DUVAL\nBiên lai khách hàng\nNgày: 23 tháng 2\n\nĐèn bàn bằng tre — 1.450,00 HK$\nGối trang trí, bộ hai chiếc — 750,00 HK$\nCây nha đam trong chậu 7,5 lít — 300,00 HK$\nChăn len giặt máy được — 2.000,00 HK$\nTạm tính — 4.500,00 HK$\nGiảm 10% — 450,00 HK$\nTỔNG CỘNG — 4.050,00 HK$\n\n☐ Tiền mặt\n☐ Số thẻ quà tặng:\n☑ Số thẻ tín dụng: ************5598\nTên trên thẻ tín dụng: Mei-Lin Fong\n\nHãy ghé quán cà phê trong cửa hàng để thưởng thức món ngon nhé!","qs":[{"n":191,"q":"What is the purpose of the article?","qvi":"Mục đích của bài báo là gì?","opts":["To compare locally made products","To announce store openings","To list changes to a Web site","To review a café"],"ans":"B","xp":"Câu hỏi mục đích. Tiêu đề \"Crawford and Duval Opens Brick-and-Mortar Stores\" và câu đầu: \"Crawford and Duval... has established four brick-and-mortar stores in Hong Kong. Last Monday, the company celebrated the grand opening...\" → thông báo việc khai trương cửa hàng.\n(D) sai: quán cà phê chỉ được nhắc qua như một tiện ích của cửa hàng.\n(A) So sánh các sản phẩm sản xuất trong nước\n(B) Thông báo việc khai trương cửa hàng\n(C) Liệt kê những thay đổi của một trang web\n(D) Đánh giá một quán cà phê"},{"n":192,"q":"What does the Web site indicate about Crawford and Duval?","qvi":"Trang web cho biết điều gì về Crawford and Duval?","opts":["It has store locations around the world.","It has been in business for ten years.","It employs interior designers.","It offers free parking at all of its stores."],"ans":"C","xp":"Câu hỏi chi tiết. Trang web: \"Each location has an interior designer on staff\" → mỗi cửa hàng có nhà thiết kế nội thất trong đội ngũ nhân viên = công ty thuê nhà thiết kế nội thất.\n(A) sai: các cửa hàng đều ở Hồng Kông. (B) sai: cửa hàng trực tuyến ra mắt \"five years ago\". (D) sai: chỉ cửa hàng Central District có bãi đậu xe miễn phí.\n(A) Công ty có cửa hàng khắp thế giới.\n(B) Công ty đã kinh doanh được mười năm.\n(C) Công ty thuê nhà thiết kế nội thất.\n(D) Công ty có chỗ đậu xe miễn phí ở tất cả các cửa hàng."},{"n":193,"q":"According to the receipt, what is indicated about the blanket?","qvi":"Theo biên lai, điều gì được nêu về chiếc chăn?","opts":["It can be washed by machine.","It is made of cotton.","It is queen-sized.","It comes in a set with pillows."],"ans":"A","xp":"Câu hỏi chi tiết. Biên lai ghi: \"Machine-washable wool blanket\" → chăn len có thể giặt bằng máy = \"It can be washed by machine\".\n(B) sai: chăn làm bằng len (wool), không phải cotton. (D) sai: gối (cushions) là món riêng. (C) không có thông tin.\n(A) Chăn có thể giặt bằng máy.\n(B) Chăn làm bằng vải cotton.\n(C) Chăn cỡ queen.\n(D) Chăn đi kèm bộ với gối."},{"n":194,"q":"Where most likely did Ms. Fong make her purchase?","qvi":"Cô Fong nhiều khả năng đã mua hàng ở đâu?","opts":["On a Web site","In a boutique shop","At a café","In a department store"],"ans":"D","xp":"Câu hỏi liên kết (suy luận). Biên lai của cô Fong có \"Aloe plant in a 7.5-litre planter\" (cây nha đam trong chậu) và dòng \"Stop at our in-store café for a treat!\". Bài báo: chỉ cửa hàng Central District (\"a large department store\") mới có \"an indoor plant department and an on-site café\" → cô Fong mua ở cửa hàng bách hóa.\n(A) Trên một trang web\n(B) Tại một cửa hàng nhỏ (boutique)\n(C) Tại một quán cà phê\n(D) Tại một cửa hàng bách hóa"},{"n":195,"q":"What is suggested about Ms. Fong?","qvi":"Điều gì được ngụ ý về cô Fong?","opts":["She often buys food from Crawford and Duval.","She is a member of the Frequent Purchase Club.","She applied a gift card to her purchase.","She shopped during a grand-opening event."],"ans":"B","xp":"Câu hỏi liên kết (suy luận). Trang web: \"Members of our online Frequent Purchase Club will receive... a 10 percent discount on purchases of HK$500 or more.\" Biên lai: tổng phụ HK$4,500 và có dòng \"Less 10%\" → cô Fong được giảm 10% nên nhiều khả năng là thành viên câu lạc bộ.\n(C) sai: ô \"Gift card number\" không được đánh dấu, cô trả bằng thẻ tín dụng. (D) sai: lễ khai trương diễn ra vào \"Last Monday\" trước ngày 18/2, còn cô mua ngày 23/2. (A) không có thông tin.\n(A) Cô ấy thường mua đồ ăn từ Crawford and Duval.\n(B) Cô ấy là thành viên của Câu lạc bộ Mua hàng Thường xuyên.\n(C) Cô ấy đã dùng thẻ quà tặng cho lần mua hàng.\n(D) Cô ấy mua sắm trong một sự kiện khai trương."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following Web pages.","passages":["<p>https://www.osawacorporateteambuilding.com/home</p><p><b>Home</b> | Requests | Reviews | Contact Us</p><h3>Osawa Corporate Team Building</h3><p>Bring your team together to promote cooperation while having fun! Our activities increase job satisfaction and engagement. We do all the planning so you can relax. Simply choose the event that is right for your team.</p><p>Scavenger Hunt—An outdoor game in which teams are given a list of objects to find and photograph with their phone or camera. Group size: 10–50 people. Time: 3 hours.</p><p>Game Day—This is a high-energy game day with fun team activities. This event builds team strength, communication, and problem-solving skills. Group size: 20–500 people.<br>Time: 2 hours.</p><p>Team Painting—Each team member creates a painting outdoors based on a predetermined theme. The paintings are linked together at the end. Group size: 6–30 people. Time: 1–2 hours.</p><p>Robot Building—Your group will be broken into teams. Each team builds a robot to be used in challenges against the others. Group size: 10–30 people. Time: 2–3 hours.</p><p>All Chocolate—Your group will have the chance to use engineering skills to build a tower of chocolate. Then you learn how to make chocolate from a local chocolatier.<br>Group size: 8–150 people. Time: 2 hours.</p><p>Book an event in October and receive 15 percent off.</p>","<p>https://www.osawacorporateteambuilding.com/requests</p><p>Home | <b>Requests</b> | Reviews | Contact Us</p><table><tr><td><b>Name</b></td><td>Alexandra Peterson</td></tr><tr><td><b>Company name</b></td><td>Whitten Tech</td></tr><tr><td><b>E-mail address</b></td><td>apeterson@whittentech.com</td></tr><tr><td><b>Phone</b></td><td>617-555-0123</td></tr><tr><td><b>Location and date of event</b></td><td>Downtown Boston, October 15</td></tr></table><p><b>What events are you interested in? Choose your top three.</b><br>1 Game Day &nbsp; 2 Scavenger Hunt &nbsp; 3 Team Painting</p><p><b>Number of participants</b> 28 people</p><p><b>Additional information</b><br>We are interested in a fun activity for our sales team before the busy selling season begins. We spend a lot of time in the office, so we want an outdoor event.</p><p><b>We will contact you within three business days with a quote and confirmation.</b></p>","<p>https://www.osawacorporateteambuilding.com/reviews</p><p>Home | Requests | <b>Reviews</b> | Contact Us</p><h3>What Our Customers Are Saying</h3><p>Posted by Whitten Tech on October 20</p><p>Our team hired Osawa Corporate Team Building to lead an activity for the sales staff at Whitten Tech. The facilitator of the Scavenger Hunt, Lorenzo Benford, was excellent. The 28 members of our sales team all had positive feedback. They reported that they loved exploring the city, learning about its history, and finding new local attractions, even on a cold and cloudy day. I highly recommend this activity. The only downside was that we did not realize how far we would be walking. It would have been helpful to have an idea of the walking distances so we could have been fully prepared.</p>"],"vi":"https://www.osawacorporateteambuilding.com/home\nTrang chủ | Yêu cầu | Đánh giá | Liên hệ\n\nOSAWA CORPORATE TEAM BUILDING\n\nGắn kết đội ngũ của bạn để thúc đẩy tinh thần hợp tác trong khi vẫn vui vẻ! Các hoạt động của chúng tôi giúp tăng sự hài lòng và gắn bó với công việc. Chúng tôi lo toàn bộ khâu lên kế hoạch để bạn có thể thư giãn. Chỉ cần chọn sự kiện phù hợp với đội của bạn.\n\nTruy tìm kho báu (Scavenger Hunt) — Một trò chơi ngoài trời, trong đó các đội được phát danh sách đồ vật cần tìm và chụp ảnh bằng điện thoại hoặc máy ảnh. Quy mô nhóm: 10–50 người. Thời gian: 3 giờ.\n\nNgày hội trò chơi (Game Day) — Một ngày hội trò chơi sôi động với các hoạt động đồng đội vui nhộn. Sự kiện này giúp xây dựng sức mạnh đội nhóm, kỹ năng giao tiếp và giải quyết vấn đề. Quy mô nhóm: 20–500 người. Thời gian: 2 giờ.\n\nVẽ tranh đồng đội (Team Painting) — Mỗi thành viên vẽ một bức tranh ngoài trời theo một chủ đề định sẵn. Cuối buổi, các bức tranh được ghép nối với nhau. Quy mô nhóm: 6–30 người. Thời gian: 1–2 giờ.\n\nChế tạo rô-bốt (Robot Building) — Nhóm của bạn sẽ được chia thành các đội. Mỗi đội chế tạo một rô-bốt để thi đấu thử thách với các đội khác. Quy mô nhóm: 10–30 người. Thời gian: 2–3 giờ.\n\nTất cả về sô-cô-la (All Chocolate) — Nhóm của bạn sẽ có cơ hội dùng kỹ năng kỹ thuật để xây một tòa tháp bằng sô-cô-la. Sau đó, bạn sẽ học cách làm sô-cô-la từ một thợ làm sô-cô-la địa phương. Quy mô nhóm: 8–150 người. Thời gian: 2 giờ.\n\nĐặt sự kiện trong tháng 10 và được giảm 15%.\n\n---\n\nhttps://www.osawacorporateteambuilding.com/requests\nTrang chủ | Yêu cầu | Đánh giá | Liên hệ\n\nHọ tên: Alexandra Peterson\nTên công ty: Whitten Tech\nĐịa chỉ e-mail: apeterson@whittentech.com\nĐiện thoại: 617-555-0123\nĐịa điểm và ngày tổ chức sự kiện: Trung tâm Boston, ngày 15 tháng 10\n\nBạn quan tâm đến những sự kiện nào? Hãy chọn ba lựa chọn hàng đầu.\n1 Game Day  2 Scavenger Hunt  3 Team Painting\n\nSố người tham gia: 28 người\n\nThông tin thêm: Chúng tôi muốn một hoạt động vui vẻ cho đội bán hàng trước khi mùa bán hàng cao điểm bắt đầu. Chúng tôi dành nhiều thời gian trong văn phòng, nên chúng tôi muốn một sự kiện ngoài trời.\n\nChúng tôi sẽ liên hệ với bạn trong vòng ba ngày làm việc kèm theo báo giá và xác nhận.\n\n---\n\nhttps://www.osawacorporateteambuilding.com/reviews\nTrang chủ | Yêu cầu | Đánh giá | Liên hệ\n\nKHÁCH HÀNG NÓI GÌ VỀ CHÚNG TÔI\nĐăng bởi Whitten Tech ngày 20 tháng 10\n\nĐội của chúng tôi đã thuê Osawa Corporate Team Building tổ chức một hoạt động cho nhân viên bán hàng của Whitten Tech. Người điều phối trò Truy tìm kho báu, Lorenzo Benford, rất xuất sắc. Cả 28 thành viên đội bán hàng của chúng tôi đều phản hồi tích cực. Họ cho biết họ rất thích khám phá thành phố, tìm hiểu lịch sử của nó và tìm ra những điểm tham quan mới ở địa phương, dù hôm đó trời lạnh và nhiều mây. Tôi rất khuyến khích hoạt động này. Điểm trừ duy nhất là chúng tôi không biết trước mình sẽ phải đi bộ xa đến mức nào. Sẽ rất hữu ích nếu chúng tôi được biết trước quãng đường đi bộ để có thể chuẩn bị đầy đủ.","qs":[{"n":196,"q":"What does the first Web page indicate about the Scavenger Hunt?","qvi":"Trang web thứ nhất cho biết điều gì về trò Scavenger Hunt?","opts":["It requires participants to rent a camera.","It concludes with prizes for participants.","It is a suitable activity for indoors.","It takes three hours to complete."],"ans":"D","xp":"Câu hỏi chi tiết. Trang web 1: \"Scavenger Hunt—... Group size: 10–50 people. Time: 3 hours.\" → mất ba giờ để hoàn thành.\n(A) sai: chụp ảnh \"with their phone or camera\", không yêu cầu thuê máy ảnh. (C) sai: đây là \"An outdoor game\" (trò chơi ngoài trời). (B) không được nhắc đến.\n(A) Người tham gia phải thuê máy ảnh.\n(B) Trò chơi kết thúc bằng phần thưởng cho người tham gia.\n(C) Đây là hoạt động phù hợp trong nhà.\n(D) Trò chơi mất ba giờ để hoàn thành."},{"n":197,"q":"What event is best for a group of more than 200 people?","qvi":"Sự kiện nào phù hợp nhất cho một nhóm hơn 200 người?","opts":["Game Day","Team Painting","Robot Building","All Chocolate"],"ans":"A","xp":"Câu hỏi chi tiết. Trang web 1: chỉ Game Day có \"Group size: 20–500 people\" → phù hợp cho nhóm hơn 200 người.\nCác lựa chọn khác: Team Painting 6–30, Robot Building 10–30, All Chocolate 8–150 người → đều không đủ.\n(A) Ngày hội trò chơi\n(B) Vẽ tranh đồng đội\n(C) Chế tạo rô-bốt\n(D) Tất cả về sô-cô-la"},{"n":198,"q":"What is suggested about Ms. Peterson?","qvi":"Điều gì được ngụ ý về cô Peterson?","opts":["She has joined the Building Robots event in the past.","She will receive a discount on an event.","She recently started a job at Whitten Tech.","She used to be an event planner."],"ans":"B","xp":"Câu hỏi liên kết (suy luận). Trang web 1: \"Book an event in October and receive 15 percent off.\" Trang yêu cầu của cô Peterson: \"Downtown Boston, October 15\" → sự kiện vào tháng 10 nên cô sẽ được giảm giá.\n(A), (C), (D) không có thông tin.\n(A) Cô ấy từng tham gia sự kiện chế tạo rô-bốt.\n(B) Cô ấy sẽ được giảm giá cho một sự kiện.\n(C) Cô ấy mới bắt đầu làm việc tại Whitten Tech.\n(D) Cô ấy từng là người lên kế hoạch sự kiện."},{"n":199,"q":"What can be concluded about Whitten Tech?","qvi":"Có thể kết luận gì về Whitten Tech?","opts":["It changed its number of event participants.","It provided its staff with free passes to museums.","It was unable to schedule its first-choice activity.","It was not able to hold its event outside."],"ans":"C","xp":"Câu hỏi liên kết (suy luận). Trang yêu cầu: lựa chọn số 1 là \"Game Day\", số 2 là \"Scavenger Hunt\". Bài đánh giá: \"The facilitator of the Scavenger Hunt, Lorenzo Benford, was excellent.\" → Whitten Tech cuối cùng tham gia Scavenger Hunt (lựa chọn thứ 2), tức là không đặt được lựa chọn đầu tiên.\n(A) sai: đăng ký 28 người và đánh giá cũng nói \"The 28 members\". (D) sai: họ đi khám phá thành phố ngoài trời. (B) không được nhắc đến.\n(A) Công ty đã thay đổi số người tham gia sự kiện.\n(B) Công ty đã tặng nhân viên vé vào cửa bảo tàng miễn phí.\n(C) Công ty không đặt được hoạt động mình chọn đầu tiên.\n(D) Công ty không thể tổ chức sự kiện ngoài trời."},{"n":200,"q":"According to the review, what was disappointing about the event?","qvi":"Theo bài đánh giá, điều gì đáng thất vọng về sự kiện?","opts":["The focus on local history","The lack of information about walking distances","The difficulty in keeping the group together","The uninteresting facilitator"],"ans":"B","xp":"Câu hỏi chi tiết. Bài đánh giá: \"The only downside was that we did not realize how far we would be walking. It would have been helpful to have an idea of the walking distances...\" → điểm trừ là thiếu thông tin về quãng đường đi bộ.\n(A) sai: nhân viên \"loved... learning about its history\". (D) sai: người điều phối \"was excellent\". (C) không được nhắc đến.\n(A) Việc tập trung vào lịch sử địa phương\n(B) Việc thiếu thông tin về quãng đường đi bộ\n(C) Khó khăn trong việc giữ cả nhóm đi cùng nhau\n(D) Người điều phối nhàm chán"}]}]}};
